// The bar and the flyouts can use different materials. Windows identify their
// surface by HWND: the wide bar popup is the TopBar, every other XAML popup is
// a flyout.
static TopBarBackdropMode BackdropModeForWindow(HWND hwnd) {
    if (hwnd && (hwnd == g_topBarPopupHwnd || hwnd == g_topBarHwnd ||
                 hwnd == g_islandHwnd)) {
        return g_topBarBackdropMode.load();
    }
    return g_flyoutBackdropMode.load();
}
static bool AnyBackdropActive() {
    return g_topBarBackdropMode.load() != TopBarBackdropMode::None ||
           g_flyoutBackdropMode.load() != TopBarBackdropMode::None;
}
// True when the given material needs dark-on-light text because Windows is
// currently rendering the light variant of it.
static bool BackdropUsesLightMaterial(TopBarBackdropMode mode);

