void PromoteChildFlyoutPopups();

extern std::vector<winrt::weak_ref<FrameworkElement>> g_detachedStyleRoots;
void PruneDetachedStyleRoots();
void RegisterDetachedStyleRoot(FrameworkElement const& root);
void UnregisterDetachedStyleRoot(FrameworkElement const& root);
extern bool g_applyingStyles;
[[clang::no_destroy]] static std::map<void*, winrt::weak_ref<FrameworkElement>> g_immediateFlyoutStyleRoots;

static void ForgetImmediateFlyoutStyleRoot(wuxc::Primitives::FlyoutBase const& flyout) {
    auto it = g_immediateFlyoutStyleRoots.find(winrt::get_abi(flyout));
    if (it == g_immediateFlyoutStyleRoots.end()) return;
    auto root = it->second.get();
    g_immediateFlyoutStyleRoots.erase(it);
    if (!root) {
        PruneDetachedStyleRoots();
        return;
    }
    for (auto const& owner : g_immediateFlyoutStyleRoots) {
        if (owner.second.get() == root) return;
    }
    UnregisterDetachedStyleRoot(root);
}

static void StylePopupImmediately(wuxc::Primitives::FlyoutBase const& flyout, FrameworkElement const& hint = nullptr) {
    if (g_applyingStyles) {
        if (flyout) {
            RunOnUiThread([flyout, hint] {
                if (flyout && flyout.IsOpen()) StylePopupImmediately(flyout, hint);
            });
        }
        return;
    }
    FrameworkElement content=hint;
    if(!content){
        if(auto controlFlyout=flyout.try_as<wuxc::Flyout>())content=controlFlyout.Content().try_as<FrameworkElement>();
        else if(auto menu=flyout.try_as<wuxc::MenuFlyout>()){
            for(auto item:menu.Items())if(auto element=item.try_as<FrameworkElement>()){content=element;break;}
        }
    }
    if(!content)return;

    FrameworkElement root = content;
    DependencyObject current = content;
    while (!current.try_as<wuxc::FlyoutPresenter>() &&
           !current.try_as<wuxc::MenuFlyoutPresenter>()) {
        auto parent = wuxm::VisualTreeHelper::GetParent(current);
        if (!parent) break;
        if (parent.try_as<wuxc::FlyoutPresenter>() ||
            parent.try_as<wuxc::MenuFlyoutPresenter>()) {
            root = parent.as<FrameworkElement>();
            break;
        }
        current = parent;
    }
    auto key = winrt::get_abi(flyout);
    auto existing = g_immediateFlyoutStyleRoots.find(key);
    if (existing != g_immediateFlyoutStyleRoots.end()) {
        if (existing->second.get() == root) {
            return;
        }
        ForgetImmediateFlyoutStyleRoot(flyout);
    }
    g_immediateFlyoutStyleRoots.insert_or_assign(key, winrt::make_weak(root));
    RegisterDetachedStyleRoot(root);
    ApplyControlStylesToPopupRoot(root);
}

void RegisterOpenPopup(wuxc::Primitives::FlyoutBase const& fb) {
    if (!fb) return;
    std::lock_guard<std::mutex> lock(g_openPopupMutex);
    for (auto const& existing : g_openPopups) {
        if (existing == fb) return;
    }
    g_openPopups.push_back(fb);
    g_anyChildFlyoutOpen = true;
    static std::set<void*> s_closingGuardInstalled;
    if (s_closingGuardInstalled.insert(winrt::get_abi(fb)).second) {
        try {
            fb.Closing([](wuxc::Primitives::FlyoutBase const&,
                          wuxc::Primitives::FlyoutBaseClosingEventArgs const& args) {
                if (g_forceClosingFlyouts.load()) return;
                if (!g_settings.disableFlyoutAutoClose) return;
                if ((GetAsyncKeyState(VK_ESCAPE) & 0x8000) != 0) return;
                ULONGLONG lastForeign = g_lastForeignClickTick.load();
                if (lastForeign != 0 &&
                    GetTickCount64() - lastForeign < 800) {
                    args.Cancel(true);
                    return;
                }
                HWND fg = GetForegroundWindow();
                DWORD fgPid = 0;
                if (fg) GetWindowThreadProcessId(fg, &fgPid);
                if (fgPid != GetCurrentProcessId()) {
                    args.Cancel(true);
                }
            });
        } catch (...) {}
    }
    RunOnUiThread([fb] {
        try { StripFlyoutPopupBackgrounds(fb); } catch (...) {}
        try { PromoteChildFlyoutPopups(); } catch (...) {}
        RunOnUiThread([fb] {
            try { StripFlyoutPopupBackgrounds(fb); } catch (...) {}
            try { PromoteChildFlyoutPopups(); } catch (...) {}
        });
    });
}

HWND FindTopBarFlyoutHwnd();

std::atomic<bool> g_liveNotifPopupOpen{ false };

void HideOrphanXamlPopups() {
    if (g_anyChildFlyoutOpen.load() || g_liveNotifPopupOpen.load() || g_creatingTopBarPopup.load() ||
        g_startSearchHandoffAtomic.load() ||
        GetTickCount64() < g_flyoutOpeningGraceUntil.load()) {
        return;
    }
    try {
        if ((g_startMenuFlyout && g_startMenuFlyout.IsOpen()) ||
            (g_searchFlyout && g_searchFlyout.IsOpen())) {
            return;
        }
    } catch (...) {}
    HWND topBarPopup = g_topBarPopupHwnd;
    if (!topBarPopup || !IsWindow(topBarPopup)) topBarPopup = FindTopBarFlyoutHwnd();
    EnumWindows([](HWND hwnd, LPARAM lp) -> BOOL {
        HWND topBarPopup = reinterpret_cast<HWND>(lp);
        if (hwnd == g_islandHwnd) return TRUE;
        if (hwnd == g_topBarHwnd) return TRUE;
        if (topBarPopup && hwnd == topBarPopup) return TRUE;
        if (IsXamlPopupOwnedBySettingsWindow(hwnd)) return TRUE;
        DWORD pid = 0;
        GetWindowThreadProcessId(hwnd, &pid);
        if (pid != GetCurrentProcessId()) return TRUE;
        if (!IsWindowVisible(hwnd)) return TRUE;
        wchar_t cls[256]{};
        if (!GetClassName(hwnd, cls, ARRAYSIZE(cls))) return TRUE;
        if (!(wcsstr(cls, L"Xaml") && wcsstr(cls, L"Popup"))) return TRUE;
        RECT r{};
        if (GetWindowRect(hwnd, &r)) {
            RECT mr = GetBarMonitorRect();
            LONG w = r.right - r.left;
            LONG h = r.bottom - r.top;
            LONG monW = mr.right - mr.left;
            if ((w >= monW / 3 && h <= g_barHeightPx + 64) ||
                (r.top <= mr.top + 32 && w >= monW / 2)) {
                return TRUE;
            }
        }
        ShowWindow(hwnd, SW_HIDE);
        return TRUE;
    }, reinterpret_cast<LPARAM>(topBarPopup));
}

void SweepStaleXamlPopups() {
    if (InterlockedCompareExchange(&g_shuttingDown, 0, 0) != 0) return;
    if (g_liveNotifPopupOpen.load() || g_creatingTopBarPopup.load() || g_startSearchHandoffAtomic.load() ||
        GetTickCount64() < g_flyoutOpeningGraceUntil.load()) {
        return;
    }
    try {
        if ((g_startMenuFlyout && g_startMenuFlyout.IsOpen()) ||
            (g_searchFlyout && g_searchFlyout.IsOpen())) {
            return;
        }
    } catch (...) {}

    bool anyOpen = false;
    {
        std::lock_guard<std::mutex> lock(g_openPopupMutex);
        auto it = g_openPopups.begin();
        while (it != g_openPopups.end()) {
            bool alive = false;
            if (*it) {
                try { alive = (*it).IsOpen(); } catch (...) { alive = false; }
            }
            if (!alive) {
                it = g_openPopups.erase(it);
            } else {
                anyOpen = true;
                ++it;
            }
        }
        g_anyChildFlyoutOpen = anyOpen;
    }
    if (anyOpen) return;

    struct Ctx { HWND topBarPopup; RECT mr; };
    Ctx ctx{ g_topBarPopupHwnd, GetBarMonitorRect() };
    if (!ctx.topBarPopup || !IsWindow(ctx.topBarPopup)) ctx.topBarPopup = FindTopBarFlyoutHwnd();

    EnumWindows([](HWND hwnd, LPARAM lp) -> BOOL {
        auto* c = reinterpret_cast<Ctx*>(lp);
        if (hwnd == g_islandHwnd) return TRUE;
        if (hwnd == g_topBarHwnd) return TRUE;
        if (c->topBarPopup && hwnd == c->topBarPopup) return TRUE;
        if (IsXamlPopupOwnedBySettingsWindow(hwnd)) return TRUE;
        DWORD pid = 0;
        GetWindowThreadProcessId(hwnd, &pid);
        if (pid != GetCurrentProcessId()) return TRUE;
        if (!IsWindowVisible(hwnd)) return TRUE;
        wchar_t cls[256]{};
        if (!GetClassName(hwnd, cls, ARRAYSIZE(cls))) return TRUE;
        if (!(wcsstr(cls, L"Xaml") && wcsstr(cls, L"Popup"))) return TRUE;
        RECT r{};
        if (GetWindowRect(hwnd, &r)) {
            LONG w = r.right - r.left;
            LONG h = r.bottom - r.top;
            LONG monW = c->mr.right - c->mr.left;
            if ((w >= monW / 3 && h <= g_barHeightPx + 64) ||
                (r.top <= c->mr.top + 32 && w >= monW / 2)) {
                return TRUE;
            }
        }
        ShowWindow(hwnd, SW_HIDE);
        return TRUE;
    }, reinterpret_cast<LPARAM>(&ctx));
}

void UnregisterOpenPopup(wuxc::Primitives::FlyoutBase const& fb) {
    if (!fb) return;
    std::lock_guard<std::mutex> lock(g_openPopupMutex);
    g_openPopups.erase(
        std::remove_if(g_openPopups.begin(), g_openPopups.end(),
                       [&](auto const& e) { return e == fb; }),
        g_openPopups.end());
    g_anyChildFlyoutOpen = !g_openPopups.empty();
    if (g_openPopups.empty()) {
        extern void ClearChildPopupTargets();
        ClearChildPopupTargets();
        RunOnUiThread([] {
            try { HideOrphanXamlPopups(); } catch (...) {}
            RunOnUiThread([] {
                try { HideOrphanXamlPopups(); } catch (...) {}
            });
        });
    }
}

