FrameworkElement BuildWindows11StartIcon(double displaySize) {
    std::wstring brush = GetEffectiveIconColorString();

    constexpr PCWSTR kStartLogoPath =
        L"F1 "
        L"M3,1 L9,1 A2,2 0 0 1 11,3 L11,9 A2,2 0 0 1 9,11 L3,11 "
        L"A2,2 0 0 1 1,9 L1,3 A2,2 0 0 1 3,1 Z "
        L"M15,1 L21,1 A2,2 0 0 1 23,3 L23,9 A2,2 0 0 1 21,11 L15,11 "
        L"A2,2 0 0 1 13,9 L13,3 A2,2 0 0 1 15,1 Z "
        L"M3,13 L9,13 A2,2 0 0 1 11,15 L11,21 A2,2 0 0 1 9,23 L3,23 "
        L"A2,2 0 0 1 1,21 L1,15 A2,2 0 0 1 3,13 Z "
        L"M15,13 L21,13 A2,2 0 0 1 23,15 L23,21 A2,2 0 0 1 21,23 L15,23 "
        L"A2,2 0 0 1 13,21 L13,15 A2,2 0 0 1 15,13 Z";

    std::wstring xaml =
        L"<Viewbox xmlns=\"http://schemas.microsoft.com/winfx/2006/xaml/presentation\" "
        L"Stretch=\"Uniform\" Width=\"" + std::to_wstring(displaySize) + L"\" Height=\"" + std::to_wstring(displaySize) + L"\">"
        L"<Path Data=\"" + std::wstring(kStartLogoPath) + L"\" Fill=\"" + brush + L"\"/>"
        L"</Viewbox>";

    try {
        auto element = Markup::XamlReader::Load(xaml).as<FrameworkElement>();
        element.Name(L"StartIcon");
        return element;
    } catch (winrt::hresult_error const& ex) {
        Wh_Log(L"Failed to build Windows 11 start icon: %08X",
               static_cast<unsigned int>(ex.code().value));
        return nullptr;
    }
}

FrameworkElement BuildVectorIcon(PCWSTR name,
                                 std::wstring_view fillData,
                                 std::wstring_view strokeData,
                                 double viewport,
                                 double displaySize,
                                 double thickness,
                                 PCWSTR brushOverride) {
    std::wstring brush = brushOverride ? brushOverride : GetEffectiveIconColorString();

    std::wstring xaml =
        L"<Viewbox xmlns=\"http://schemas.microsoft.com/winfx/2006/xaml/presentation\" "
        L"Stretch=\"Uniform\" Width=\"" +
        std::to_wstring(displaySize) + L"\" Height=\"" + std::to_wstring(displaySize) + L"\">"
        L"<Grid Width=\"" + std::to_wstring(viewport) + L"\" Height=\"" +
        std::to_wstring(viewport) + L"\">";

    if (!fillData.empty()) {
        xaml += L"<Path Data=\"" + EscapeXmlAttr(fillData) + L"\" Fill=\"" + brush + L"\"/>";
    }
    if (!strokeData.empty()) {
        xaml += L"<Path Data=\"" + EscapeXmlAttr(strokeData) + L"\" Stroke=\"" + brush +
                L"\" StrokeThickness=\"" + std::to_wstring(thickness) +
                L"\" StrokeStartLineCap=\"Round\" StrokeEndLineCap=\"Round\" "
                L"StrokeLineJoin=\"Round\"/>";
    }

    xaml += L"</Grid></Viewbox>";

    try {
        auto element = Markup::XamlReader::Load(xaml).as<FrameworkElement>();
        if (name && *name) {
            element.Name(name);
        }
        return element;
    } catch (winrt::hresult_error const& ex) {
        Wh_Log(L"Failed to build vector icon %s: %08X", name ? name : L"(unnamed)",
               static_cast<unsigned int>(ex.code().value));
        return nullptr;
    }
}




wuxm::SolidColorBrush MakeBrush(uint8_t a, uint8_t r, uint8_t g, uint8_t b) {
    return wuxm::SolidColorBrush(wui::ColorHelper::FromArgb(a, r, g, b));
}

wuxm::SolidColorBrush FontColorBrush(uint8_t alpha = 0xFF) {
    wui::Color c{};
    if (!g_settings.fontColor.empty()) {
        if (TryParseHexColor(g_settings.fontColor, &c) ||
            TryParseNamedColor(g_settings.fontColor, &c)) {
            c = AdaptInkForLightMaterial(c);
            return MakeBrush(alpha, c.R, c.G, c.B);
        }
    }
    // No custom font color: use white, or near-black when a light material
    // would make white text invisible.
    if (ShouldAdaptInkForLightMaterial()) {
        return MakeBrush(alpha, 0x20, 0x20, 0x20);
    }
    return MakeBrush(alpha, 0xFF, 0xFF, 0xFF);
}

wuxm::SolidColorBrush FontColorBrushDimmed() {
    wui::Color c{};
    if (!g_settings.fontColor.empty()) {
        if (TryParseHexColor(g_settings.fontColor, &c) ||
            TryParseNamedColor(g_settings.fontColor, &c)) {
            c = AdaptInkForLightMaterial(c);
            return MakeBrush(0xAA, c.R, c.G, c.B);
        }
    }
    if (ShouldAdaptInkForLightMaterial()) {
        return MakeBrush(0xAA, 0x20, 0x20, 0x20);
    }
    return MakeBrush(0xAA, 0xFF, 0xFF, 0xFF);
}

wuxm::SolidColorBrush IconColorBrush(uint8_t alpha = 0xFF) {
    std::wstring effective = GetEffectiveIconColorString();
    wui::Color c{};
    if (TryParseHexColor(effective, &c) || TryParseNamedColor(effective, &c)) {
        c = AdaptInkForLightMaterial(c);
        return MakeBrush(alpha, c.R, c.G, c.B);
    }
    if (ShouldAdaptInkForLightMaterial()) {
        return MakeBrush(alpha, 0x20, 0x20, 0x20);
    }
    return MakeBrush(alpha, 0xFF, 0xFF, 0xFF);
}

CornerRadius MakeCorner(double radius) {
    return CornerRadius{radius, radius, radius, radius};
}

// Copy TopBarRoot's live geometry onto MicaLayer so the material always tracks
// the bar instead of being a fixed rectangle behind it. Each property is
// re-synced on every layout pass, so moving, resizing, tilting or rounding the
// bar carries the material with it.
//
// A theme can take control of any single property (Width / Height / Margin /
// CornerRadius / Opacity ...) through Control styles. We remember the last value
// we wrote; as soon as the live value differs from it, the user owns that
// property and we stop touching it. That keeps "Auto" behaviour live while
// still letting a theme shrink, offset or hide the layer.
namespace mica_geometry {

struct LastApplied {
    bool hasW = false, hasH = false, hasMargin = false;
    bool hasHAlign = false, hasVAlign = false, hasXform = false;
    bool hasXformOrigin = false, hasOpacity = false, hasCorner = false;
    double w = 0, h = 0;
    Thickness margin{};
    HorizontalAlignment hAlign = HorizontalAlignment::Stretch;
    VerticalAlignment vAlign = VerticalAlignment::Stretch;
    wuxm::Transform xform{nullptr};
    wf::Point xformOrigin{};
    double opacity = 1.0;
    CornerRadius corner{};
};

bool SamePoint(wf::Point a, wf::Point b) {
    return a.X == b.X && a.Y == b.Y;
}

bool SameThickness(Thickness a, Thickness b) {
    return a.Left == b.Left && a.Top == b.Top && a.Right == b.Right &&
           a.Bottom == b.Bottom;
}

bool SameCorner(CornerRadius a, CornerRadius b) {
    return a.TopLeft == b.TopLeft && a.TopRight == b.TopRight &&
           a.BottomRight == b.BottomRight && a.BottomLeft == b.BottomLeft;
}

}  // namespace mica_geometry

void SyncMicaLayerGeometry() {
    using namespace mica_geometry;
    static LastApplied s_last;
    static FrameworkElement s_lastMica{nullptr};

    auto rootIt = g_namedElements.find(L"TopBarRoot");
    auto micaIt = g_namedElements.find(L"MicaLayer");
    if (rootIt == g_namedElements.end() || micaIt == g_namedElements.end()) return;
    auto root = rootIt->second;
    auto mica = micaIt->second;
    if (!root || !mica) return;
    if (s_lastMica != mica) {
        s_last = LastApplied{};
        s_lastMica = mica;
    }

    // We may only write a property while it is still unset or still holds our
    // own last value. Once it differs, a style owns it and we leave it alone.
    // Styles are applied with SetValue, so they show up as local values here.
    auto unset = [](FrameworkElement const& fe, DependencyProperty const& dp) {
        auto v = fe.ReadLocalValue(dp);
        return !v || v == DependencyProperty::UnsetValue();
    };
    auto ownsDouble = [&](FrameworkElement const& fe, DependencyProperty const& dp,
                          bool wrote, double live, double ours) {
        return unset(fe, dp) || (wrote && live == ours);
    };

    try {
        // Width / Height stay "Auto" (unset) unless TopBarRoot pins an explicit
        // size. Leaving them unset makes the layer stretch through the same
        // margin as the bar, which is exactly "same size as TopBarRoot" and
        // keeps tracking live when the bar is resized or its margin changes.
        const double rootW = root.Width();
        const double rootH = root.Height();
        const bool wantW = std::isfinite(rootW);
        const bool wantH = std::isfinite(rootH);
        if (wantW) {
            if (ownsDouble(mica, FrameworkElement::WidthProperty(), s_last.hasW,
                           mica.Width(), s_last.w)) {
                mica.Width(rootW);
                s_last.hasW = true;
                s_last.w = rootW;
            }
        } else if (s_last.hasW &&
                   ownsDouble(mica, FrameworkElement::WidthProperty(), s_last.hasW,
                              mica.Width(), s_last.w)) {
            // Root went back to Auto: release our pin too.
            mica.ClearValue(FrameworkElement::WidthProperty());
            s_last.hasW = false;
        }
        if (wantH) {
            if (ownsDouble(mica, FrameworkElement::HeightProperty(), s_last.hasH,
                           mica.Height(), s_last.h)) {
                mica.Height(rootH);
                s_last.hasH = true;
                s_last.h = rootH;
            }
        } else if (s_last.hasH &&
                   ownsDouble(mica, FrameworkElement::HeightProperty(), s_last.hasH,
                              mica.Height(), s_last.h)) {
            mica.ClearValue(FrameworkElement::HeightProperty());
            s_last.hasH = false;
        }

        auto m = root.Margin();
        if (unset(mica, FrameworkElement::MarginProperty()) ||
            (s_last.hasMargin && SameThickness(mica.Margin(), s_last.margin))) {
            mica.Margin(m);
            s_last.hasMargin = true;
            s_last.margin = m;
        }

        auto ha = root.HorizontalAlignment();
        if (unset(mica, FrameworkElement::HorizontalAlignmentProperty()) ||
            (s_last.hasHAlign && mica.HorizontalAlignment() == s_last.hAlign)) {
            mica.HorizontalAlignment(ha);
            s_last.hasHAlign = true;
            s_last.hAlign = ha;
        }

        auto va = root.VerticalAlignment();
        if (unset(mica, FrameworkElement::VerticalAlignmentProperty()) ||
            (s_last.hasVAlign && mica.VerticalAlignment() == s_last.vAlign)) {
            mica.VerticalAlignment(va);
            s_last.hasVAlign = true;
            s_last.vAlign = va;
        }

        auto t = root.RenderTransform();
        bool xformOurs = unset(mica, UIElement::RenderTransformProperty());
        if (!xformOurs && s_last.hasXform) {
            auto live = mica.RenderTransform();
            xformOurs = (!live && !s_last.xform) ||
                        (live && s_last.xform &&
                         winrt::get_abi(live) == winrt::get_abi(s_last.xform));
        }
        if (xformOurs) {
            mica.RenderTransform(t);
            s_last.hasXform = true;
            s_last.xform = t;
        }

        auto o = root.RenderTransformOrigin();
        if (unset(mica, UIElement::RenderTransformOriginProperty()) ||
            (s_last.hasXformOrigin &&
             SamePoint(mica.RenderTransformOrigin(), s_last.xformOrigin))) {
            mica.RenderTransformOrigin(o);
            s_last.hasXformOrigin = true;
            s_last.xformOrigin = o;
        }

        auto opacity = root.Opacity();
        if (ownsDouble(mica, UIElement::OpacityProperty(), s_last.hasOpacity,
                       mica.Opacity(), s_last.opacity)) {
            mica.Opacity(opacity);
            s_last.hasOpacity = true;
            s_last.opacity = opacity;
        }

        if (auto micaBorder = mica.try_as<wuxc::Border>()) {
            bool cornerOurs =
                unset(micaBorder, wuxc::Border::CornerRadiusProperty());
            if (!cornerOurs && s_last.hasCorner)
                cornerOurs = SameCorner(micaBorder.CornerRadius(), s_last.corner);
            if (cornerOurs) {
                auto radius = static_cast<double>(g_settings.cornerRadius);
                if (auto rootBorder = root.try_as<wuxc::Border>()) {
                    radius = rootBorder.CornerRadius().TopLeft;
                }
                auto cr = MakeCorner(radius);
                micaBorder.CornerRadius(cr);
                s_last.hasCorner = true;
                s_last.corner = cr;
                // The blur/tint layer sits in front of the material and must
                // share its rounding, otherwise its backdrop brush would paint
                // square corners over the rounded material.
                if (auto blurIt = g_namedElements.find(L"GlobalBlurLayer");
                    blurIt != g_namedElements.end()) {
                    if (auto blurBorder = blurIt->second.try_as<wuxc::Border>())
                        blurBorder.CornerRadius(cr);
                }
            }
        }
    } catch (...) {}
}

// Build the material brush painted on MicaLayer. Defined after XamlBlurBrush,
// which it instantiates.
wuxm::Brush CreateBackdropMaterialBrush(UIElement const& element,
                                       TopBarBackdropMode mode);

// Repaint MicaLayer for the current mode and keep its geometry in sync.
void RefreshMicaLayer();

// A Grid or a plain Border cannot round its children, and transparent XAML
// popups still paint square layers behind a rounded shell (the "square blue /
// black layer" seen at the corners). Clip the element to a rounded rectangle
// so nothing can leak past the visible corner radius.
// UWP's RectangleGeometry has no radius properties, so the rounding is done
// with a composition geometric clip on the element visual instead.
void ApplyRoundedClip(FrameworkElement const& element, double radius) {
    if (!element) return;
    try {
        auto visual = wuxh::ElementCompositionPreview::GetElementVisual(element);
        if (!visual) return;
        auto compositor = visual.Compositor();
        auto geometry = compositor.CreateRoundedRectangleGeometry();
        auto resolveRadius = [weakEl = winrt::make_weak(element), radius]() -> float {
            float r = static_cast<float>(radius);
            if (auto fe = weakEl.get()) {
                try {
                    if (auto b = fe.try_as<wuxc::Border>()) {
                        double tl = b.CornerRadius().TopLeft;
                        if (std::isfinite(tl) && tl >= 0.0) r = static_cast<float>(tl);
                    } else if (auto p = fe.try_as<wuxc::Panel>()) {
                        if (p.Children().Size() > 0) {
                            if (auto cb = p.Children().GetAt(0).try_as<wuxc::Border>()) {
                                double tl = cb.CornerRadius().TopLeft;
                                if (std::isfinite(tl) && tl >= 0.0) r = static_cast<float>(tl);
                            }
                        }
                    } else if (auto c = fe.try_as<wuxc::Control>()) {
                        double tl = c.CornerRadius().TopLeft;
                        if (std::isfinite(tl) && tl >= 0.0) r = static_cast<float>(tl);
                    }
                } catch (...) {}
            }
            return std::max(0.0f, r);
        };
        float r0 = resolveRadius();
        geometry.CornerRadius(winrt::Windows::Foundation::Numerics::float2{ r0, r0 });
        auto update = [geometry, resolveRadius](double w, double h) {
            try {
                if (!std::isfinite(w) || !std::isfinite(h) || w <= 0 || h <= 0)
                    return;
                geometry.Size(winrt::Windows::Foundation::Numerics::float2{
                    static_cast<float>(w), static_cast<float>(h)});
                float r = resolveRadius();
                geometry.CornerRadius(winrt::Windows::Foundation::Numerics::float2{ r, r });
            } catch (...) {}
        };
        update(element.ActualWidth(), element.ActualHeight());
        visual.Clip(compositor.CreateGeometricClip(geometry));
        element.SizeChanged([update](auto&& sender, auto&&) {
            try {
                auto fe = sender.template as<FrameworkElement>();
                if (!fe) return;
                update(fe.ActualWidth(), fe.ActualHeight());
            } catch (...) {}
        });
        element.Loaded([update](auto&& sender, auto&&) {
            try {
                auto fe = sender.template as<FrameworkElement>();
                if (!fe) return;
                update(fe.ActualWidth(), fe.ActualHeight());
            } catch (...) {}
        });
        auto hookBorderRadius = [weakEl = winrt::make_weak(element), update](wuxc::Border const& b) {
            if (!b) return;
            try {
                b.RegisterPropertyChangedCallback(
                    wuxc::Border::CornerRadiusProperty(),
                    [weakEl, update](DependencyObject const&, DependencyProperty const&) {
                        if (auto fe = weakEl.get()) {
                            update(fe.ActualWidth(), fe.ActualHeight());
                        }
                    });
            } catch (...) {}
        };
        if (auto b = element.try_as<wuxc::Border>()) {
            hookBorderRadius(b);
        } else if (auto p = element.try_as<wuxc::Panel>()) {
            if (p.Children().Size() > 0) {
                if (auto cb = p.Children().GetAt(0).try_as<wuxc::Border>()) {
                    hookBorderRadius(cb);
                }
            }
        } else if (auto c = element.try_as<wuxc::Control>()) {
            try {
                auto weakEl = winrt::make_weak(element);
                c.RegisterPropertyChangedCallback(
                    wuxc::Control::CornerRadiusProperty(),
                    [weakEl, update](DependencyObject const&, DependencyProperty const&) {
                        if (auto fe = weakEl.get()) {
                            update(fe.ActualWidth(), fe.ActualHeight());
                        }
                    });
            } catch (...) {}
        }
    } catch (...) {}
}

// Shared tint/border constants for every surface that opts in to the standard
// "filled tile" look (action chips, active list rows, control-centre tiles).
// It is opt-in on purpose: a bare ghost button stays fully transparent and
// borderless, because many controls - calendar day cells, search result boxes,
// toggles - paint their own background and would otherwise end up as an empty
// box with a stray hairline border around it.
constexpr uint8_t kUiTintAlpha = 0x20;
constexpr uint8_t kUiBorderAlpha = 0x40;

wuxc::Button MakeGhostButton(PCWSTR name, double cornerRadius) {
    // Silence every XAML UI sound (button invoke / flyout show+hide clicks).
    // Done once, process-wide; the bar must never make noise on its own.
    {
        static bool s_xamlSoundsOff = false;
        if (!s_xamlSoundsOff) {
            s_xamlSoundsOff = true;
            try { ElementSoundPlayer::State(ElementSoundPlayerState::Off); } catch (...) {}
            try { ElementSoundPlayer::Volume(0.0); } catch (...) {}
        }
    }
    wuxc::Button button;
    try { button.ElementSoundMode(ElementSoundMode::Off); } catch (...) {}
    if (name && *name) {
        button.Name(name);
    }
    button.MinHeight(0);
    button.MinWidth(0);
    button.Background(MakeBrush(0, 0, 0, 0));
    button.BorderThickness(Thickness{0, 0, 0, 0});
    button.CornerRadius(MakeCorner(cornerRadius));
    try { button.BackgroundSizing(wuxc::BackgroundSizing::InnerBorderEdge); } catch (...) {}
    button.Padding(Thickness{8, 4, 8, 4});
    button.HorizontalContentAlignment(HorizontalAlignment::Stretch);
    button.VerticalContentAlignment(VerticalAlignment::Center);
    try { button.UseSystemFocusVisuals(false); } catch (...) {}
    try {
        auto res = button.Resources();
        auto transparent = MakeBrush(0, 0, 0, 0);
        auto zero = winrt::box_value(Thickness{0, 0, 0, 0});
        res.Insert(winrt::box_value(winrt::hstring(L"FocusVisualPrimaryBrush")), transparent);
        res.Insert(winrt::box_value(winrt::hstring(L"FocusVisualSecondaryBrush")), transparent);
        res.Insert(winrt::box_value(winrt::hstring(L"FocusVisualPrimaryThickness")), zero);
        res.Insert(winrt::box_value(winrt::hstring(L"FocusVisualSecondaryThickness")), zero);
    } catch (...) {}
    return button;
}

// Windows 11 Taskbar / WinUI 3 Fluent Motion press-down animation:
// ControlFasterAnimationDuration (83 ms) with Fluent fast-out slow-in cubic-bezier(0,0,0,1).
[[clang::no_destroy]] static std::map<void*, winrt::weak_ref<wuxa::Storyboard>> g_activePressStoryboards;

static TopBarPressAnimConfig ResolvePressAnimConfig(FrameworkElement const& fe, float defaultScale) {
    TopBarPressAnimConfig cfg;
    cfg.pressScale = defaultScale;
    std::wstring name;
    try { name = std::wstring(fe.Name()); } catch (...) {}
    std::lock_guard<std::mutex> lock(g_pressAnimConfigMutex);
    auto apply = [&](const std::wstring& key) {
        auto it = g_pressAnimConfigs.find(key);
        if (it == g_pressAnimConfigs.end()) return;
        cfg.enabled = it->second.enabled;
        if (it->second.pressScale > 0.0) cfg.pressScale = it->second.pressScale;
        if (it->second.pressDurationMs >= 0) cfg.pressDurationMs = it->second.pressDurationMs;
        if (it->second.releaseDurationMs >= 0) cfg.releaseDurationMs = it->second.releaseDurationMs;
    };
    apply(L"*");
    apply(L"TopBarRoot");
    if (!name.empty()) apply(name);
    return cfg;
}

static wuxm::CompositeTransform EnsureUwpPressTransform(FrameworkElement const& fe) {
    if (!fe) return nullptr;
    try {
        fe.RenderTransformOrigin(wf::Point{0.5, 0.5});
        if (auto ct = fe.RenderTransform().try_as<wuxm::CompositeTransform>()) {
            return ct;
        }
        wuxm::CompositeTransform ct;
        fe.RenderTransform(ct);
        return ct;
    } catch (...) {
        return nullptr;
    }
}

static void RunUwpScaleStoryboard(FrameworkElement const& fe, double toScale, int durationMs, bool isRelease) {
    if (!fe) return;
    auto ct = EnsureUwpPressTransform(fe);
    if (!ct) return;
    void* key = winrt::get_abi(fe);
    if (auto it = g_activePressStoryboards.find(key); it != g_activePressStoryboards.end()) {
        if (auto prev = it->second.get()) {
            try { prev.Pause(); } catch (...) {}
        }
    }
    if (durationMs <= 0) {
        try {
            ct.ScaleX(toScale);
            ct.ScaleY(toScale);
        } catch (...) {}
        return;
    }
    try {
        wuxa::Storyboard sb;
        wuxa::DoubleAnimation ax;
        wuxa::DoubleAnimation ay;
        ax.To(toScale);
        ay.To(toScale);
        auto dur = winrt::Windows::UI::Xaml::DurationHelper::FromTimeSpan(
            std::chrono::milliseconds(durationMs));
        ax.Duration(dur);
        ay.Duration(dur);
        if (isRelease) {
            wuxa::BackEase back;
            back.EasingMode(wuxa::EasingMode::EaseOut);
            back.Amplitude(0.32);
            ax.EasingFunction(back);
            ay.EasingFunction(back);
        } else {
            wuxa::ExponentialEase ease;
            ease.EasingMode(wuxa::EasingMode::EaseOut);
            ease.Exponent(4.5);
            ax.EasingFunction(ease);
            ay.EasingFunction(ease);
        }
        wuxa::Storyboard::SetTarget(ax, fe);
        wuxa::Storyboard::SetTargetProperty(ax, L"(UIElement.RenderTransform).(CompositeTransform.ScaleX)");
        wuxa::Storyboard::SetTarget(ay, fe);
        wuxa::Storyboard::SetTargetProperty(ay, L"(UIElement.RenderTransform).(CompositeTransform.ScaleY)");
        sb.Children().Append(ax);
        sb.Children().Append(ay);
        if (g_activePressStoryboards.size() > 256) g_activePressStoryboards.clear();
        g_activePressStoryboards[key] = winrt::make_weak(sb);
        sb.Begin();
    } catch (...) {}
}

// UWP Storyboard + CompositeTransform press-down animation (customizable via YAML:
// PressAnimation=none|uwp, PressScale=0.90, PressDuration=83, ReleaseDuration=167).
static void AnimateTopBarButtonPressDown(FrameworkElement const& fe,
                                         float pressScale = 0.90f) {
    if (!fe) return;
    try {
        if (fe.Name() == L"ResourceButton") return;
        auto cfg = ResolvePressAnimConfig(fe, pressScale);
        if (!cfg.enabled) return;
        RunUwpScaleStoryboard(fe, cfg.pressScale, cfg.pressDurationMs, false);
    } catch (...) {}
}

// UWP Storyboard + CompositeTransform spring-like BackEase release animation.
static void AnimateTopBarButtonRelease(FrameworkElement const& fe,
                                       float restScale = 1.0f) {
    if (!fe) return;
    try {
        if (fe.Name() == L"ResourceButton") return;
        auto cfg = ResolvePressAnimConfig(fe, 0.90f);
        if (!cfg.enabled) {
            if (auto ct = fe.RenderTransform().try_as<wuxm::CompositeTransform>()) {
                ct.ScaleX(restScale);
                ct.ScaleY(restScale);
            }
            return;
        }
        RunUwpScaleStoryboard(fe, static_cast<double>(restScale), cfg.releaseDurationMs, true);
    } catch (...) {}
}

static void PlayTopBarPressBounce(FrameworkElement const& fe,
                                  float dipScale = 0.90f,
                                  float restScale = 1.0f) {
    if (!fe) return;
    try {
        double w = fe.ActualWidth();
        double h = fe.ActualHeight();
        if (w <= 1.0) w = fe.Width();
        if (h <= 1.0) h = fe.Height();
        if (!std::isfinite(w) || w <= 1.0) w = 24.0;
        if (!std::isfinite(h) || h <= 1.0) h = 24.0;
        auto visual = wuxh::ElementCompositionPreview::GetElementVisual(fe);
        auto comp = visual.Compositor();
        visual.CenterPoint(winrt::Windows::Foundation::Numerics::float3{
            static_cast<float>(w * 0.5), static_cast<float>(h * 0.5), 0.f});
        auto easeIn = comp.CreateCubicBezierEasingFunction(
            winrt::Windows::Foundation::Numerics::float2{0.0f, 0.0f},
            winrt::Windows::Foundation::Numerics::float2{0.0f, 1.0f});
        auto easeOut = comp.CreateCubicBezierEasingFunction(
            winrt::Windows::Foundation::Numerics::float2{0.16f, 1.0f},
            winrt::Windows::Foundation::Numerics::float2{0.3f, 1.0f});
        auto anim = comp.CreateVector3KeyFrameAnimation();
        anim.InsertKeyFrame(0.38f,
            winrt::Windows::Foundation::Numerics::float3{dipScale, dipScale, 1.0f}, easeIn);
        anim.InsertKeyFrame(1.0f,
            winrt::Windows::Foundation::Numerics::float3{restScale, restScale, 1.0f}, easeOut);
        anim.Duration(std::chrono::milliseconds(220));
        visual.StartAnimation(L"Scale", anim);
    } catch (...) {}
}

static bool IsSourceInsideNestedButton(wuxc::Button const& outerBtn,
                                       wf::IInspectable const& source) {
    if (!outerBtn || !source) return false;
    try {
        DependencyObject cur = source.try_as<DependencyObject>();
        while (cur && cur != outerBtn) {
            if (cur.try_as<wuxc::Primitives::ButtonBase>()) {
                return true;
            }
            cur = wuxm::VisualTreeHelper::GetParent(cur);
        }
    } catch (...) {}
    return false;
}

static void AttachTopBarPressAnimation(wuxc::Button const& btn, float dipScale = 0.90f) {
    if (!btn) return;
    try {
        winrt::weak_ref<wuxc::Button> weakBtn = winrt::make_weak(btn);
        auto pressed = std::make_shared<bool>(false);
        auto pressTick = std::make_shared<ULONGLONG>(0);
        auto pressGen = std::make_shared<uint64_t>(0);
        btn.AddHandler(
            UIElement::PointerPressedEvent(),
            winrt::box_value(Input::PointerEventHandler(
                [weakBtn, dipScale, pressed, pressTick, pressGen](
                    wf::IInspectable const&,
                    Input::PointerRoutedEventArgs const& args) {
                    try {
                        auto pt = args.GetCurrentPoint(nullptr);
                        if (!pt.Properties().IsLeftButtonPressed()) return;
                        auto b = weakBtn.get();
                        if (!b) return;
                        // Never animate the outer button when a nested sub-button
                        // (e.g. Media Prev/Pause/Next or Resource tile) was pressed.
                        if (IsSourceInsideNestedButton(b, args.OriginalSource())) return;
                        *pressed = true;
                        *pressTick = GetTickCount64();
                        ++(*pressGen);
                        AnimateTopBarButtonPressDown(b, dipScale);
                    } catch (...) {}
                })),
            true);
        auto releaseNow = [weakBtn, pressed, pressTick, pressGen]() {
            if (!*pressed) return;
            *pressed = false;
            const uint64_t myGen = *pressGen;
            const ULONGLONG elapsed = GetTickCount64() - *pressTick;
            constexpr ULONGLONG kMinPressHoldMs = 75;
            if (elapsed < kMinPressHoldMs) {
                const DWORD waitMs = static_cast<DWORD>(kMinPressHoldMs - elapsed);
                RunInBackground([weakBtn, pressGen, myGen, waitMs] {
                    if (WaitForSingleObject(g_stopEvent, waitMs) == WAIT_OBJECT_0) return;
                    RunOnUiThread([weakBtn, pressGen, myGen] {
                        if (*pressGen != myGen) return;
                        if (auto b = weakBtn.get()) {
                            AnimateTopBarButtonRelease(b, 1.0f);
                        }
                    });
                });
                return;
            }
            if (auto b = weakBtn.get()) {
                AnimateTopBarButtonRelease(b, 1.0f);
            }
        };
        btn.AddHandler(
            UIElement::PointerReleasedEvent(),
            winrt::box_value(Input::PointerEventHandler(
                [releaseNow](wf::IInspectable const&,
                             Input::PointerRoutedEventArgs const&) {
                    try { releaseNow(); } catch (...) {}
                })),
            true);
        btn.AddHandler(
            UIElement::PointerCaptureLostEvent(),
            winrt::box_value(Input::PointerEventHandler(
                [releaseNow](wf::IInspectable const&,
                             Input::PointerRoutedEventArgs const&) {
                    try { releaseNow(); } catch (...) {}
                })),
            true);
        btn.AddHandler(
            UIElement::PointerExitedEvent(),
            winrt::box_value(Input::PointerEventHandler(
                [releaseNow](wf::IInspectable const&,
                             Input::PointerRoutedEventArgs const&) {
                    try { releaseNow(); } catch (...) {}
                })),
            true);
    } catch (...) {}
}

// Maps the "Bold intensity" setting onto the closest font weight. Windows
// exposes weights as presets (100..900); the setting picks the preset.
winrt::Windows::UI::Text::FontWeight ResolveBoldWeight() {
    using W = winrt::Windows::UI::Text::FontWeights;
    const int requested = g_settings.boldIntensity;
    if (requested <= 250) return W::ExtraLight();
    if (requested <= 350) return W::Light();
    if (requested <= 450) return W::Normal();
    if (requested <= 550) return W::Medium();
    if (requested <= 650) return W::SemiBold();
    if (requested <= 750) return W::Bold();
    if (requested <= 850) return W::ExtraBold();
    return W::Black();
}

wuxc::TextBlock MakeText(PCWSTR name, std::wstring_view text, double size, bool bold,
                         double opacity) {
    wuxc::TextBlock block;
    if (name && *name) {
        block.Name(name);
    }
    block.Text(winrt::hstring(text));
    block.FontSize(size);

    if (!g_settings.fontFamily.empty()) {
        try {
            block.FontFamily(wuxm::FontFamily(winrt::hstring(g_settings.fontFamily)));
        } catch (...) {}
    } else if (IsWinUI3StyleMode()) {
        try {
            block.FontFamily(wuxm::FontFamily(
                size >= 18.0 ? L"Segoe UI Variable Display, Segoe UI"
                             : L"Segoe UI Variable Text, Segoe UI"));
        } catch (...) {}
    }
    if (g_settings.fontBold) {
        block.FontWeight(ResolveBoldWeight());
    } else if (bold) {
        block.FontWeight(IsWinUI3StyleMode()
                             ? winrt::Windows::UI::Text::FontWeights::SemiBold()
                             : ResolveBoldWeight());
    }
    if (!g_settings.fontColor.empty()) {
        wui::Color fontColor{};
        if (TryParseHexColor(g_settings.fontColor, &fontColor) ||
            TryParseNamedColor(g_settings.fontColor, &fontColor)) {
            fontColor = AdaptInkForLightMaterial(fontColor);
            block.Foreground(MakeBrush(fontColor.A, fontColor.R, fontColor.G, fontColor.B));
        }
    }
    block.Opacity(opacity);
    block.VerticalAlignment(VerticalAlignment::Center);
    block.TextTrimming(TextTrimming::CharacterEllipsis);
    return block;
}

wuxc::Border MakeDivider() {
    wuxc::Border border;
    border.Name(L"FlyoutDivider");
    border.Height(1);
    border.Background(MakeBrush(IsWinUI3StyleMode() ? 0x16 : 28, 255, 255, 255));
    border.Margin(Thickness{0, 6, 0, 6});
    return border;
}

