FrameworkElement MakeInlineGlyph(PCWSTR glyph, double fontSize, wuxm::Brush const& fgBrush = nullptr) {
    wuxm::Brush brush = fgBrush ? fgBrush : IconColorBrush();
    wuxc::FontIcon fi;
    try {
        fi.FontFamily(wuxm::FontFamily(L"Segoe Fluent Icons, Segoe MDL2 Assets"));
    } catch (...) {}
    if (glyph && *glyph) fi.Glyph(winrt::hstring(glyph));
    fi.FontSize(fontSize);
    fi.Foreground(brush);
    fi.HorizontalAlignment(HorizontalAlignment::Center);
    fi.VerticalAlignment(VerticalAlignment::Center);
    return fi;
}

FrameworkElement Glyph(PCWSTR glyph, double displaySize, PCWSTR colorHexOverride = nullptr) {
    wui::Color c{};
    bool haveColor = false;
    if (colorHexOverride) {
        if (TryParseHexColor(colorHexOverride, &c) || TryParseNamedColor(colorHexOverride, &c)) {
            haveColor = true;
        }
    }
    wuxm::Brush brush = haveColor ? MakeBrush(c.A, c.R, c.G, c.B) : IconColorBrush();

    wuxc::FontIcon fi;
    fi.Glyph(winrt::hstring(glyph));
    fi.FontSize(32);
    try {
        fi.FontFamily(wuxm::FontFamily(L"Segoe Fluent Icons"));
    } catch (...) {}
    fi.Foreground(brush);
    fi.HorizontalAlignment(HorizontalAlignment::Center);
    fi.VerticalAlignment(VerticalAlignment::Center);

    wuxc::Grid grid;
    grid.MinWidth(32);
    grid.MinHeight(32);
    grid.Padding(Thickness{2, 2, 2, 2});
    grid.Children().Append(fi);

    wuxc::Viewbox vb;
    vb.Stretch(wuxm::Stretch::Uniform);
    vb.Width(displaySize);
    vb.Height(displaySize);
    vb.Child(grid);
    return vb;
}

