void RunOnUiThread(std::function<void()> work) {
    if (InterlockedCompareExchange(&g_shuttingDown, 0, 0) != 0) {
        return;
    }
    auto guarded = [work = std::move(work)]() {
        if (InterlockedCompareExchange(&g_shuttingDown, 0, 0) != 0) {
            return;
        }
        try {
            work();
        } catch (...) {
        }
    };

    if (g_uiDispatcherQueue) {
        g_uiDispatcherQueue.TryEnqueue(guarded);
        return;
    }

    if (g_rootElement) {
        try {
            g_rootElement.Dispatcher().RunAsync(
                winrt::Windows::UI::Core::CoreDispatcherPriority::Normal, guarded);
        } catch (...) {
        }
    }
}

std::atomic<int> g_backgroundJobs{0};
std::vector<HANDLE> g_workerThreads;
std::mutex g_workerThreadsMutex;

void RunInBackground(std::function<void()> work) {
    if (InterlockedCompareExchange(&g_shuttingDown, 0, 0) != 0) {
        return;
    }
    {
        std::lock_guard<std::mutex> lock(g_workerThreadsMutex);
        for (auto it = g_workerThreads.begin(); it != g_workerThreads.end();) {
            if (WaitForSingleObject(*it, 0) == WAIT_OBJECT_0) {
                CloseHandle(*it);
                it = g_workerThreads.erase(it);
            } else {
                ++it;
            }
        }
    }
    g_backgroundJobs.fetch_add(1);
    auto* workPtr = new std::function<void()>(std::move(work));
    HANDLE threadHandle = (HANDLE)_beginthreadex(nullptr, 0, [](void* param) -> unsigned int {
        auto* workPtr = static_cast<std::function<void()>*>(param);
        HRESULT hr = CoInitializeEx(nullptr, COINIT_MULTITHREADED);
        try {
            (*workPtr)();
        } catch (...) {
        }
        if (SUCCEEDED(hr)) {
            CoUninitialize();
        }
        g_backgroundJobs.fetch_sub(1);
        delete workPtr;
        return 0;
    }, workPtr, 0, nullptr);
    if (threadHandle) {
        std::lock_guard<std::mutex> lock(g_workerThreadsMutex);
        g_workerThreads.push_back(threadHandle);
    }
}

std::mutex g_volumeCoalesceMutex;
int g_pendingVolumeValue = -1;
bool g_volumeWorkerRunning = false;
int g_pendingCaptureVolumeValue = -1;
bool g_captureVolumeWorkerRunning = false;

void SetEndpointVolumeCoalesced(EDataFlow flow, int value) {
    const bool capture = (flow == eCapture);
    {
        std::lock_guard<std::mutex> lock(g_volumeCoalesceMutex);
        auto& pending = capture ? g_pendingCaptureVolumeValue : g_pendingVolumeValue;
        auto& running = capture ? g_captureVolumeWorkerRunning : g_volumeWorkerRunning;
        pending = value;
        if (running) {
            return;
        }
        running = true;
    }
    RunInBackground([flow, capture] {
        for (;;) {
            int v;
            {
                std::lock_guard<std::mutex> lock(g_volumeCoalesceMutex);
                auto& pending = capture ? g_pendingCaptureVolumeValue : g_pendingVolumeValue;
                auto& running = capture ? g_captureVolumeWorkerRunning : g_volumeWorkerRunning;
                if (pending < 0) {
                    running = false;
                    return;
                }
                v = pending;
                pending = -1;
            }
            audio::SetEndpointVolume(flow, v);
        }
    });
}

void SetMasterVolumeCoalesced(int value) {
    SetEndpointVolumeCoalesced(eRender, value);
}

void SetCaptureVolumeCoalesced(int value) {
    SetEndpointVolumeCoalesced(eCapture, value);
}

std::mutex g_brightnessCoalesceMutex;
int g_pendingBrightnessValue = -1;
bool g_brightnessWorkerRunning = false;

void SetBrightnessCoalesced(int value) {
    {
        std::lock_guard<std::mutex> lock(g_brightnessCoalesceMutex);
        g_pendingBrightnessValue = value;
        if (g_brightnessWorkerRunning) {
            return;
        }
        g_brightnessWorkerRunning = true;
    }
    RunInBackground([] {
        for (;;) {
            int v;
            {
                std::lock_guard<std::mutex> lock(g_brightnessCoalesceMutex);
                if (g_pendingBrightnessValue < 0) {
                    g_brightnessWorkerRunning = false;
                    return;
                }
                v = g_pendingBrightnessValue;
                g_pendingBrightnessValue = -1;
            }
            brightness::Set(v);
        }
    });
}

std::mutex g_monitorBrightnessCoalesceMutex;
std::map<HMONITOR, int> g_pendingMonitorBrightness;
bool g_monitorBrightnessWorkerRunning = false;

void SetMonitorBrightnessCoalesced(HMONITOR monitor, int value) {
    if (!monitor) {
        return;
    }
    {
        std::lock_guard<std::mutex> lock(g_monitorBrightnessCoalesceMutex);
        g_pendingMonitorBrightness[monitor] = value;
        if (g_monitorBrightnessWorkerRunning) {
            return;
        }
        g_monitorBrightnessWorkerRunning = true;
    }
    RunInBackground([] {
        for (;;) {
            std::map<HMONITOR, int> batch;
            {
                std::lock_guard<std::mutex> lock(g_monitorBrightnessCoalesceMutex);
                if (g_pendingMonitorBrightness.empty()) {
                    g_monitorBrightnessWorkerRunning = false;
                    return;
                }
                batch.swap(g_pendingMonitorBrightness);
            }
            for (const auto& entry : batch) {
                brightness::SetMonitorBrightnessPercent(entry.first, entry.second);
            }
        }
    });
}

std::mutex g_monitorCacheMutex;
std::vector<brightness::MonitorEntry> g_monitorCache;
std::atomic<bool> g_monitorCacheWarming{false};


std::vector<brightness::MonitorEntry> GetCachedMonitors() {
    std::lock_guard<std::mutex> lock(g_monitorCacheMutex);
    return g_monitorCache;
}

void RepopulateLater(const std::function<void()>& populate) {
    RunOnUiThread(populate);
}

