namespace recyclebin {

struct RecycleBinItem {
    std::wstring name;
    std::wstring originalFolder;
    std::vector<uint8_t> childPidlBytes;
    uint64_t sizeBytes = 0;
    bool isFolder = false;
};

void Refresh() {
    try {
        SHQUERYRBINFO info{};
        info.cbSize = sizeof(info);
        if (SUCCEEDED(SHQueryRecycleBin(nullptr, &info))) {
            g_recycleBinState.sizeBytes =
                static_cast<uint64_t>(info.i64Size);
            g_recycleBinState.itemCount =
                static_cast<uint64_t>(info.i64NumItems);
            g_recycleBinState.valid = true;
        }
    } catch (...) {
    }
}

std::wstring FormatBytes(uint64_t bytes) {
    const wchar_t* units[] = {L"B", L"KB", L"MB", L"GB", L"TB"};
    double value = static_cast<double>(bytes);
    int unit = 0;
    while (value >= 1024.0 && unit < 4) {
        value /= 1024.0;
        unit++;
    }
    wchar_t buf[64];
    swprintf_s(buf, L"%.1f %s", value, units[unit]);
    return buf;
}

bool Empty() {
    HRESULT hr = SHEmptyRecycleBin(
        nullptr, nullptr,
        SHERB_NOCONFIRMATION | SHERB_NOPROGRESSUI | SHERB_NOSOUND);
    return SUCCEEDED(hr);
}

std::vector<RecycleBinItem> EnumerateItems(size_t maxItems = 250) {
    std::vector<RecycleBinItem> out;
    HRESULT coHr = CoInitializeEx(nullptr, COINIT_APARTMENTTHREADED);
    const bool didInit = (coHr == S_OK || coHr == S_FALSE);

    static const IID kIidShellFolder =
        {0x000214E6, 0x0000, 0x0000, {0xC0, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x46}};
    static const IID kIidShellFolder2 =
        {0x93F2F68C, 0x1D1B, 0x11D3, {0xA3, 0x0E, 0x00, 0xC0, 0x4F, 0x79, 0xAB, 0xD1}};
    static const PROPERTYKEY kPkeySize =
        {{0xB725F130, 0x47EF, 0x101A, {0xA5, 0xF1, 0x02, 0x60, 0x8C, 0x9E, 0xEB, 0xAC}}, 12};
    static const PROPERTYKEY kPkeyDeletedFrom =
        {{0x9B174B33, 0x40FF, 0x11D2, {0xA2, 0x7E, 0x00, 0xC0, 0x4F, 0xC3, 0x08, 0x71}}, 2};

    IShellFolder* desktop = nullptr;
    PIDLIST_ABSOLUTE pidlBin = nullptr;
    IShellFolder* binFolder = nullptr;
    IShellFolder2* binFolder2 = nullptr;
    IEnumIDList* enumerator = nullptr;

    if (SUCCEEDED(SHGetDesktopFolder(&desktop)) && desktop &&
        SUCCEEDED(SHGetSpecialFolderLocation(nullptr, CSIDL_BITBUCKET, &pidlBin)) && pidlBin &&
        SUCCEEDED(desktop->BindToObject(pidlBin, nullptr, kIidShellFolder,
                                        reinterpret_cast<void**>(&binFolder))) &&
        binFolder) {
        binFolder->QueryInterface(kIidShellFolder2, reinterpret_cast<void**>(&binFolder2));
        if (SUCCEEDED(binFolder->EnumObjects(
                nullptr, SHCONTF_FOLDERS | SHCONTF_NONFOLDERS | SHCONTF_INCLUDEHIDDEN,
                &enumerator)) &&
            enumerator) {
            PITEMID_CHILD child = nullptr;
            ULONG fetched = 0;
            while (out.size() < maxItems &&
                   enumerator->Next(1, &child, &fetched) == S_OK && fetched == 1 && child) {
                RecycleBinItem item;
                STRRET sr{};
                if (SUCCEEDED(binFolder->GetDisplayNameOf(child, SHGDN_NORMAL, &sr))) {
                    wchar_t nameBuf[MAX_PATH * 2]{};
                    if (SUCCEEDED(StrRetToBufW(&sr, child, nameBuf, ARRAYSIZE(nameBuf)))) {
                        item.name = nameBuf;
                    }
                }
                SFGAOF attrs = SFGAO_FOLDER;
                PCUITEMID_CHILD cArr[1] = { child };
                if (SUCCEEDED(binFolder->GetAttributesOf(1, cArr, &attrs))) {
                    item.isFolder = (attrs & SFGAO_FOLDER) != 0;
                }
                if (binFolder2) {
                    VARIANT vSize{};
                    VariantInit(&vSize);
                    if (SUCCEEDED(binFolder2->GetDetailsEx(child, &kPkeySize, &vSize))) {
                        if (vSize.vt == VT_UI8) item.sizeBytes = vSize.ullVal;
                        else if (vSize.vt == VT_I8 && vSize.llVal >= 0) item.sizeBytes = static_cast<uint64_t>(vSize.llVal);
                        else if (vSize.vt == VT_UI4) item.sizeBytes = vSize.ulVal;
                        else if (vSize.vt == VT_I4 && vSize.lVal >= 0) item.sizeBytes = static_cast<uint64_t>(vSize.lVal);
                        else if (vSize.vt == VT_BSTR && vSize.bstrVal) {
                            item.sizeBytes = _wcstoui64(vSize.bstrVal, nullptr, 10);
                        }
                    }
                    VariantClear(&vSize);

                    VARIANT vFrom{};
                    VariantInit(&vFrom);
                    if (SUCCEEDED(binFolder2->GetDetailsEx(child, &kPkeyDeletedFrom, &vFrom))) {
                        if (vFrom.vt == VT_BSTR && vFrom.bstrVal) {
                            item.originalFolder = vFrom.bstrVal;
                        }
                    }
                    VariantClear(&vFrom);
                }
                UINT pidlSize = ILGetSize(child);
                if (pidlSize > 0) {
                    item.childPidlBytes.resize(pidlSize);
                    std::memcpy(item.childPidlBytes.data(), child, pidlSize);
                }
                if (item.name.empty()) item.name = L"Recycled item";
                out.push_back(std::move(item));
                CoTaskMemFree(child);
                child = nullptr;
            }
            enumerator->Release();
        }
    }

    if (binFolder2) binFolder2->Release();
    if (binFolder) binFolder->Release();
    if (pidlBin) CoTaskMemFree(pidlBin);
    if (desktop) desktop->Release();
    if (didInit) CoUninitialize();
    return out;
}

bool DeleteItems(const std::vector<std::vector<uint8_t>>& childPidls) {
    if (childPidls.empty()) return false;
    HRESULT coHr = CoInitializeEx(nullptr, COINIT_APARTMENTTHREADED);
    const bool didInit = (coHr == S_OK || coHr == S_FALSE);

    static const CLSID kClsidFileOp =
        {0x3AD05575, 0x8857, 0x4850, {0x92, 0x77, 0x11, 0xB8, 0x5B, 0xDB, 0x8E, 0x09}};
    static const IID kIidFileOp =
        {0x947AAB5F, 0x0A5C, 0x4C13, {0xB4, 0xD6, 0x4B, 0xF7, 0x83, 0x6F, 0xC9, 0xF8}};
    static const IID kIidShellFolder =
        {0x000214E6, 0x0000, 0x0000, {0xC0, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x46}};
    static const IID kIidShellItem =
        {0x43826D1E, 0xE718, 0x42EE, {0xBC, 0x55, 0xA1, 0xE2, 0x61, 0xC3, 0x7B, 0xFE}};

    bool ok = false;
    IShellFolder* desktop = nullptr;
    PIDLIST_ABSOLUTE pidlBin = nullptr;
    IShellFolder* binFolder = nullptr;
    IFileOperation* pfo = nullptr;

    if (SUCCEEDED(SHGetDesktopFolder(&desktop)) && desktop &&
        SUCCEEDED(SHGetSpecialFolderLocation(nullptr, CSIDL_BITBUCKET, &pidlBin)) && pidlBin &&
        SUCCEEDED(desktop->BindToObject(pidlBin, nullptr, kIidShellFolder,
                                        reinterpret_cast<void**>(&binFolder))) &&
        binFolder &&
        SUCCEEDED(CoCreateInstance(kClsidFileOp, nullptr, CLSCTX_ALL, kIidFileOp,
                                   reinterpret_cast<void**>(&pfo))) &&
        pfo) {
        pfo->SetOperationFlags(FOF_NOCONFIRMATION | FOF_SILENT | FOF_NOERRORUI);
        int queued = 0;
        for (const auto& bytes : childPidls) {
            if (bytes.empty()) continue;
            void* mem = CoTaskMemAlloc(bytes.size());
            if (!mem) continue;
            std::memcpy(mem, bytes.data(), bytes.size());
            IShellItem* si = nullptr;
            if (SUCCEEDED(SHCreateItemWithParent(
                    nullptr, binFolder, reinterpret_cast<PCUITEMID_CHILD>(mem),
                    kIidShellItem, reinterpret_cast<void**>(&si))) &&
                si) {
                if (SUCCEEDED(pfo->DeleteItem(si, nullptr))) {
                    ++queued;
                }
                si->Release();
            }
            CoTaskMemFree(mem);
        }
        if (queued > 0 && SUCCEEDED(pfo->PerformOperations())) {
            ok = true;
        }
        pfo->Release();
    }

    if (binFolder) binFolder->Release();
    if (pidlBin) CoTaskMemFree(pidlBin);
    if (desktop) desktop->Release();
    if (didInit) CoUninitialize();
    return ok;
}

}

wuxc::TextBlock MakeStatusText(std::wstring_view text) {
    auto block = MakeText(nullptr, text, 12, false, 0.6);
    block.Margin(Thickness{10, 8, 10, 8});
    block.TextWrapping(TextWrapping::Wrap);
    return block;
}

wuxc::Button MakeSettingsLink(std::wstring_view label, PCWSTR uri) {
    const bool winui = IsWinUI3StyleMode();
    auto button = MakeGhostButton(L"FlyoutFooterLink", EffectiveRowCorner());
    button.HorizontalAlignment(HorizontalAlignment::Stretch);
    if (winui) {
        button.Background(MakeBrush(0x0D, 0xFF, 0xFF, 0xFF));
        button.BorderBrush(MakeBrush(0x18, 0xFF, 0xFF, 0xFF));
        button.BorderThickness(Thickness{1, 1, 1, 1});
        button.Padding(Thickness{12, 9, 12, 9});
        button.Margin(Thickness{0, 2, 0, 0});

        wuxc::Grid row;
        wuxc::ColumnDefinition c0; c0.Width(GridLength{1, GridUnitType::Star});
        wuxc::ColumnDefinition c1; c1.Width(GridLength{0, GridUnitType::Auto});
        row.ColumnDefinitions().Append(c0);
        row.ColumnDefinitions().Append(c1);

        auto text = MakeText(nullptr, label, 12.5, false, 0.90);
        wuxc::Grid::SetColumn(text, 0);
        row.Children().Append(text);

        auto chev = iconpacks::MakeInlineGlyph(L"\uE76C", 11.0, FontColorBrush());
        chev.Opacity(0.65);
        wuxc::Grid::SetColumn(chev, 1);
        row.Children().Append(chev);

        button.Content(row);
    } else {
        button.Padding(Thickness{10, 7, 10, 7});
        auto text = MakeText(nullptr, label, 12, false, 0.75);
        button.Content(text);
    }
    std::wstring target = uri;
    button.Click([target](auto&&, auto&&) {
        ShellExecute(nullptr, L"open", target.c_str(), nullptr, nullptr, SW_SHOWNORMAL);
    });
    return button;
}

namespace nightlight {
    bool Get();
    bool Set(bool enable);
}

void PopulateDisplayPanel() {
    if (!g_displayPanel) {
        return;
    }

    g_monitorBrightnessSliders.clear();
    g_mainBrightnessSlider = nullptr;

    g_populatingPanel = true;
    struct Guard {
        ~Guard() { g_populatingPanel = false; }
    } guard;

    auto children = g_displayPanel.Children();
    children.Clear();

    const bool winui = IsWinUI3StyleMode();
    children.Append(MakePanelTitle(L"Display"));

    if (brightness::Available()) {
        auto icon = BuildVectorIcon(nullptr, L"", icons::kBrightnessStroke, 24, 18, 1.6);
        wuxc::Slider mainSlider{nullptr};
        auto sliderRow = MakeSliderRow(icon, brightness::Get(),
                                      [](int value) {
                                          SetBrightnessCoalesced(value);
                                          if (!g_syncingBrightness.load()) {
                                              g_syncingBrightness = true;
                                              for (auto& s : g_monitorBrightnessSliders) {
                                                  if (!s) continue;
                                                  try {
                                                      if (std::abs(s.Value() - (double)value) > 0.5) {
                                                          s.Value((double)value);
                                                      }
                                                  } catch (...) {}
                                              }
                                              g_syncingBrightness = false;
                                          }
                                      }, &mainSlider);
        g_mainBrightnessSlider = mainSlider;
        if (winui) {
            wuxc::Border card;
            card.CornerRadius(MakeCorner(6));
            card.Background(MakeBrush(0x0F, 0xFF, 0xFF, 0xFF));
            card.BorderBrush(MakeBrush(0x1A, 0xFF, 0xFF, 0xFF));
            card.BorderThickness(Thickness{1, 1, 1, 1});
            try { card.BackgroundSizing(wuxc::BackgroundSizing::InnerBorderEdge); } catch (...) {}
            card.Padding(Thickness{10, 8, 10, 8});
            card.Margin(Thickness{0, 0, 0, 4});
            wuxc::StackPanel cardBody;
            cardBody.Spacing(4);
            auto brHdr = MakeText(nullptr, L"Brightness", 11, false, 0.65);
            brHdr.Margin(Thickness{4, 0, 4, 0});
            cardBody.Children().Append(brHdr);
            cardBody.Children().Append(sliderRow);
            card.Child(cardBody);
            children.Append(card);
        } else {
            children.Append(sliderRow);
        }
    } else {
        children.Append(MakeStatusText(L"Brightness control isn't available on this display."));
    }

    {
        auto monitors = GetCachedMonitors();
        std::wstring subtitle;
        if (!monitors.empty()) {
            subtitle = monitors.size() == 1
                ? std::wstring(L"1 display")
                : std::to_wstring(monitors.size()) + L" displays";
        } else if (g_monitorCacheWarming) {
            subtitle = L"Scanning…";
        } else {
            subtitle = L"None detected";
        }

        auto expander = MakeExpander(L"All monitors", subtitle,
                                     &g_displayMonitorsExpanded,
                                     nullptr);

        if (monitors.empty()) {
            expander.body.Children().Append(MakeStatusText(
                g_monitorCacheWarming
                    ? L"Scanning for monitors…"
                    : L"No monitors were detected."));
        }

        for (const auto& m : monitors) {
            wuxc::StackPanel row;
            row.Spacing(0);
            row.Margin(Thickness{10, 4, 10, 4});
            row.Children().Append(MakeText(nullptr, m.name, 12, false, 0.85));

            if (!m.controllable) {
                row.Children().Append(MakeText(
                    nullptr, L"Brightness control not supported",
                    11, false, 0.55));
                expander.body.Children().Append(row);
                continue;
            }

            auto icon = BuildVectorIcon(nullptr, L"",
                                        icons::kBrightnessStroke, 24, 15, 1.5);
            HMONITOR hmon = m.hmonitor;
            wuxc::Slider monitorSlider{nullptr};
            row.Children().Append(MakeSliderRow(icon, m.percent,
                [hmon](int value) {
                    SetMonitorBrightnessCoalesced(hmon, value);
                    if (!g_syncingBrightness.load()) {
                        g_syncingBrightness = true;
                        if (g_mainBrightnessSlider) {
                            try {
                                if (std::abs(g_mainBrightnessSlider.Value() - (double)value) > 0.5) {
                                    g_mainBrightnessSlider.Value((double)value);
                                }
                            } catch (...) {}
                        }
                        if (g_mainBrightnessSyncCallback) {
                            try { g_mainBrightnessSyncCallback(value); } catch (...) {}
                        }
                        g_syncingBrightness = false;
                    }
                },
                &monitorSlider));
            if (monitorSlider) {
                g_monitorBrightnessSliders.push_back(monitorSlider);
            }
            expander.body.Children().Append(row);
        }
        children.Append(expander.root);
    }

    children.Append(MakeDivider());

    bool darkMode = IsAppsDarkMode();
    bool nightLightOn = false;
    try { nightLightOn = nightlight::Get(); } catch (...) {}

    auto makeToggleRow = [](FrameworkElement iconEl, PCWSTR title, PCWSTR subtitle,
                            bool initialOn, std::function<void(bool)> onToggle) -> wuxc::Grid {
        wuxc::Grid row;
        row.Padding(Thickness{12, 9, 12, 9});
        row.ColumnSpacing(10);
        wuxc::ColumnDefinition cIcon; cIcon.Width(GridLength{0, GridUnitType::Auto});
        wuxc::ColumnDefinition cText; cText.Width(GridLength{1, GridUnitType::Star});
        wuxc::ColumnDefinition cSw; cSw.Width(GridLength{0, GridUnitType::Auto});
        row.ColumnDefinitions().Append(cIcon);
        row.ColumnDefinitions().Append(cText);
        row.ColumnDefinitions().Append(cSw);

        if (iconEl) {
            iconEl.VerticalAlignment(VerticalAlignment::Center);
            wuxc::Grid::SetColumn(iconEl, 0);
            row.Children().Append(iconEl);
        }

        wuxc::StackPanel labels;
        labels.Spacing(1);
        labels.VerticalAlignment(VerticalAlignment::Center);
        labels.Children().Append(MakeText(nullptr, title, 12.5, true, 0.95));
        labels.Children().Append(MakeText(nullptr, subtitle, 10.5, false, 0.62));
        wuxc::Grid::SetColumn(labels, 1);
        row.Children().Append(labels);

        wuxc::ToggleSwitch ts;
        ts.OnContent(winrt::box_value(L""));
        ts.OffContent(winrt::box_value(L""));
        ts.MinWidth(0);
        ts.Width(44);
        ts.VerticalAlignment(VerticalAlignment::Center);
        ts.IsOn(initialOn);
        StyleWinUI3ToggleSwitch(ts);
        ts.Toggled([onToggle = std::move(onToggle)](auto&& sender, auto&&) {
            if (g_populatingPanel) return;
            if (auto sw = sender.template try_as<wuxc::ToggleSwitch>()) {
                if (onToggle) onToggle(sw.IsOn());
            }
        });
        wuxc::Grid::SetColumn(ts, 2);
        row.Children().Append(ts);
        return row;
    };

    wuxc::Border settingsCard;
    settingsCard.CornerRadius(MakeCorner(6));
    settingsCard.Background(MakeBrush(0x0F, 0xFF, 0xFF, 0xFF));
    settingsCard.BorderBrush(MakeBrush(0x1A, 0xFF, 0xFF, 0xFF));
    settingsCard.BorderThickness(Thickness{1, 1, 1, 1});
    try { settingsCard.BackgroundSizing(wuxc::BackgroundSizing::InnerBorderEdge); } catch (...) {}
    settingsCard.Margin(Thickness{0, 2, 0, 2});

    wuxc::StackPanel cardRows;
    cardRows.Spacing(0);

    auto nlIcon = iconpacks::MakeInlineGlyph(L"\uE708", 16.0, IconColorBrush());
    cardRows.Children().Append(makeToggleRow(
        nlIcon, L"Night light", L"Warm colors for night viewing", nightLightOn,
        [](bool target) {
            RunInBackground([target] {
                try { nightlight::Set(target); } catch (...) {}
            });
        }));

    wuxc::Border innerSep;
    innerSep.Height(1);
    innerSep.Background(MakeBrush(0x14, 0xFF, 0xFF, 0xFF));
    innerSep.HorizontalAlignment(HorizontalAlignment::Stretch);
    cardRows.Children().Append(innerSep);

    auto darkIcon = BuildVectorIcon(nullptr, icons::kMoonFill, L"", 24, 16, 1.6);
    cardRows.Children().Append(makeToggleRow(
        darkIcon, L"Dark mode", L"Windows app color theme", darkMode,
        [](bool target) {
            SetAppsDarkMode(target);
        }));

    settingsCard.Child(cardRows);
    children.Append(settingsCard);

    children.Append(MakeDivider()); 
    children.Append(MakeSettingsLink(L"Display settings", L"ms-settings:display"));
    StripControlCenterSubHeaderIfHosted(g_displayPanel);
    ApplyControlStylesToPopupRoot(g_displayPanel.as<FrameworkElement>());
}

FrameworkElement BuildSpeakerIcon(double size, int volume, bool muted) {
    std::wstring stroke;
    if (muted || volume == 0) {
        stroke = icons::kSpeakerMuted;
    } else if (volume < 55) {
        stroke = L"M15.4 9.4 A3.6 3.6 0 0 1 15.4 14.6";
    } else {
        stroke = icons::kSpeakerWaves;
    }
    return BuildVectorIcon(nullptr, icons::kSpeakerFill, stroke, 24, size, 1.6);
}

void RefreshSoundButtonIcon() {
    if (!g_soundButton) {
        return;
    }
    if (auto icon = iconpacks::SoundIcon(audio::GetMasterVolume(), audio::GetMasterMute())) {
        g_soundButton.Content(icon);
    }
}

