void UpdateMediaVisualizerTick() {
    if (g_visualizerBars.empty() && g_mediaButtonBars.empty()) return;
    float bands[24] = {0};
    visualizer::GetBands(bands, 24);

    static float s_smoothFlyout[24] = {0};
    if (!g_visualizerBars.empty()) {
        size_t nFly = g_visualizerBars.size();
        const double maxH = 92.0;
        for (size_t i = 0; i < nFly && i < 24; i++) {
            float v = 0;
            int from = (int)(i * 24 / nFly);
            int to   = (int)((i + 1) * 24 / nFly);
            if (to <= from) to = from + 1;
            for (int k = from; k < to && k < 24; k++) v = (std::max)(v, bands[k]);
            s_smoothFlyout[i] = s_smoothFlyout[i] * 0.72f + v * 0.28f;
            double h = 6.0 + s_smoothFlyout[i] * maxH;
            try { g_visualizerBars[i].Height(h); } catch (...) {}
        }
    }

    static float s_smoothButton[8] = {0};
    if (!g_mediaButtonBars.empty()) {
        size_t nBtn = g_mediaButtonBars.size();
        const double maxH = 14.0;
        for (size_t i = 0; i < nBtn; i++) {
            float v = 0;
            int from = (int)(i * 24 / nBtn);
            int to   = (int)((i + 1) * 24 / nBtn);
            if (to <= from) to = from + 1;
            for (int k = from; k < to && k < 24; k++) v = (std::max)(v, bands[k]);
            s_smoothButton[i] = s_smoothButton[i] * 0.7f + v * 0.3f;
            double h = 4.0 + s_smoothButton[i] * maxH;
            try { g_mediaButtonBars[i].Height(h); } catch (...) {}
        }
    }
}

void StopMediaVisualizer() {
    if (g_mediaVisualizerTimer) {
        g_mediaVisualizerTimer.Stop();
    }
    visualizer::Stop();
}

void StartMediaVisualizer() {
    if (!g_settings.showMediaVisualizer && !g_settings.mediaButtonShowVisualizer) return;
    visualizer::Start();
    if (!g_mediaVisualizerTimer) {
        g_mediaVisualizerTimer = DispatcherTimer();
        g_mediaVisualizerTimer.Interval(std::chrono::milliseconds(50));
        g_mediaVisualizerTimer.Tick([](wf::IInspectable const&, wf::IInspectable const&) {
            try { UpdateMediaVisualizerTick(); } catch (...) {}
        });
    }
    g_mediaVisualizerTimer.Start();
}


FrameworkElement BuildMediaButtonContent(const media::Snapshot& snapshot) {
    wuxc::StackPanel row;
    row.Orientation(wuxc::Orientation::Horizontal);
    row.Spacing(6);
    row.VerticalAlignment(VerticalAlignment::Center);
    row.HorizontalAlignment(HorizontalAlignment::Center);

    std::wstring mediaIconColorHex = GetEffectiveIconColorString();
    {
        auto mapIt = g_namedElementIconColorHex.find(L"MediaButton");
        if (mapIt != g_namedElementIconColorHex.end()) {
            mediaIconColorHex = mapIt->second;
        }
    }

    if (g_settings.mediaButtonShowIcon) {
        if (g_mediaThumbnailCache) {
            wuxc::Border artBorder;
            artBorder.Width(18);
            artBorder.Height(18);
            artBorder.CornerRadius(MakeCorner(3));
            artBorder.VerticalAlignment(VerticalAlignment::Center);
            wuxc::Image img;
            img.Source(g_mediaThumbnailCache);
            img.Width(18);
            img.Height(18);
            img.Stretch(wuxm::Stretch::UniformToFill);
            artBorder.Child(img);
            row.Children().Append(artBorder);
        } else {
            if (auto icon = BuildVectorIcon(
                    nullptr, icons::kMusicNoteFill, L"", 24, 16, 1.5,
                    mediaIconColorHex.c_str())) {
                icon.VerticalAlignment(VerticalAlignment::Center);
                row.Children().Append(icon);
            }
        }
    }

    if (g_settings.mediaButtonShowName) {
        auto tb = MakeText(nullptr,
            snapshot.title.empty() ? L"Unknown" : snapshot.title, 12);
        tb.MaxWidth(105);
        tb.TextTrimming(TextTrimming::CharacterEllipsis);
        tb.VerticalAlignment(VerticalAlignment::Center);
        row.Children().Append(tb);
    }

    for (int i = 0; i < 3; ++i) g_mediaSubButtons[i] = {};

    if (g_settings.mediaButtonShowControls) {
        auto makeCtrl = [](PCWSTR ctrlName, PCWSTR stateName, FrameworkElement iconElem, std::function<void()> onClick) {
            auto hit = wuxc::Button();
            try { hit.ElementSoundMode(ElementSoundMode::Off); } catch (...) {}
            if (ctrlName && *ctrlName) hit.Name(ctrlName);
            if (stateName && *stateName) {
                try { VisualStateManager::GoToState(hit, stateName, false); } catch (...) {}
            }
            try { hit.UseSystemFocusVisuals(false); } catch (...) {}
            hit.IsTabStop(false);
            hit.Width(22);
            hit.Height(22);
            hit.MinWidth(22);
            hit.MinHeight(22);
            hit.Padding(Thickness{0, 0, 0, 0});
            hit.Background(MakeBrush(1, 0, 0, 0));
            hit.BorderThickness(Thickness{0, 0, 0, 0});
            hit.CornerRadius(MakeCorner(4));
            hit.HorizontalAlignment(HorizontalAlignment::Center);
            hit.VerticalAlignment(VerticalAlignment::Center);
            hit.HorizontalContentAlignment(HorizontalAlignment::Center);
            hit.VerticalContentAlignment(VerticalAlignment::Center);
            if (iconElem) {
                iconElem.IsHitTestVisible(false);
                hit.Content(iconElem);
            }
            AttachTopBarPressAnimation(hit, 0.84f);
            hit.Click([onClick](auto&&, auto&&) {
                if (onClick) onClick();
            });
            return hit;
        };
        auto refreshSoon = [] {
            RunInBackground([] {
                Sleep(400);
                auto s = media::Read();
                RunOnUiThread([s] { try { ApplyMediaSnapshot(s); } catch (...) {} });
            });
        };
        wuxc::StackPanel transportPanel;
        transportPanel.Name(L"MediaTransportPanel");
        transportPanel.Orientation(wuxc::Orientation::Horizontal);
        transportPanel.Spacing(0);
        transportPanel.VerticalAlignment(VerticalAlignment::Center);
        auto prevBtn = makeCtrl(
            L"MediaPrevButton", L"Normal",
            iconpacks::MediaPrev(14, mediaIconColorHex.c_str()),
            [refreshSoon] {
                media::Send(media::Command::Previous); refreshSoon();
            });
        auto playPauseBtn = makeCtrl(
            snapshot.playing ? L"MediaPauseButton" : L"MediaResumeButton",
            snapshot.playing ? L"Paused" : L"Resumed",
            snapshot.playing ? iconpacks::MediaPause(14, mediaIconColorHex.c_str())
                             : iconpacks::MediaPlay(14, mediaIconColorHex.c_str()),
            [refreshSoon] {
                media::Send(media::Command::PlayPause); refreshSoon();
            });
        auto nextBtn = makeCtrl(
            L"MediaNextButton", L"Normal",
            iconpacks::MediaNext(14, mediaIconColorHex.c_str()),
            [refreshSoon] {
                media::Send(media::Command::Next); refreshSoon();
            });
        g_mediaSubButtons[0] = winrt::make_weak(prevBtn);
        g_mediaSubButtons[1] = winrt::make_weak(playPauseBtn);
        g_mediaSubButtons[2] = winrt::make_weak(nextBtn);
        transportPanel.Children().Append(prevBtn);
        transportPanel.Children().Append(playPauseBtn);
        transportPanel.Children().Append(nextBtn);
        row.Children().Append(transportPanel);
    }

    if (g_settings.mediaButtonShowVisualizer) {
            wuxc::StackPanel viz;
            viz.Orientation(wuxc::Orientation::Horizontal);
            viz.Spacing(1);
            viz.VerticalAlignment(VerticalAlignment::Center);
            viz.Height(20);
            viz.Margin(Thickness{0, 0, 0, 2});
            wui::Color accent{};
        if (!TryParseHexColor(mediaIconColorHex, &accent)) {
            accent = wui::ColorHelper::FromArgb(255, 255, 255, 255);
        }
        g_mediaButtonBars.clear();
        viz.Height(20);
        constexpr int kBars = 5;
        for (int i = 0; i < kBars; i++) {
            winrt::Windows::UI::Xaml::Shapes::Rectangle bar;
            bar.Width(3);
            bar.RadiusX(1);
            bar.RadiusY(1);
            bar.Height(3);
            bar.VerticalAlignment(VerticalAlignment::Bottom);
            bar.Fill(MakeBrush(0xFF, accent.R, accent.G, accent.B));
            viz.Children().Append(bar);
            g_mediaButtonBars.push_back(bar);
        }
        row.Children().Append(viz);
        if (snapshot.playing) {
            StartMediaVisualizer();
        }
    } else {
        g_mediaButtonBars.clear();
    }

    return row;
}

void ApplyMediaSnapshot(const media::Snapshot& snapshot) {
    bool playing = snapshot.valid && snapshot.playing;
    bool sessionExists = snapshot.valid;
    bool wasPlaying = g_mediaPlaying;
    bool wasSessionExists = g_mediaSessionExists;
    g_mediaPlaying = playing;
    g_mediaSessionExists = sessionExists;
    if (playing) g_cachedMediaSnapshot = snapshot;
    if (!playing && wasPlaying) {
        StopMediaVisualizer();
    }

    if (sessionExists && !snapshot.thumbnailBytes.empty() && !snapshot.title.empty()) {
        g_lastGoodThumbnailTitle = snapshot.title;
        g_lastGoodThumbnailBytes = snapshot.thumbnailBytes;
    }

    static std::wstring s_lastMediaButtonSig;
    std::wstring buttonSig = snapshot.title + L"|" + snapshot.artist + L"|" +
                             (playing ? L"1" : L"0") + L"|" +
                             (sessionExists ? L"1" : L"0");
    bool needRebuild = (buttonSig != s_lastMediaButtonSig);
    s_lastMediaButtonSig = buttonSig;

    if (sessionExists && g_settings.showMediaButton && g_mediaButton) {
        if (!snapshot.thumbnailBytes.empty() &&
            snapshot.thumbnailBytes != g_mediaThumbnailCacheBytes) {
            g_mediaThumbnailCacheBytes = snapshot.thumbnailBytes;
            g_mediaThumbnailCache = BytesToBitmapImage(snapshot.thumbnailBytes);
        }
        if (needRebuild) {
            g_mediaButton.Content(BuildMediaButtonContent(snapshot));
            try { ApplyAllControlStyles(); } catch (...) {}
            AdjustTaskButtonWidths();
        }
    }

    if (needRebuild) {
        RunOnUiThread([] {
            try { ApplyAllControlStyles(); } catch (...) {}
            RunOnUiThread([] {
                try { ApplyAllControlStyles(); } catch (...) {}
            });
        });
    }
    if (playing != wasPlaying || sessionExists != wasSessionExists) {
        ApplyVisibilitySettings();
    }
    if ((needRebuild || playing != wasPlaying || sessionExists != wasSessionExists) &&
        g_mediaFlyout && g_mediaFlyout.IsOpen()) {
        PopulateMediaPanel();
    }
    if (wasSessionExists && !sessionExists && g_settings.showMediaButton) {
        RunInBackground([] {
            if (WaitForSingleObject(g_stopEvent, 350) == WAIT_OBJECT_0) return;
            RunOnUiThread([] {
                try { RefreshMediaButtonState(); } catch (...) {}
            });
        });
    }
}

void PopulateMediaPanel() {
    if (!g_mediaPanel) return;
    RunInBackground([] {
        auto snapshot = media::Read();
        if (snapshot.valid && snapshot.playing && snapshot.lastUpdated > 0) {
            int64_t nowTicks = winrt::clock::now().time_since_epoch().count();
            int64_t elapsed = nowTicks - snapshot.lastUpdated;
            if (elapsed > 0) {
                snapshot.positionTicks += elapsed;
                if (snapshot.endTicks > 0 &&
                    snapshot.positionTicks > snapshot.endTicks) {
                    snapshot.positionTicks = snapshot.endTicks;
                }
            }
        }
        RunOnUiThread([snapshot] {
            if (!g_mediaPanel) return;
            g_populatingPanel = true;
            struct Guard { ~Guard() { g_populatingPanel = false; } } guard;
            auto ch = g_mediaPanel.Children();
            ch.Clear();

            if (!snapshot.valid) {
                ch.Append(MakeStatusText(L"Nothing is playing right now."));
                return;
            }

            auto fmtTime = [](int64_t ticks) -> std::wstring {
                if (ticks <= 0) return L"0:00";
                int64_t totalSec = ticks / 10000000LL;
                if (totalSec < 0) totalSec = 0;
                int mins = static_cast<int>(totalSec / 60);
                int secs = static_cast<int>(totalSec % 60);
                wchar_t buf[16];
                swprintf_s(buf, L"%d:%02d", mins, secs);
                return buf;
            };

            const bool winui = IsWinUI3StyleMode();
            wuxc::Border card;
            card.CornerRadius(MakeCorner(winui ? 8 : 16));
            card.Background(MakeBrush(winui ? 0x0F : 0, 0xFF, 0xFF, 0xFF));
            card.BorderBrush(MakeBrush(winui ? 0x1A : 0, 0xFF, 0xFF, 0xFF));
            card.BorderThickness(Thickness{winui ? 1.0 : 0.0, winui ? 1.0 : 0.0,
                                           winui ? 1.0 : 0.0, winui ? 1.0 : 0.0});
            try { card.BackgroundSizing(wuxc::BackgroundSizing::InnerBorderEdge); } catch (...) {}
            card.Padding(winui ? Thickness{ 14, 14, 14, 14 } : Thickness{ 16, 0, 16, 16 });
            card.HorizontalAlignment(HorizontalAlignment::Stretch);
            card.Margin(winui ? Thickness{ 0, 0, 0, 2 } : Thickness{ 4, 0, 4, 4 });

            wuxc::StackPanel body;
            body.Spacing(14);
            body.HorizontalAlignment(HorizontalAlignment::Stretch);

            wuxc::Grid header;
            header.ColumnSpacing(14);
            {
                wuxc::ColumnDefinition c0;
                c0.Width(GridLength{ 0, GridUnitType::Auto });
                header.ColumnDefinitions().Append(c0);
                wuxc::ColumnDefinition c1;
                c1.Width(GridLength{ 1, GridUnitType::Star });
                header.ColumnDefinitions().Append(c1);
                wuxc::ColumnDefinition c2;
                c2.Width(GridLength{ 0, GridUnitType::Auto });
                header.ColumnDefinitions().Append(c2);
            }

            wuxc::Border artFrame;
            artFrame.Width(60);
            artFrame.Height(60);
            const double artRadius = winui ? 6.0 : 10.0;
            artFrame.CornerRadius(MakeCorner(artRadius));
            artFrame.VerticalAlignment(VerticalAlignment::Center);
            if (winui) {
                ApplyRoundedClip(artFrame.as<FrameworkElement>(), artRadius);
            } else {
                wuxm::RectangleGeometry artClip;
                artClip.Rect(winrt::Windows::Foundation::Rect{0.0f, 0.0f, 60.0f, 60.0f});
                artFrame.Clip(artClip);
            }
            if (!snapshot.thumbnailBytes.empty() && !snapshot.title.empty()) {
                g_lastGoodThumbnailTitle = snapshot.title;
                g_lastGoodThumbnailBytes = snapshot.thumbnailBytes;
            }
            std::vector<uint8_t> thumbBytes = snapshot.thumbnailBytes;
            if (thumbBytes.empty() && !snapshot.title.empty() &&
                snapshot.title == g_lastGoodThumbnailTitle &&
                !g_lastGoodThumbnailBytes.empty()) {
                thumbBytes = g_lastGoodThumbnailBytes;
            }
            bool artSet = false;
            if (!thumbBytes.empty()) {
                if (thumbBytes != g_mediaFlyoutArtBytes || !g_mediaFlyoutArt) {
                    g_mediaFlyoutArtBytes = thumbBytes;
                    g_mediaFlyoutArt = BytesToBitmapImage(thumbBytes, 120);
                }
                if (g_mediaFlyoutArt) {
                    wuxc::Image artImg;
                    artImg.Source(g_mediaFlyoutArt);
                    artImg.Width(60);
                    artImg.Height(60);
                    artImg.Stretch(wuxm::Stretch::UniformToFill);
                    artFrame.Background(MakeBrush(0x30, 0xFF, 0xFF, 0xFF));
                    artFrame.Child(artImg);
                    artSet = true;
                }
            }
            if (!artSet) {
                artFrame.Background(MakeBrush(0x30, 0xFF, 0xFF, 0xFF));
                if (auto icon = BuildVectorIcon(
                        nullptr, icons::kMusicNoteFill, L"", 24, 28, 1.5)) {
                    icon.HorizontalAlignment(HorizontalAlignment::Center);
                    icon.VerticalAlignment(VerticalAlignment::Center);
                    artFrame.Child(icon);
                }
            }
            wuxc::Grid::SetColumn(artFrame, 0);
            header.Children().Append(artFrame);

            wuxc::StackPanel titleStack;
            titleStack.VerticalAlignment(VerticalAlignment::Center);
            titleStack.HorizontalAlignment(HorizontalAlignment::Left);
            titleStack.MaxWidth(168);
            titleStack.Spacing(3);
            auto titleTb = MakeText(nullptr,
                snapshot.title.empty() ? L"Unknown" : snapshot.title, 15, true);
            titleTb.TextWrapping(TextWrapping::Wrap);
            titleTb.MaxLines(2);
            titleStack.Children().Append(titleTb);
            if (!snapshot.artist.empty()) {
                auto artistTb = MakeText(nullptr, snapshot.artist, 12, false, 0.7);
                artistTb.TextWrapping(TextWrapping::Wrap);
                artistTb.MaxLines(1);
                titleStack.Children().Append(artistTb);
            }
            wuxc::Grid::SetColumn(titleStack, 1);
            header.Children().Append(titleStack);

            if (g_settings.showMediaVisualizer) {
                wuxc::Grid viz;
                viz.Width(30);
                viz.Height(92);
                viz.VerticalAlignment(VerticalAlignment::Center);
                wui::Color accent{};
                if (!TryParseHexColor(GetEffectiveIconColorString(), &accent)) {
                    accent = wui::ColorHelper::FromArgb(255, 255, 255, 255);
                }
                g_visualizerBars.clear();
                constexpr int kBars = 5;
                for (int i = 0; i < kBars; i++) {
                    wuxc::ColumnDefinition cd;
                    cd.Width(GridLength{ 1, GridUnitType::Star });
                    viz.ColumnDefinitions().Append(cd);
                }
                for (int i = 0; i < kBars; i++) {
                    winrt::Windows::UI::Xaml::Shapes::Rectangle bar;
                    bar.Width(3);
                    bar.RadiusX(2);
                    bar.RadiusY(2);
                    bar.Height(4);
                    bar.VerticalAlignment(VerticalAlignment::Bottom);
                    bar.HorizontalAlignment(HorizontalAlignment::Center);
                    bar.Fill(MakeBrush(0xFF, accent.R, accent.G, accent.B));
                    wuxc::Grid::SetColumn(bar, i);
                    viz.Children().Append(bar);
                    g_visualizerBars.push_back(bar);
                }
                auto clipGeom = wuxm::RectangleGeometry();
                clipGeom.Rect(winrt::Windows::Foundation::Rect{ 0.0f, 0.0f, 30.0f, 92.0f });
                viz.Clip(clipGeom);
                wuxc::Grid::SetColumn(viz, 2);
                header.Children().Append(viz);
                if (snapshot.playing) {
                    StartMediaVisualizer();
                }
            } else {
                g_visualizerBars.clear();
            }

            body.Children().Append(header);

            {
                wuxc::Grid progressRow;
                progressRow.ColumnSpacing(10);
                {
                    wuxc::ColumnDefinition c0;
                    c0.Width(GridLength{ 0, GridUnitType::Auto });
                    progressRow.ColumnDefinitions().Append(c0);
                    wuxc::ColumnDefinition c1;
                    c1.Width(GridLength{ 1, GridUnitType::Star });
                    progressRow.ColumnDefinitions().Append(c1);
                    wuxc::ColumnDefinition c2;
                    c2.Width(GridLength{ 0, GridUnitType::Auto });
                    progressRow.ColumnDefinitions().Append(c2);
                }

                auto posTb = MakeText(L"MediaPositionText", fmtTime(snapshot.positionTicks), 11, false, 0.7);
                posTb.VerticalAlignment(VerticalAlignment::Center);
                posTb.MinWidth(36);
                wuxc::Grid::SetColumn(posTb, 0);
                progressRow.Children().Append(posTb);
                g_namedElements.insert_or_assign(L"MediaPositionText", posTb);

                wuxc::ProgressBar progress;
                progress.Name(L"MediaProgressBar");
                progress.Minimum(0);
                progress.Maximum(100);
                double pct = 0.0;
                if (snapshot.endTicks > 0) {
                    pct = static_cast<double>(snapshot.positionTicks) /
                          static_cast<double>(snapshot.endTicks) * 100.0;
                    if (pct < 0.0) pct = 0.0;
                    if (pct > 100.0) pct = 100.0;
                }
                progress.Value(pct);
                progress.VerticalAlignment(VerticalAlignment::Center);
                progress.Height(4);
                if (winui) {
                    wui::Color acc = GetSystemAccentColor();
                    progress.Foreground(MakeBrush(0xFF, acc.R, acc.G, acc.B));
                    progress.Background(MakeBrush(0x28, 0xFF, 0xFF, 0xFF));
                } else {
                    progress.Foreground(MakeBrush(0xCC, 0xFF, 0xFF, 0xFF));
                    progress.Background(MakeBrush(0x30, 0xFF, 0xFF, 0xFF));
                }
                progress.BorderThickness(Thickness{ 0, 0, 0, 0 });
                g_namedElements.insert_or_assign(L"MediaProgressBar", progress);

                wuxc::Border seekHit;
                seekHit.Background(MakeBrush(0x01, 0, 0, 0));
                seekHit.VerticalAlignment(VerticalAlignment::Center);
                seekHit.Height(20);
                seekHit.HorizontalAlignment(HorizontalAlignment::Stretch);

                auto seekHitRef = seekHit;
                auto doSeek = [seekHitRef, progress, posTb, snapshot](double clickX) {
                    static std::shared_ptr<DispatcherTimer> s_seekResetTimer;
                    if (!s_seekResetTimer) {
                        s_seekResetTimer = std::make_shared<DispatcherTimer>();
                        s_seekResetTimer->Interval(std::chrono::milliseconds(250));
                        s_seekResetTimer->Tick([](wf::IInspectable const&, wf::IInspectable const&) {
                            s_seekResetTimer->Stop();
                            try {
                                auto it = g_namedElements.find(L"MediaProgressBar");
                                if (it != g_namedElements.end()) {
                                    if (auto bar = it->second.try_as<wuxc::ProgressBar>()) {
                                        bar.Height(4);
                                    }
                                }
                            } catch (...) {}
                        });
                    }
                    s_seekResetTimer->Stop();
                    s_seekResetTimer->Start();
                    try {
                        double wpre = seekHitRef.ActualWidth();
                        if (wpre > 0.0) {
                            double rpre = std::clamp(clickX / wpre, 0.0, 1.0);
                            progress.Value(rpre * 100.0);
                            progress.Height(6);
                            if (snapshot.endTicks > 0) {
                                int64_t s2 = static_cast<int64_t>(rpre * snapshot.endTicks) / 10000000LL;
                                if (s2 < 0) s2 = 0;
                                wchar_t b[16];
                                swprintf_s(b, L"%d:%02d", (int)(s2/60), (int)(s2%60));
                                posTb.Text(winrt::hstring(b));
                            }
                        }
                    } catch (...) {}
                    double w = seekHitRef.ActualWidth();
                    if (w <= 0.0) return;
                    double ratio = std::clamp(clickX / w, 0.0, 1.0);
#if TOPBAR_HAS_MEDIA_CONTROL
                    RunInBackground([ratio] {
                        try {
                            using namespace winrt::Windows::Media::Control;
                            auto manager = GlobalSystemMediaTransportControlsSessionManager
                                ::RequestAsync().get();
                            if (!manager) return;
                            auto session = manager.GetCurrentSession();
                            if (!session) return;
                            auto info = session.GetTimelineProperties();
                            if (!info) return;
                            int64_t end = info.EndTime().count();
                            if (end <= 0) return;
                            int64_t target = static_cast<int64_t>(ratio * end);
                            session.TryChangePlaybackPositionAsync(target).get();
                            Sleep(120);
                            auto refreshed = media::Read();
                            RunOnUiThread([refreshed] {
                                try { ApplyMediaSnapshot(refreshed); } catch (...) {}
                                try { PopulateMediaPanel(); } catch (...) {}
                            });
                        } catch (...) {}
                    });
#endif
                };
                auto progressRef = progress;
                auto posTbRef = posTb;
                auto draggingRef = std::make_shared<bool>(false);
                auto endTicksRef = std::make_shared<int64_t>(snapshot.endTicks);
                auto fmtSeekTime = [](int64_t ticks) -> std::wstring {
                    if (ticks <= 0) return L"0:00";
                    int64_t s = ticks / 10000000LL;
                    if (s < 0) s = 0;
                    wchar_t b[16];
                    swprintf_s(b, L"%d:%02d",
                               static_cast<int>(s / 60),
                               static_cast<int>(s % 60));
                    return b;
                };
                auto updateDragVisual = [seekHitRef, progressRef, posTbRef,
                                          endTicksRef, fmtSeekTime](double clickX) -> double {
                    double w = seekHitRef.ActualWidth();
                    if (w <= 0.0) return 0.0;
                    double ratio = std::clamp(clickX / w, 0.0, 1.0);
                    try {
                        progressRef.Value(ratio * 100.0);
                        progressRef.Height(6);
                        int64_t end = *endTicksRef;
                        if (end > 0) {
                            posTbRef.Text(winrt::hstring(fmtSeekTime(
                                static_cast<int64_t>(ratio * end))));
                        }
                    } catch (...) {}
                    return ratio;
                };
                auto sendSeek = [](double ratio) {
#if TOPBAR_HAS_MEDIA_CONTROL
                    RunInBackground([ratio] {
                        try {
                            using namespace winrt::Windows::Media::Control;
                            auto manager = GlobalSystemMediaTransportControlsSessionManager
                                ::RequestAsync().get();
                            if (!manager) return;
                            auto session = manager.GetCurrentSession();
                            if (!session) return;
                            auto info = session.GetTimelineProperties();
                            if (!info) return;
                            int64_t end = info.EndTime().count();
                            if (end <= 0) return;
                            int64_t target = static_cast<int64_t>(ratio * end);
                            session.TryChangePlaybackPositionAsync(target).get();
                        } catch (...) {}
                    });
#endif
                };
                seekHit.AddHandler(UIElement::PointerPressedEvent(),
                    winrt::box_value(Input::PointerEventHandler(
                        [seekHitRef, updateDragVisual, draggingRef](auto const&,
                                             Input::PointerRoutedEventArgs const& e) {
                            try {
                                auto pt = e.GetCurrentPoint(seekHitRef);
                                *draggingRef = true;
                                updateDragVisual(pt.Position().X);
                                seekHitRef.CapturePointer(e.Pointer());
                                e.Handled(true);
                            } catch (...) {}
                        })), true);
                seekHit.AddHandler(UIElement::PointerMovedEvent(),
                    winrt::box_value(Input::PointerEventHandler(
                        [seekHitRef, updateDragVisual, draggingRef](auto const&,
                                             Input::PointerRoutedEventArgs const& e) {
                            try {
                                if (!*draggingRef) return;
                                auto pt = e.GetCurrentPoint(seekHitRef);
                                if (!pt.Properties().IsLeftButtonPressed()) return;
                                updateDragVisual(pt.Position().X);
                                e.Handled(true);
                            } catch (...) {}
                        })), true);
                seekHit.AddHandler(UIElement::PointerReleasedEvent(),
                    winrt::box_value(Input::PointerEventHandler(
                        [seekHitRef, updateDragVisual, draggingRef, sendSeek, progressRef](auto const&,
                                     Input::PointerRoutedEventArgs const& e) {
                            try {
                                if (!*draggingRef) return;
                                *draggingRef = false;
                                auto pt = e.GetCurrentPoint(seekHitRef);
                                double ratio = updateDragVisual(pt.Position().X);
                                seekHitRef.ReleasePointerCapture(e.Pointer());
                                try { progressRef.Height(4); } catch (...) {}
                                sendSeek(ratio);
                            } catch (...) {}
                        })), true);

                wuxc::Grid progressStack;
                progressStack.Children().Append(progress);
                progressStack.Children().Append(seekHit);
                wuxc::Grid::SetColumn(progressStack, 1);
                progressRow.Children().Append(progressStack);

                auto endTb = MakeText(L"MediaEndText", fmtTime(snapshot.endTicks), 11, false, 0.7);
                endTb.VerticalAlignment(VerticalAlignment::Center);
                endTb.MinWidth(36);
                endTb.TextAlignment(TextAlignment::Right);
                wuxc::Grid::SetColumn(endTb, 2);
                progressRow.Children().Append(endTb);
                g_namedElements.insert_or_assign(L"MediaEndText", endTb);

                body.Children().Append(progressRow);
            }

            {
                wuxc::StackPanel controls;
                controls.Orientation(wuxc::Orientation::Horizontal);
                controls.Spacing(14);
                controls.HorizontalAlignment(HorizontalAlignment::Center);
                controls.VerticalAlignment(VerticalAlignment::Center);
                controls.Margin(Thickness{ 0, 4, 0, 0 });

                auto makeIconBtn = [](FrameworkElement iconElem,
                                      std::function<void()> onClick) {
                    auto b = MakeGhostButton(nullptr, 8);
                    b.Width(36);
                    b.Height(36);
                    b.MinWidth(36);
                    b.Padding(Thickness{ 0, 0, 0, 0 });
                    b.Background(MakeBrush(0, 0, 0, 0));
                    b.BorderThickness(Thickness{ 0, 0, 0, 0 });
                    b.HorizontalContentAlignment(HorizontalAlignment::Center);
                    b.VerticalContentAlignment(VerticalAlignment::Center);
                    if (iconElem) {
                        iconElem.HorizontalAlignment(HorizontalAlignment::Center);
                        iconElem.VerticalAlignment(VerticalAlignment::Center);
                        wuxc::Border wrapper;
                        wrapper.Background(MakeBrush(0x22, 0xFF, 0xFF, 0xFF));
                        wrapper.CornerRadius(MakeCorner(8));
                        wrapper.Child(iconElem);
                        b.Content(wrapper);
                    }
                    b.Click([onClick](auto&&, auto&&) { if (onClick) onClick(); });
                    return b;
                };

                auto refreshSoon = [] {
                    RunInBackground([] {
                        Sleep(300);
                        auto s = media::Read();
                        RunOnUiThread([s] {
                            try { ApplyMediaSnapshot(s); } catch (...) {}
                            try { PopulateMediaPanel(); } catch (...) {}
                        });
                    });
                };

                controls.Children().Append(makeIconBtn(
                    iconpacks::MediaPrev(18, L"#FFFFFF"),
                    [refreshSoon] { media::Send(media::Command::Previous); refreshSoon(); }));

                auto playBtn = MakeGhostButton(nullptr, 28);
                playBtn.Width(56);
                playBtn.Height(56);
                playBtn.MinWidth(56);
                playBtn.Padding(Thickness{ 0, 0, 0, 0 });
                auto accent = GetSystemAccentColor();
                auto accentBrush = MakeBrush(0xFF, accent.R, accent.G, accent.B);
                playBtn.Background(accentBrush);
                playBtn.BorderBrush(accentBrush);
                playBtn.BorderThickness(Thickness{ 0, 0, 0, 0 });
                playBtn.HorizontalContentAlignment(HorizontalAlignment::Center);
                playBtn.VerticalContentAlignment(VerticalAlignment::Center);
                playBtn.Resources().Insert(
                    winrt::box_value(winrt::hstring(L"ButtonBackground")), accentBrush);
                playBtn.Resources().Insert(
                    winrt::box_value(winrt::hstring(L"ButtonBackgroundPointerOver")), accentBrush);
                playBtn.Resources().Insert(
                    winrt::box_value(winrt::hstring(L"ButtonBackgroundPressed")), accentBrush);
                playBtn.Resources().Insert(
                    winrt::box_value(winrt::hstring(L"ButtonBorderBrush")), accentBrush);
                playBtn.Resources().Insert(
                    winrt::box_value(winrt::hstring(L"ButtonBorderBrushPointerOver")), accentBrush);
                playBtn.Resources().Insert(
                    winrt::box_value(winrt::hstring(L"ButtonBorderBrushPressed")), accentBrush);
                playBtn.Content(snapshot.playing
                    ? iconpacks::MediaPause(22, L"#FFFFFF")
                    : iconpacks::MediaPlay(22, L"#FFFFFF"));
                playBtn.Click([](auto&&, auto&&) {
                    media::Send(media::Command::PlayPause);
                    RunInBackground([] {
                        Sleep(300);
                        auto refreshed = media::Read();
                        RunOnUiThread([refreshed] {
                            ApplyMediaSnapshot(refreshed);
                            PopulateMediaPanel();
                        });
                    });
                });
                controls.Children().Append(playBtn);

                controls.Children().Append(makeIconBtn(
                    iconpacks::MediaNext(18, L"#FFFFFF"),
                    [refreshSoon] { media::Send(media::Command::Next); refreshSoon(); }));

                body.Children().Append(controls);
            }

            card.Child(body);
            ch.Append(card);
            StartMediaProgressTimer();
            RunOnUiThread([] {
                try { UpdateMediaFlyoutProgress(); } catch (...) {}
            });
            auto scheduleRefresh = [](int delayMs) {
                RunInBackground([delayMs] {
                    Sleep(delayMs);
                    RunOnUiThread([] {
                        try { UpdateMediaFlyoutProgress(); } catch (...) {}
                    });
                });
            };
            scheduleRefresh(150); 
            scheduleRefresh(500);
            scheduleRefresh(1200);
            if (g_mediaPanel) ApplyControlStylesToPopupRoot(g_mediaPanel.as<FrameworkElement>());
        });
    });
}

static std::atomic<bool> g_mediaRefreshInFlight{false};

void RefreshMediaButtonState() {
    if (!g_settings.showMediaButton) {
        g_mediaPlaying = false;
        g_mediaSessionExists = false;
        ApplyVisibilitySettings();
        return;
    }
    if (g_mediaRefreshInFlight.exchange(true)) return;
    RunInBackground([] {
        auto snapshot = media::Read();
        g_mediaRefreshInFlight.store(false);
        RunOnUiThread([snapshot] { ApplyMediaSnapshot(snapshot); });
    });
}

#else

void RefreshMediaCard() {}
void PopulateMediaPanel() {}
void RefreshMediaButtonState() {}
void StartMediaVisualizer() {}
void StopMediaVisualizer() {}

#endif

void PopulateSoundPanel() {
    if (!g_soundPanel) {
        return;
    }

    g_populatingPanel = true;
    struct Guard {
        ~Guard() { g_populatingPanel = false; }
    } guard;

    auto children = g_soundPanel.Children();
    children.Clear();

    children.Append(MakePanelTitle(L"Sound"));

    if (!g_settings.showMediaButton) {
        g_mediaContainer = wuxc::StackPanel();
        g_mediaContainer.Name(L"MediaCard");
        g_mediaContainer.Visibility(Visibility::Collapsed);
        children.Append(g_mediaContainer);
        RefreshMediaCard();
    }

    const bool winui = IsWinUI3StyleMode();
    int masterVolume = audio::GetMasterVolume();
    bool masterMuted = audio::GetMasterMute();

    auto wrapWinUI3Card = [&](UIElement const& inner, Thickness margin) -> UIElement {
        if (!winui) return inner;
        wuxc::Border card;
        card.CornerRadius(MakeCorner(6));
        card.Background(MakeBrush(0x0F, 0xFF, 0xFF, 0xFF));
        card.BorderBrush(MakeBrush(0x1A, 0xFF, 0xFF, 0xFF));
        card.BorderThickness(Thickness{1, 1, 1, 1});
        try { card.BackgroundSizing(wuxc::BackgroundSizing::InnerBorderEdge); } catch (...) {}
        card.Padding(Thickness{10, 8, 10, 8});
        card.Margin(margin);
        card.Child(inner);
        return card;
    };

    auto muteButton = MakeGhostButton(L"SoundMuteButton", EffectiveRowCorner());
    muteButton.Padding(Thickness{6, 6, 6, 6});
    muteButton.Content(iconpacks::SoundIcon(masterVolume, masterMuted));
    muteButton.Click([masterMuted](auto&&, auto&&) {
        if (auto volume = audio::EndpointVolume(eRender)) {
            volume->SetMute(masterMuted ? FALSE : TRUE, nullptr);
        }
        RefreshSoundButtonIcon();
        RepopulateLater(PopulateSoundPanel);
    });

    auto weakMute = winrt::make_weak(muteButton);
    auto outSliderRow = MakeSliderRow(muteButton, masterVolume, [weakMute](int value) {
        SetMasterVolumeCoalesced(value);
        RunOnUiThread([weakMute, value] {
            RefreshSoundButtonIcon();
            if (auto mb = weakMute.get()) {
                try { mb.Content(iconpacks::SoundIcon(value, value == 0)); } catch (...) {}
            }
        });
    });
    if (winui) {
        wuxc::StackPanel outBox;
        outBox.Spacing(4);
        auto outHeader = MakeText(nullptr, L"Output volume", 11, false, 0.65);
        outHeader.Margin(Thickness{4, 0, 4, 0});
        outBox.Children().Append(outHeader);
        outBox.Children().Append(outSliderRow);
        children.Append(wrapWinUI3Card(outBox, Thickness{0, 0, 0, 4}));
    } else {
        children.Append(outSliderRow);
    }

    // Input (microphone) volume row
    {
        int inputVolume = audio::GetEndpointVolume(eCapture);
        bool inputMuted = audio::GetEndpointMute(eCapture);
        bool hasCapture = audio::DefaultDevice(eCapture) != nullptr;

        auto makeMicGlyph = [hasCapture](bool muted) {
            auto fi = iconpacks::MakeInlineGlyph(muted ? L"\uF781" : L"\uE720", 16.0);
            fi.Opacity(hasCapture ? (muted ? 0.55 : 1.0) : 0.35);
            return fi;
        };

        auto inHeader = MakeText(nullptr, hasCapture ? L"Input volume" : L"Input volume (no microphone)",
                                 11, false, hasCapture ? 0.65 : 0.42);
        inHeader.Margin(Thickness{4, winui ? 0.0 : 6.0, 4, 0});

        auto inMuteButton = MakeGhostButton(L"InputMuteButton", EffectiveRowCorner());
        inMuteButton.Padding(Thickness{6, 6, 6, 6});
        inMuteButton.Content(makeMicGlyph(inputMuted));
        inMuteButton.IsEnabled(hasCapture);
        inMuteButton.Click([inputMuted](auto&&, auto&&) {
            if (auto volume = audio::EndpointVolume(eCapture)) {
                volume->SetMute(inputMuted ? FALSE : TRUE, nullptr);
            }
            RepopulateLater(PopulateSoundPanel);
        });

        auto weakInMute = winrt::make_weak(inMuteButton);
        auto inSliderRow = MakeSliderRow(inMuteButton, inputVolume, [weakInMute, makeMicGlyph](int value) {
            SetCaptureVolumeCoalesced(value);
            RunOnUiThread([weakInMute, makeMicGlyph, value] {
                if (auto mb = weakInMute.get()) {
                    try { mb.Content(makeMicGlyph(value == 0)); } catch (...) {}
                }
            });
        });
        if (!hasCapture) {
            inSliderRow.Opacity(0.45);
            inSliderRow.IsHitTestVisible(false);
        }
        if (winui) {
            wuxc::StackPanel inBox;
            inBox.Spacing(4);
            inBox.Children().Append(inHeader);
            inBox.Children().Append(inSliderRow);
            children.Append(wrapWinUI3Card(inBox, Thickness{0, 0, 0, 2}));
        } else {
            children.Append(inHeader);
            children.Append(inSliderRow);
        }
    }

    children.Append(MakeDivider());

    auto buildAudioDeviceSection = [&](PCWSTR title, EDataFlow flow, bool* expandedFlag,
                                       PCWSTR emptyText) {
        auto devices = audio::EnumerateDevices(flow);
        std::wstring currentName = (flow == eRender) ? L"No output device" : L"No input device";
        for (const auto& device : devices) {
            if (device.isDefault && device.isEnabled) {
                currentName = device.name;
                break;
            }
        }

        auto expander = MakeExpander(title, currentName, expandedFlag, nullptr);

        if (devices.empty()) {
            expander.body.Children().Append(MakeStatusText(emptyText));
        }

        auto makeActionPill = [winui](PCWSTR text, bool = false) {
            auto btn = MakeGhostButton(nullptr, winui ? 4.0 : 6.0);
            btn.Padding(Thickness{10, 4, 10, 4});
            btn.MinWidth(0);
            btn.MinHeight(0);
            auto bg = MakeBrush(winui ? 0x14 : 0x1C, 0xFF, 0xFF, 0xFF);
            auto hoverBg = MakeBrush(0x22, 0xFF, 0xFF, 0xFF);
            auto pressedBg = MakeBrush(0x0E, 0xFF, 0xFF, 0xFF);
            auto bd = MakeBrush(winui ? 0x24 : 0x2A, 0xFF, 0xFF, 0xFF);
            btn.Background(bg);
            btn.BorderBrush(bd);
            btn.BorderThickness(Thickness{1, 1, 1, 1});
            btn.Resources().Insert(winrt::box_value(winrt::hstring(L"ButtonBackground")), bg);
            btn.Resources().Insert(winrt::box_value(winrt::hstring(L"ButtonBackgroundPointerOver")), hoverBg);
            btn.Resources().Insert(winrt::box_value(winrt::hstring(L"ButtonBackgroundPressed")), pressedBg);
            btn.Resources().Insert(winrt::box_value(winrt::hstring(L"ButtonBorderBrush")), bd);
            btn.Resources().Insert(winrt::box_value(winrt::hstring(L"ButtonBorderBrushPointerOver")), MakeBrush(0x32, 0xFF, 0xFF, 0xFF));
            auto lbl = MakeText(nullptr, text, 11, false, 0.92);
            btn.Content(lbl);
            return btn;
        };

        for (const auto& device : devices) {
            wuxc::Border card;
            card.CornerRadius(CornerRadius{winui ? 6.0 : 8.0, winui ? 6.0 : 8.0,
                                           winui ? 6.0 : 8.0, winui ? 6.0 : 8.0});
            card.Background(MakeBrush(device.isEnabled ? (winui ? 0x0F : 0x10) : 0x06,
                                      0xFF, 0xFF, 0xFF));
            card.BorderBrush(MakeBrush(device.isEnabled ? 0x1A : 0x0E, 0xFF, 0xFF, 0xFF));
            card.BorderThickness(Thickness{1, 1, 1, 1});
            try { card.BackgroundSizing(wuxc::BackgroundSizing::InnerBorderEdge); } catch (...) {}
            card.Padding(Thickness{10, 7, 10, 7});
            card.Margin(Thickness{0, 2, 0, 2});

            wuxc::StackPanel col;
            col.Spacing(6);

            wuxc::Grid topRow;
            topRow.ColumnSpacing(8);
            wuxc::ColumnDefinition cIcon; cIcon.Width(GridLength{0, GridUnitType::Auto});
            wuxc::ColumnDefinition cName; cName.Width(GridLength{1, GridUnitType::Star});
            wuxc::ColumnDefinition cBadge; cBadge.Width(GridLength{0, GridUnitType::Auto});
            topRow.ColumnDefinitions().Append(cIcon);
            topRow.ColumnDefinitions().Append(cName);
            topRow.ColumnDefinitions().Append(cBadge);

            FrameworkElement glyph{nullptr};
            if (flow == eRender) {
                glyph = BuildVectorIcon(nullptr, icons::kHeadphoneFill,
                                        icons::kHeadphoneStroke, 24, 16, 1.6);
            } else {
                glyph = iconpacks::MakeInlineGlyph(L"\uE720", 15.0, FontColorBrush());
            }
            glyph.VerticalAlignment(VerticalAlignment::Center);
            glyph.Opacity(device.isEnabled ? 1.0 : 0.35);
            wuxc::Grid::SetColumn(glyph, 0);
            topRow.Children().Append(glyph);

            auto nameTb = MakeText(nullptr, device.name, 12.5, device.isDefault,
                                   device.isEnabled ? 0.95 : 0.38);
            nameTb.TextTrimming(TextTrimming::CharacterEllipsis);
            nameTb.MaxLines(1);
            nameTb.VerticalAlignment(VerticalAlignment::Center);
            wuxc::Grid::SetColumn(nameTb, 1);
            topRow.Children().Append(nameTb);

            if (device.isDefault && device.isEnabled) {
                wuxc::Border defPill;
                defPill.CornerRadius(CornerRadius{4, 4, 4, 4});
                defPill.Padding(Thickness{7, 2, 7, 2});
                defPill.Background(MakeBrush(0x16, 0xFF, 0xFF, 0xFF));
                defPill.BorderBrush(MakeBrush(0x28, 0xFF, 0xFF, 0xFF));
                defPill.BorderThickness(Thickness{1, 1, 1, 1});
                defPill.VerticalAlignment(VerticalAlignment::Center);
                auto defTxt = MakeText(nullptr, L"Default", 10.5, true, 0.92);
                defPill.Child(defTxt);
                wuxc::Grid::SetColumn(defPill, 2);
                topRow.Children().Append(defPill);
            }
            col.Children().Append(topRow);

            wuxc::StackPanel actions;
            actions.Orientation(wuxc::Orientation::Horizontal);
            actions.Spacing(6);
            actions.Margin(Thickness{24, 0, 0, 0});

            std::wstring deviceId = device.id;
            if (device.isEnabled) {
                if (!device.isDefault) {
                    auto defBtn = makeActionPill(L"Make default");
                    defBtn.Click([deviceId](auto&&, auto&&) {
                        if (!audio::SetDefaultDevice(deviceId)) {
                            Wh_Log(L"Failed to set default audio device");
                        }
                        RefreshSoundButtonIcon();
                        RepopulateLater(PopulateSoundPanel);
                    });
                    actions.Children().Append(defBtn);
                }
                auto disBtn = makeActionPill(L"Disable", true);
                disBtn.Click([deviceId](auto&&, auto&&) {
                    audio::SetDeviceEnabled(deviceId, false);
                    RefreshSoundButtonIcon();
                    RepopulateLater(PopulateSoundPanel);
                });
                actions.Children().Append(disBtn);
            } else {
                auto enBtn = makeActionPill(L"Enable");
                enBtn.Click([deviceId](auto&&, auto&&) {
                    audio::SetDeviceEnabled(deviceId, true);
                    RefreshSoundButtonIcon();
                    RepopulateLater(PopulateSoundPanel);
                });
                actions.Children().Append(enBtn);
            }

            col.Children().Append(actions);
            card.Child(col);
            expander.body.Children().Append(card);
        }
        children.Append(expander.root);
    };

    buildAudioDeviceSection(L"Output device", eRender, &g_outputDevicesExpanded,
                            L"No output devices found.");
    buildAudioDeviceSection(L"Input device", eCapture, &g_inputDevicesExpanded,
                            L"No input devices found.");

    {
        auto sessions = audio::EnumerateSessions();
        std::wstring subtitle =
            sessions.empty()
                ? std::wstring(L"Nothing is playing")
                : std::to_wstring(sessions.size()) +
                      (sessions.size() == 1 ? L" app" : L" apps");

        auto expander = MakeExpander(L"App volume mixer", subtitle, &g_appMixerExpanded, nullptr);

        if (sessions.empty()) {
            expander.body.Children().Append(
                MakeStatusText(L"No apps are currently playing audio."));
        }
        for (const auto& session : sessions) {
            wuxc::StackPanel row;
            row.Spacing(0);
            row.Margin(Thickness{10, 4, 10, 4});
            row.Children().Append(MakeText(nullptr, session.name, 12, false, 0.85));

            auto makeMixerGlyph = [](int vol) -> FrameworkElement {
                if (iconpacks::IsWinUI()) {
                    PCWSTR g = (vol <= 0) ? L"\uE992" : (vol <= 33 ? L"\uE993" : (vol <= 66 ? L"\uE994" : L"\uE995"));
                    return iconpacks::Glyph(g, 15);
                }
                return BuildSpeakerIcon(15, vol, vol <= 0);
            };
            wuxc::ContentControl iconHost;
            iconHost.IsTabStop(false);
            iconHost.VerticalAlignment(VerticalAlignment::Center);
            iconHost.Content(makeMixerGlyph(session.volume));

            auto control = session.control;
            auto weakIconHost = winrt::make_weak(iconHost);
            row.Children().Append(MakeSliderRow(iconHost, session.volume, [control, weakIconHost, makeMixerGlyph](int value) {
                if (control) {
                    control->SetMasterVolume(std::clamp(value, 0, 100) / 100.0f, nullptr);
                    if (value > 0) {
                        control->SetMute(FALSE, nullptr);
                    }
                }
                if (auto ih = weakIconHost.get()) {
                    try { ih.Content(makeMixerGlyph(value)); } catch (...) {}
                }
            }));
            expander.body.Children().Append(row);
        }
        children.Append(expander.root);
    }

    children.Append(MakeDivider()); 
    children.Append(MakeSettingsLink(L"Sound settings", L"ms-settings:sound"));
    StripControlCenterSubHeaderIfHosted(g_soundPanel);
    ApplyControlStylesToPopupRoot(g_soundPanel.as<FrameworkElement>());
}

FrameworkElement BuildWifiIcon(double size, int signal, bool connected) {
    int level = 0;
    if (connected) {
        if (signal >= 75) level = 3;
        else if (signal >= 50) level = 2;
        else if (signal >= 25) level = 1;
    }

    std::wstring outerPath =
        L"M61.5917 17.7222C79.4636 17.723 96.6521 24.3489 109.605 36.2305C110.58 37.1478 112.139 37.1362 113.1 36.2045"
        L"L122.423 27.1255C122.909 26.653 123.181 26.0129 123.177 25.3469C123.173 24.6809 122.894 24.0439 122.402 23.5769"
        L"C88.4054 -7.85896 34.7726 -7.85896 0.776469 23.5769C0.284012 24.0436 0.00459724 24.6804 0.0000562216 25.3463"
        L"C-0.00448479 26.0123 0.266222 26.6526 0.752273 27.1255L10.0785 36.2045C11.0385 37.1376 12.5987 37.1492 13.5734 36.2305"
        L"C26.5276 24.3481 43.7181 17.7222 61.5917 17.7222Z";
    std::wstring middlePath =
        L"M61.5676 48.0483C71.321 48.0477 80.7264 51.7249 87.9562 58.3656C88.934 59.308 90.4744 59.2876 91.4276 58.3195"
        L"L100.678 48.8392C101.165 48.342 101.435 47.6674 101.428 46.9664C101.421 46.2654 101.137 45.5965 100.64 45.1094"
        L"C78.6243 24.3363 44.5296 24.3363 22.5135 45.1094C22.0162 45.5965 21.7324 46.2657 21.7259 46.9669"
        L"C21.7194 47.6681 21.9906 48.3427 22.4788 48.8392L31.7262 58.3195C32.6795 59.2876 34.2198 59.308 35.1977 58.3656"
        L"C42.4227 51.7293 51.8206 48.0524 61.5676 48.0483Z";
    std::wstring bottomPath =
        L"M79.7076 68.1222C79.7214 68.8792 79.4551 69.6091 78.9715 70.1395L63.3304 87.7786C62.8719 88.297 62.2468 88.5888 61.5946 88.5888"
        L"C60.9423 88.5888 60.3172 88.297 59.8587 87.7786L44.215 70.1395C43.7317 69.6087 43.4659 68.8786 43.4802 68.1216"
        L"C43.4946 67.3645 43.7878 66.6477 44.2907 66.1402C54.2797 56.6989 68.9094 56.6989 78.8984 66.1402"
        L"C79.401 66.6481 79.6938 67.3652 79.7076 68.1222Z";

    const wchar_t* dimOp = L"0.3";
    const wchar_t* fullOp = L"1.0";
    const wchar_t* outerOp = (level >= 3) ? fullOp : dimOp;
    const wchar_t* middleOp = (level >= 2) ? fullOp : dimOp;
    const wchar_t* bottomOp = connected ? fullOp : dimOp;

    std::wstring brush = GetEffectiveIconColorString();

    std::wstring xaml =
        L"<Viewbox xmlns=\"http://schemas.microsoft.com/winfx/2006/xaml/presentation\" "
        L"Stretch=\"Uniform\" Width=\"" + std::to_wstring(size) + L"\" Height=\"" + std::to_wstring(size) + L"\">"
        L"<Grid Width=\"124\" Height=\"89\">"
        L"<Path Data=\"" + EscapeXmlAttr(outerPath) + L"\" Fill=\"" + brush + L"\" Opacity=\"" + outerOp + L"\"/>"
        L"<Path Data=\"" + EscapeXmlAttr(middlePath) + L"\" Fill=\"" + brush + L"\" Opacity=\"" + middleOp + L"\"/>"
        L"<Path Data=\"" + EscapeXmlAttr(bottomPath) + L"\" Fill=\"" + brush + L"\" Opacity=\"" + bottomOp + L"\"/>"
        L"</Grid></Viewbox>";

    try {
        auto element = Markup::XamlReader::Load(xaml).as<FrameworkElement>();
        element.Name(L"WifiIcon");
        return element;
    } catch (winrt::hresult_error const& ex) {
        Wh_Log(L"Failed to build wifi icon: %08X", static_cast<unsigned int>(ex.code().value));
        return nullptr;
    } catch (...) {
        return nullptr;
    }
}

void RefreshWifiButtonIcon() {
    if (!g_wifiButton) {
        return;
    }
    auto status = wifi::GetStatus();
    if (auto icon = iconpacks::WifiIcon(status.signal, status.connected && status.radioOn)) {
        g_wifiButton.Content(icon);
    }
}

void SyncWifiStateFast() {
    if (g_wifiScanning.load() || g_wifiSyncing.load()) {
        return;
    }
    if (!g_wifiConnectingSSID.empty() || !g_wifiDisconnectingSSID.empty()) {
        return;
    }
    g_wifiSyncing.store(true);
    const uint64_t startVer = g_wifiNetworksVersion.load();
    RunInBackground([startVer] {
        struct SyncReset { ~SyncReset() { g_wifiSyncing.store(false); } } reset;
        if (WaitForSingleObject(g_stopEvent, 0) == WAIT_OBJECT_0) {
            return;
        }
        auto networks = wifi::EnumerateNetworks();
        RunOnUiThread([networks = std::move(networks), startVer]() mutable {
            if (g_wifiNetworksVersion.load() != startVer) {
                return;
            }
            g_wifiNetworks = std::move(networks);
            g_wifiLastEnumTick.store(GetTickCount64());
            RefreshWifiButtonIcon();
            PopulateWifiPanel();
        });
    });
}

void StartWifiScan() {
    if (g_wifiScanning.exchange(true)) {
        return;
    }
    const uint64_t startVer = g_wifiNetworksVersion.load();
    g_wifiLastScanTick.store(GetTickCount64());
    RepopulateLater(PopulateWifiPanel);
    RunInBackground([startVer] {
        if (WaitForSingleObject(g_stopEvent, 0) == WAIT_OBJECT_0) {
            g_wifiScanning = false;
            return;
        }
        wifi::RequestScanAndWait(g_stopEvent, 2600);
        auto networks = wifi::EnumerateNetworks();
        RunOnUiThread([networks = std::move(networks), startVer]() mutable {
            g_wifiScanning = false;
            g_wifiLastScanTick.store(GetTickCount64());
            if (g_wifiNetworksVersion.load() == startVer) {
                g_wifiNetworks = std::move(networks);
                g_wifiLastEnumTick.store(GetTickCount64());
            }
            RefreshWifiButtonIcon();
            PopulateWifiPanel();
        });
    });
}

void ConnectToWifi(const wifi::Network& network, const std::wstring& password) {
    RunInBackground([network, password] {
        if (WaitForSingleObject(g_stopEvent, 0) == WAIT_OBJECT_0) return;
        bool ok = wifi::Connect(network, password);
        bool connected = false;
        if (ok) {
            const ULONGLONG startTick = GetTickCount64();
            while (GetTickCount64() - startTick < 4500) {
                if (WaitForSingleObject(g_stopEvent, 100) == WAIT_OBJECT_0) {
                    return;
                }
                auto st = wifi::GetStatus();
                if (!st.radioOn) {
                    break;
                }
                if (st.connected && _wcsicmp(st.ssid.c_str(), network.ssid.c_str()) == 0) {
                    connected = true;
                    break;
                }
                // Once past initial handshake window, if adapter dropped back to
                // idle/disconnected (e.g. bad password), stop waiting early.
                if (!st.connecting && !st.connected && (GetTickCount64() - startTick) >= 1100) {
                    break;
                }
            }
        }

        if (!connected && !network.hasProfile) {
            wifi::ForgetProfile(network.ssid);
        }

        auto networks = wifi::EnumerateNetworks();
        if (!connected) {
            for (const auto& candidate : networks) {
                if (candidate.ssid == network.ssid && candidate.connected) {
                    connected = true;
                    break;
                }
            }
        }

        g_wifiNetworksVersion.fetch_add(1);
        RunOnUiThread([networks = std::move(networks), connected, network]() mutable {
            g_wifiNetworks = std::move(networks);
            g_wifiLastEnumTick.store(GetTickCount64());
            g_wifiPasswordPrompt = false;
            g_wifiConnectingSSID.clear();
            if (!connected) {
                g_wifiPromptError = L"Couldn't connect to " + network.ssid + L".";
            }
            RefreshWifiButtonIcon();
            PopulateWifiPanel();
        });
    });
}

void BuildWifiPasswordView(const wf::Collections::IVector<UIElement>& children) {
    g_flyoutInputTransitionUntil.store(GetTickCount64() + 500);
    children.Append(MakePanelTitle(L"Connect to " + g_wifiPromptNetwork.ssid));

    if (!g_wifiPromptError.empty()) {
        auto error = MakeText(nullptr, g_wifiPromptError, 12, false, 0.9);
        error.Foreground(MakeBrush(0xFF, 0xFF, 0x8A, 0x80));
        error.TextWrapping(TextWrapping::Wrap);
        error.Margin(Thickness{10, 0, 10, 6});
        children.Append(error);
    }

    children.Append(MakeStatusText(L"Enter the network security key."));

    wuxc::PasswordBox passwordBox;
    passwordBox.Name(L"WifiPasswordBox");
    passwordBox.PlaceholderText(L"Password");
    passwordBox.Margin(Thickness{10, 0, 10, 8});
    passwordBox.Padding(Thickness{10, 7, 10, 7});
    passwordBox.CornerRadius(MakeCorner(EffectiveRowCorner()));
    passwordBox.Background(MakeBrush(0xFF, 0x30, 0x30, 0x30));
    passwordBox.Foreground(MakeBrush(0xFF, 0xFF, 0xFF, 0xFF));
    passwordBox.AllowFocusOnInteraction(true);
    passwordBox.IsTabStop(true);
    StyleWinUI3TextControlResources(passwordBox);
    children.Append(passwordBox);
    try { passwordBox.Focus(FocusState::Programmatic); } catch (...) {}

    auto submit = [passwordBox] {
        std::wstring password{passwordBox.Password()};
        wifi::Network target = g_wifiPromptNetwork;
        g_wifiPasswordPrompt = false;
        g_wifiPromptError.clear();
        g_wifiConnectingSSID = target.ssid;
        RepopulateLater(PopulateWifiPanel);
        ConnectToWifi(target, password);
    };

    passwordBox.KeyDown([submit](auto&&, Input::KeyRoutedEventArgs const& args) {
        if (args.Key() == winrt::Windows::System::VirtualKey::Enter) {
            args.Handled(true);
            submit();
        }
    });

    wuxc::Grid buttons;
    buttons.ColumnSpacing(8);
    buttons.Margin(Thickness{10, 0, 10, 4});
    for (int i = 0; i < 2; i++) {
        wuxc::ColumnDefinition column;
        column.Width(GridLength{1, GridUnitType::Star});
        buttons.ColumnDefinitions().Append(column);
    }

    auto connect = MakeGhostButton(L"WifiConnectButton", kRowCorner);
    connect.Padding(Thickness{12, 8, 12, 8});
    connect.HorizontalAlignment(HorizontalAlignment::Stretch);
    connect.HorizontalContentAlignment(HorizontalAlignment::Center);
    auto connectTxt = MakeText(nullptr, L"Connect", 12, true, 1.0);
    connect.Content(connectTxt);
    StyleWinUI3AccentButton(connect, connectTxt);
    connect.Click([submit](auto&&, auto&&) { submit(); });
    wuxc::Grid::SetColumn(connect, 0);
    buttons.Children().Append(connect);

    auto cancel = MakeGhostButton(L"WifiCancelButton", kRowCorner);
    cancel.Background(MakeBrush(0x18, 0xFF, 0xFF, 0xFF));
    cancel.Padding(Thickness{12, 8, 12, 8});
    cancel.HorizontalAlignment(HorizontalAlignment::Stretch);
    cancel.HorizontalContentAlignment(HorizontalAlignment::Center);
    cancel.Content(MakeText(nullptr, L"Cancel", 12));
    cancel.Click([](auto&&, auto&&) {
        g_wifiPasswordPrompt = false;
        g_wifiPromptError.clear();
        RepopulateLater(PopulateWifiPanel);
    });
    wuxc::Grid::SetColumn(cancel, 1);
    buttons.Children().Append(cancel);

    children.Append(buttons);

    passwordBox.AddHandler(UIElement::PointerPressedEvent(),
        winrt::box_value(Input::PointerEventHandler(
            [passwordBox](auto&&, auto&&) {
                ActivateChildFlyoutInput(passwordBox, true);
            })), true);
    passwordBox.Loaded([passwordBox](auto&&, auto&&) {
        RunOnUiThread([passwordBox] {
            ActivateChildFlyoutInput(passwordBox, true);
        });
    });
}

// Content signatures of the Wi-Fi / Bluetooth panels. They let a re-scan skip a
// full rebuild when nothing it renders changed. Any code that resets the panel
// to a transient state (the "Loading..." placeholder) must invalidate them, or
// the rebuild that follows would be mistaken for a no-op.
static std::wstring g_wifiPanelSig;
static std::wstring g_btPanelSig;

void InvalidateWifiPanelSignature() { g_wifiPanelSig.clear(); }
void InvalidateBluetoothPanelSignature() { g_btPanelSig.clear(); }

void PopulateWifiPanel() {
    if (!g_wifiPanel) {
        return;
    }

    // Rebuilding the panel means throwing away and re-creating dozens of XAML
    // elements (and re-walking the whole visual tree for styling). The Wi-Fi
    // list is re-scanned every 30 s while the flyout is open, so doing that on
    // every scan was pure churn. Skip the rebuild entirely when the rendered
    // content would be identical.
    {
        std::wstring sig = IsWinUI3StyleMode() ? L"u1|w1|" : L"u0|w1|";
        sig += g_wifiPasswordPrompt ? L"1" : L"0";
        sig += L"|";
        sig += g_wifiPromptError;
        sig += L"|";
        sig += g_wifiScanning ? L"1" : L"0";
        sig += L"|";
        sig += g_wifiConnectingSSID;
        sig += L"|";
        sig += g_wifiDisconnectingSSID;
        sig += L"|";
        auto st = wifi::GetStatus();
        sig += st.available ? L"1" : L"0";
        sig += st.radioOn ? L"1" : L"0";
        sig += L"|";
        for (const auto& n : g_wifiNetworks) {
            sig += n.ssid;
            sig += L",";
            sig += std::to_wstring(n.signal);
            sig += n.connected ? L"c" : L"-";
            sig += n.hasProfile ? L"p" : L"-";
            sig += n.secured ? L"s" : L"-";
            sig += L";";
        }
        if (g_wifiPanelSig == sig && g_wifiPanel.Children().Size() > 0) {
            return;
        }
        g_wifiPanelSig = sig;
    }

    const bool hadExisting = g_wifiPanel.Children().Size() > 0;
    const double prevShellH = hadExisting ? CaptureFlyoutShellHeight(g_wifiPanel.as<FrameworkElement>()) : 0.0;

    g_populatingPanel = true;
    struct Guard {
        double prevH;
        ~Guard() {
            g_populatingPanel = false;
            try { StripControlCenterSubHeaderIfHosted(g_wifiPanel); } catch (...) {}
            try { ApplyControlStylesToPopupRoot(g_wifiPanel.as<FrameworkElement>()); } catch (...) {}
            if (prevH > 24.0) {
                try {
                    AnimateFlyoutShellResize(g_wifiPanel.as<FrameworkElement>(), nullptr, nullptr, nullptr, 30, prevH);
                } catch (...) {}
            }
        }
    } guard{prevShellH};

    auto children = g_wifiPanel.Children();
    children.Clear();

    if (g_wifiPasswordPrompt) {
        BuildWifiPasswordView(children);
        return;
    }

    auto status = wifi::GetStatus();

    wuxc::Grid headerGrid;
    headerGrid.Name(L"WifiHeaderGrid");
    headerGrid.Margin(Thickness{4, 2, 0, 6});
    headerGrid.HorizontalAlignment(HorizontalAlignment::Stretch);

    wuxc::ColumnDefinition leftColumn;
    leftColumn.Width(GridLength{1, GridUnitType::Star});
    headerGrid.ColumnDefinitions().Append(leftColumn);

    wuxc::ColumnDefinition rightColumn;
    rightColumn.Width(GridLength{0, GridUnitType::Auto});
    headerGrid.ColumnDefinitions().Append(rightColumn);

    wuxc::StackPanel leftStack;
    leftStack.Name(L"WifiHeaderLeftStack");
    leftStack.Orientation(wuxc::Orientation::Horizontal);
    leftStack.Spacing(8);
    leftStack.VerticalAlignment(VerticalAlignment::Center);

    auto titleBlock = MakeText(L"FlyoutTitle", L"Wi-Fi", 15, true);
    leftStack.Children().Append(titleBlock);

    wuxc::ProgressRing wifiProgress;
    wifiProgress.Name(L"WifiProgressRing");
    wifiProgress.IsActive(true);
    wifiProgress.Width(14);
    wifiProgress.Height(14);
    wifiProgress.VerticalAlignment(VerticalAlignment::Center);
    wifiProgress.Foreground(MakeBrush(0xFF, GetSystemAccentColor().R, GetSystemAccentColor().G, GetSystemAccentColor().B));
    wifiProgress.Opacity(g_wifiScanning ? 1.0 : 0.3);
    leftStack.Children().Append(wifiProgress);

    wuxc::Grid::SetColumn(leftStack, 0);
    headerGrid.Children().Append(leftStack);

    wuxc::StackPanel rightStack;
    rightStack.Name(L"WifiHeaderRightStack");
    rightStack.Orientation(wuxc::Orientation::Horizontal);
    rightStack.Spacing(4);
    rightStack.VerticalAlignment(VerticalAlignment::Center);

    auto refreshButton = MakeGhostButton(L"WifiRefreshButton", EffectiveRowCorner());
    refreshButton.Padding(Thickness{6, 6, 6, 6});
    if (IsWinUI3StyleMode()) {
        refreshButton.Background(MakeBrush(0x0F, 0xFF, 0xFF, 0xFF));
        refreshButton.BorderBrush(MakeBrush(0x1C, 0xFF, 0xFF, 0xFF));
        refreshButton.BorderThickness(Thickness{1, 1, 1, 1});
    }
    refreshButton.Content(iconpacks::IsWinUI()
        ? iconpacks::Glyph(L"\uE72C", 16)
        : BuildVectorIcon(nullptr, L"M12 20c-2.21665 0 -4.10415 -0.77915 -5.6625 -2.3375C4.779165 16.10415 4 14.21665 4 12c0 -2.21665 0.779165 -4.10415 2.3375 -5.6625C7.89585 4.779165 9.78335 4 12 4c1.41665 0 2.65835 0.2875 3.725 0.8625 1.06665 0.575 1.99165 1.3625 2.775 2.3625V4h1.5v6.35H13.65v-1.5h4.2c-0.63335 -1 -1.44165 -1.80835 -2.425 -2.425C14.44165 5.80835 13.3 5.5 12 5.5c-1.81665 0 -3.35415 0.62915 -4.6125 1.8875C6.12915 8.64585 5.5 10.18335 5.5 12c0 1.81665 0.62915 3.35415 1.8875 4.6125C8.64585 17.87085 10.18335 18.5 12 18.5c1.38335 0 2.65 -0.39585 3.8 -1.1875s1.95 -1.8375 2.4 -3.1375h1.55c-0.48335 1.75 -1.44165 3.15835 -2.875 4.225C15.44165 19.46665 13.81665 20 12 20Z", L"", 24, 20, 1.7));
    refreshButton.Click([](auto&&, auto&&) {
        StartWifiScan();
    });
    rightStack.Children().Append(refreshButton);

    wuxc::ToggleSwitch toggle;
    toggle.Name(L"WifiHeaderToggle");
    g_namedElements.insert_or_assign(L"WifiHeaderToggle", toggle);
    StyleWinUI3ToggleSwitch(toggle);
    toggle.OnContent(winrt::box_value(L""));
    toggle.OffContent(winrt::box_value(L""));
    toggle.MinWidth(50);
    toggle.Width(50);
    toggle.HorizontalAlignment(HorizontalAlignment::Right);
    toggle.HorizontalContentAlignment(HorizontalAlignment::Right);
    toggle.VerticalAlignment(VerticalAlignment::Center);
    toggle.Margin(Thickness{0, 0, 4, 0});
    toggle.IsOn(status.radioOn);
    toggle.Toggled([](auto&& sender, auto&&) {
        if (g_populatingPanel) return;
        bool on = sender.template as<wuxc::ToggleSwitch>().IsOn();
        RunInBackground([on] {
            if (WaitForSingleObject(g_stopEvent, 0) == WAIT_OBJECT_0) return;
            wifi::SetRadio(on);
            for (int i = 0; i < 20; ++i) {
                if (WaitForSingleObject(g_stopEvent, 80) == WAIT_OBJECT_0) return;
                if (wifi::GetStatus().radioOn == on) {
                    break;
                }
            }
            auto networks = on ? wifi::EnumerateNetworks() : std::vector<wifi::Network>{};
            g_wifiNetworksVersion.fetch_add(1);
            RunOnUiThread([networks = std::move(networks), on]() mutable {
                g_wifiNetworks = std::move(networks);
                g_wifiLastEnumTick.store(GetTickCount64());
                g_wifiConnectingSSID.clear();
                g_wifiDisconnectingSSID.clear();
                RefreshWifiButtonIcon();
                PopulateWifiPanel();
                if (on) {
                    StartWifiScan();
                }
            });
        });
    });
    rightStack.Children().Append(toggle);

    wuxc::Grid::SetColumn(rightStack, 1);
    headerGrid.Children().Append(rightStack);

    children.Append(headerGrid);

    if (!status.available) {
        children.Append(MakeStatusText(L"No Wi-Fi adapter was found on this PC."));
        return;
    }
    if (!status.radioOn) {
        children.Append(MakeStatusText(L"Wi-Fi is off."));
        return;
    }

    if (!g_wifiPromptError.empty()) {
        auto error = MakeText(nullptr, g_wifiPromptError, 12, false, 0.9);
        error.Foreground(MakeBrush(0xFF, 0xFF, 0x8A, 0x80));
        error.TextWrapping(TextWrapping::Wrap);
        error.Margin(Thickness{10, 0, 10, 4});
        children.Append(error);
    }

    if (g_wifiNetworks.empty()) {
        children.Append(MakeStatusText(g_wifiScanning ? L"Scanning for networks…"
                                                      : L"No networks found."));
    }

    // Shared connect action: re-read the network list once the radio settled,
    // exactly like the old row click did.
    auto connectNow = [](wifi::Network target) {
        g_wifiPromptError.clear();
        if (target.secured && !target.hasProfile) {
            g_wifiPasswordPrompt = true;
            g_wifiPromptNetwork = target;
            RepopulateLater(PopulateWifiPanel);
            return;
        }
        g_wifiConnectingSSID = target.ssid;
        RepopulateLater(PopulateWifiPanel);
        ConnectToWifi(target, L"");
    };

    auto forgetNow = [](wifi::Network target) {
        g_wifiPromptError.clear();
        g_wifiDisconnectingSSID = target.ssid;
        RepopulateLater(PopulateWifiPanel);
        RunInBackground([target] {
            if (WaitForSingleObject(g_stopEvent, 0) == WAIT_OBJECT_0) return;
            if (target.connected) {
                wifi::Disconnect();
            }
            const std::wstring prof = target.profileName.empty() ? target.ssid : target.profileName;
            wifi::ForgetProfile(prof);
            if (!target.profileName.empty() && target.profileName != target.ssid) {
                wifi::ForgetProfile(target.ssid);
            }
            std::vector<wifi::Network> networks;
            for (int i = 0; i < 10; ++i) {
                if (WaitForSingleObject(g_stopEvent, 80) == WAIT_OBJECT_0) return;
                networks = wifi::EnumerateNetworks();
                bool stillSaved = false;
                for (const auto& n : networks) {
                    if (n.ssid == target.ssid && (n.connected || n.hasProfile)) {
                        stillSaved = true;
                        break;
                    }
                }
                if (!stillSaved) break;
            }
            g_wifiNetworksVersion.fetch_add(1);
            RunOnUiThread([networks = std::move(networks)]() mutable {
                g_wifiNetworks = std::move(networks);
                g_wifiLastEnumTick.store(GetTickCount64());
                g_wifiDisconnectingSSID.clear();
                RefreshWifiButtonIcon();
                PopulateWifiPanel();
            });
        });
    };

    // Ensure Connected -> Saved/Paired -> Unpaired ordering even on cached lists.
    std::stable_sort(g_wifiNetworks.begin(), g_wifiNetworks.end(),
                     [](const wifi::Network& a, const wifi::Network& b) {
                         if (a.connected != b.connected) return a.connected;
                         if (a.hasProfile != b.hasProfile) return a.hasProfile;
                         return a.signal > b.signal;
                     });

    for (const auto& network : g_wifiNetworks) {
        auto icon = iconpacks::WifiIcon(network.signal, true);
        const bool isConnecting = (network.ssid == g_wifiConnectingSSID);
        const bool isDisconnecting = (network.ssid == g_wifiDisconnectingSSID);
        std::wstring subtitle;
        if (isConnecting) {
            subtitle = L"Connecting...";
        } else if (isDisconnecting) {
            subtitle = L"Disconnecting...";
        } else if (network.connected) {
            subtitle = L"Connected";
        } else if (network.hasProfile) {
            subtitle = network.secured ? L"Saved, secured" : L"Saved";
        } else if (network.secured) {
            subtitle = L"Secured";
        } else {
            subtitle = L"Open";
        }

        wifi::Network captured = network;
        FrameworkElement topTrailing{nullptr};
        if (isConnecting || isDisconnecting) {
            wuxc::ProgressRing rowRing;
            rowRing.IsActive(true);
            rowRing.Width(16);
            rowRing.Height(16);
            rowRing.VerticalAlignment(VerticalAlignment::Center);
            rowRing.Foreground(MakeBrush(0xFF, GetSystemAccentColor().R, GetSystemAccentColor().G,
                                         GetSystemAccentColor().B));
            topTrailing = rowRing;
        } else if (network.connected) {
            wuxc::StackPanel btnStack;
            btnStack.Orientation(wuxc::Orientation::Horizontal);
            btnStack.Spacing(6);
            btnStack.VerticalAlignment(VerticalAlignment::Center);

            auto discBtn = MakeActionChip(nullptr, L"Disconnect", [captured] {
                g_wifiPromptError.clear();
                g_wifiDisconnectingSSID = captured.ssid;
                RepopulateLater(PopulateWifiPanel);
                RunInBackground([] {
                    if (WaitForSingleObject(g_stopEvent, 0) == WAIT_OBJECT_0) return;
                    wifi::Disconnect();
                    for (int i = 0; i < 20; ++i) {
                        if (WaitForSingleObject(g_stopEvent, 60) == WAIT_OBJECT_0) return;
                        if (!wifi::GetStatus().connected) {
                            break;
                        }
                    }
                    auto networks = wifi::EnumerateNetworks();
                    g_wifiNetworksVersion.fetch_add(1);
                    RunOnUiThread([networks = std::move(networks)]() mutable {
                        g_wifiNetworks = std::move(networks);
                        g_wifiLastEnumTick.store(GetTickCount64());
                        g_wifiDisconnectingSSID.clear();
                        RefreshWifiButtonIcon();
                        PopulateWifiPanel();
                    });
                });
            });

            auto forgetBtn = MakeActionChip(nullptr, L"Forget",
                                            [captured, forgetNow] { forgetNow(captured); });

            btnStack.Children().Append(discBtn);
            btnStack.Children().Append(forgetBtn);
            topTrailing = btnStack;
        } else if (network.hasProfile) {
            wuxc::StackPanel btnStack;
            btnStack.Orientation(wuxc::Orientation::Horizontal);
            btnStack.Spacing(6);
            btnStack.VerticalAlignment(VerticalAlignment::Center);

            auto connectBtn = MakeActionChip(nullptr, L"Connect",
                                             [captured, connectNow] { connectNow(captured); });
            auto forgetBtn = MakeActionChip(nullptr, L"Forget",
                                            [captured, forgetNow] { forgetNow(captured); });

            btnStack.Children().Append(connectBtn);
            btnStack.Children().Append(forgetBtn);
            topTrailing = btnStack;
        } else {
            // Every network that is not connected gets a Connect button, so
            // connecting is always an explicit, visible action.
            auto connectBtn = MakeActionChip(nullptr, L"Connect",
                                             [captured, connectNow] { connectNow(captured); });
            topTrailing = connectBtn;
        }
        // Single-row card layout keeps action buttons inline with the network name in all cases.
        children.Append(MakeDeviceCardRow(icon, network.ssid, subtitle, topTrailing,
                                          nullptr, L"WifiNetworkRow", network.connected));
    }

    children.Append(MakeDivider());
    children.Append(MakeSettingsLink(L"Network settings", L"ms-settings:network-wifi"));
}

void RefreshBluetoothButtonIcon() {
    if (!g_bluetoothButton) {
        return;
    }
    const bool radioOn = bluetooth::IsRadioOn();
    int connectedBattery = -1;
    if (radioOn) {
        for (const auto& d : g_bluetoothDevices) {
            if (d.connected && d.batteryPercent >= 0) {
                connectedBattery = std::clamp(d.batteryPercent, 0, 100);
                break;
            }
        }
    }
    auto btIcon = iconpacks::BluetoothIcon(radioOn);
    if (radioOn && connectedBattery >= 0 && btIcon) {
        int levelIdx = std::clamp((connectedBattery + 5) / 10, 0, 10);
        wchar_t battGlyph[2] = { static_cast<wchar_t>(0xF5F2 + levelIdx), L'\0' };
        wuxc::FontIcon battIcon;
        if (connectedBattery <= 20) {
            battIcon.Name(L"BtBatteryLowIcon");
        }
        battIcon.FontFamily(wuxm::FontFamily(L"Segoe Fluent Icons, Segoe MDL2 Assets"));
        battIcon.Glyph(battGlyph);
        battIcon.FontSize(15);
        battIcon.UseLayoutRounding(true);
        battIcon.VerticalAlignment(VerticalAlignment::Center);
        battIcon.HorizontalAlignment(HorizontalAlignment::Center);
        battIcon.Foreground(connectedBattery <= 20
            ? MakeBrush(0xFF, 0xFF, 0x6B, 0x6B)
            : IconColorBrush());

        btIcon.VerticalAlignment(VerticalAlignment::Center);

        wuxc::Grid grid;
        grid.Name(L"BluetoothButtonContentGrid");
        grid.ColumnSpacing(2);
        grid.VerticalAlignment(VerticalAlignment::Center);
        grid.HorizontalAlignment(HorizontalAlignment::Center);
        wuxc::ColumnDefinition c0; c0.Width(GridLength{0, GridUnitType::Auto});
        wuxc::ColumnDefinition c1; c1.Width(GridLength{0, GridUnitType::Auto});
        grid.ColumnDefinitions().Append(c0);
        grid.ColumnDefinitions().Append(c1);
        wuxc::Grid::SetColumn(battIcon, 0);
        wuxc::Grid::SetColumn(btIcon, 1);
        grid.Children().Append(battIcon);
        grid.Children().Append(btIcon);
        g_bluetoothButton.Content(grid);
        return;
    }
    g_bluetoothButton.Content(btIcon);
}

// UI-thread only: appends recently discovered nearby unpaired devices (<25s)
// onto a fresh paired-only snapshot without ever reviving a removed/unpaired
// device that used to be paired.
void MergeRecentUnpairedBluetooth(std::vector<bluetooth::Device>& pairedDevices) {
    const ULONGLONG now = GetTickCount64();
    if (g_btRecentUnpaired.empty() || now - g_btRecentUnpairedTick.load() > 25000) {
        g_btRecentUnpaired.clear();
        return;
    }
    std::set<uint64_t> knownMacs;
    std::set<std::wstring> knownNames;
    for (const auto& d : pairedDevices) {
        uint64_t mac = d.address.ullLong & 0xFFFFFFFFFFFFULL;
        if (mac) knownMacs.insert(mac);
        std::wstring low = ToLowerCopy(TrimWs(d.name));
        if (!low.empty()) knownNames.insert(low);
    }
    for (const auto& u : g_btRecentUnpaired) {
        uint64_t mac = u.address.ullLong & 0xFFFFFFFFFFFFULL;
        std::wstring low = ToLowerCopy(TrimWs(u.name));
        if ((mac && knownMacs.count(mac)) || (!low.empty() && knownNames.count(low))) {
            continue;
        }
        bluetooth::Device copy = u;
        copy.paired = false;
        copy.connected = false;
        pairedDevices.push_back(std::move(copy));
        if (mac) knownMacs.insert(mac);
        if (!low.empty()) knownNames.insert(low);
    }
}

void SyncBluetoothStateFast() {
    if (g_bluetoothScanning.load() || g_bluetoothSyncing.load()) {
        return;
    }
    if (g_bluetoothConnectingAddress.load() != 0 || g_pairingDeviceAddress.load() != 0 ||
        g_bluetoothRemovingAddress.load() != 0) {
        return;
    }
    g_bluetoothSyncing.store(true);
    const uint64_t startVer = g_btDevicesVersion.load();
    RunInBackground([startVer] {
        struct SyncReset { ~SyncReset() { g_bluetoothSyncing.store(false); } } reset;
        if (WaitForSingleObject(g_stopEvent, 0) == WAIT_OBJECT_0) {
            return;
        }
        bool on = bluetooth::QueryRadioOnLive();
        auto devices = on ? bluetooth::Enumerate(false)
                          : std::vector<bluetooth::Device>{};
        RunOnUiThread([devices = std::move(devices), on, startVer]() mutable {
            if (g_btDevicesVersion.load() != startVer) {
                return;
            }
            if (!on) {
                g_btRecentUnpaired.clear();
            } else {
                MergeRecentUnpairedBluetooth(devices);
            }
            g_bluetoothDevices = std::move(devices);
            g_btLastEnumTick.store(GetTickCount64());
            RefreshBluetoothButtonIcon();
            PopulateBluetoothPanel();
        });
    });
}

void StartBluetoothScan(bool includeUnpaired) {
    if (g_bluetoothScanning.exchange(true)) {
        Wh_Log(L"Bluetooth scan already in progress");
        return;
    }
    const uint64_t startVer = g_btDevicesVersion.load();
    if (includeUnpaired) {
        g_btLastInquiryTick.store(GetTickCount64());
    }
    RepopulateLater(PopulateBluetoothPanel);
    Wh_Log(L"Starting Bluetooth scan (includeUnpaired=%d)", includeUnpaired ? 1 : 0);
    RunInBackground([includeUnpaired, startVer] {
        if (WaitForSingleObject(g_stopEvent, 0) == WAIT_OBJECT_0) {
            Wh_Log(L"Bluetooth scan cancelled (stop event)");
            g_bluetoothScanning = false;
            return;
        }
        bool on = bluetooth::QueryRadioOnLive();
        if (!on) {
            RunOnUiThread([startVer] {
                g_bluetoothScanning = false;
                if (g_btDevicesVersion.load() == startVer) {
                    g_btRecentUnpaired.clear();
                    g_bluetoothDevices.clear();
                    g_btLastEnumTick.store(GetTickCount64());
                }
                RefreshBluetoothButtonIcon();
                PopulateBluetoothPanel();
            });
            return;
        }
        auto devices = bluetooth::Enumerate(includeUnpaired);
        Wh_Log(L"Bluetooth scan found %d devices", (int)devices.size());
        RunOnUiThread([devices = std::move(devices), includeUnpaired, startVer]() mutable {
            g_bluetoothScanning = false;
            if (g_btDevicesVersion.load() == startVer) {
                if (includeUnpaired) {
                    g_btRecentUnpaired.clear();
                    for (const auto& d : devices) {
                        if (!d.paired && !d.connected) {
                            g_btRecentUnpaired.push_back(d);
                        }
                    }
                    g_btRecentUnpairedTick.store(GetTickCount64());
                    g_btLastInquiryTick.store(GetTickCount64());
                } else {
                    MergeRecentUnpairedBluetooth(devices);
                }
                g_bluetoothDevices = std::move(devices);
                g_btLastEnumTick.store(GetTickCount64());
            }
            RefreshBluetoothButtonIcon();
            PopulateBluetoothPanel();
        });
    });
}

void RefreshBluetoothRadioState() {
    RunInBackground([] {
        bluetooth::QueryRadioOnLive();
        RunOnUiThread([] {
            RefreshBluetoothButtonIcon();
            const bool btInCC = (g_controlCenterFlyout && g_controlCenterFlyout.IsOpen() &&
                                 g_ccNav.activeSubView == L"bluetooth");
            if ((g_bluetoothFlyout && g_bluetoothFlyout.IsOpen()) || btInCC) {
                PopulateBluetoothPanel();
            }
        });
    });
}

void PopulateBluetoothPanel() {
    if (!g_bluetoothPanel) {
        return;
    }

    // Same idea as the Wi-Fi panel: the device list is re-scanned every 15 s
    // while the flyout is open, so only rebuild when something it renders
    // actually changed.
    {
        std::wstring sig = IsWinUI3StyleMode() ? L"u1|b1|" : L"u0|b1|";
        sig += g_bluetoothScanning ? L"1" : L"0";
        sig += L"|";
        sig += std::to_wstring(g_pairingDeviceAddress);
        sig += L"|";
        sig += std::to_wstring(g_bluetoothConnectingAddress);
        sig += L",";
        sig += std::to_wstring(g_bluetoothConnectingState);
        sig += L"|";
        sig += std::to_wstring(g_bluetoothRemovingAddress);
        sig += L"|";
        sig += bluetooth::Available() ? L"1" : L"0";
        sig += bluetooth::IsRadioOn() ? L"1" : L"0";
        sig += L"|";
        for (const auto& d : g_bluetoothDevices) {
            sig += d.name;
            sig += L",";
            sig += std::to_wstring(d.address.ullLong);
            sig += d.connected ? L"c" : L"-";
            sig += d.hasAudio ? L"a" : L"-";
            sig += d.hasMic ? L"m" : L"-";
            sig += d.paired ? L"p" : L"-";
            sig += std::to_wstring(d.batteryPercent);
            sig += L";";
        }
        if (g_btPanelSig == sig && g_bluetoothPanel.Children().Size() > 0) {
            return;
        }
        g_btPanelSig = sig;
    }

    const bool hadExisting = g_bluetoothPanel.Children().Size() > 0;
    const double prevShellH = hadExisting ? CaptureFlyoutShellHeight(g_bluetoothPanel.as<FrameworkElement>()) : 0.0;

    g_populatingPanel = true;
    struct Guard {
        double prevH;
        ~Guard() {
            g_populatingPanel = false;
            try { StripControlCenterSubHeaderIfHosted(g_bluetoothPanel); } catch (...) {}
            try { ApplyControlStylesToPopupRoot(g_bluetoothPanel.as<FrameworkElement>()); } catch (...) {}
            if (prevH > 24.0) {
                try {
                    AnimateFlyoutShellResize(g_bluetoothPanel.as<FrameworkElement>(), nullptr, nullptr, nullptr, 30, prevH);
                } catch (...) {}
            }
        }
    } guard{prevShellH};

    auto children = g_bluetoothPanel.Children();
    children.Clear();

    bool available = bluetooth::Available();
    bool radioOn = available && bluetooth::IsRadioOn();

    wuxc::Grid headerGrid;
    headerGrid.Name(L"BluetoothHeaderGrid");
    headerGrid.Margin(Thickness{4, 2, 0, 6});
    headerGrid.HorizontalAlignment(HorizontalAlignment::Stretch);

    wuxc::ColumnDefinition leftColumn;
    leftColumn.Width(GridLength{1, GridUnitType::Star});
    headerGrid.ColumnDefinitions().Append(leftColumn);

    wuxc::ColumnDefinition rightColumn;
    rightColumn.Width(GridLength{0, GridUnitType::Auto});
    headerGrid.ColumnDefinitions().Append(rightColumn);

    wuxc::StackPanel leftStack;
    leftStack.Name(L"BluetoothHeaderLeftStack");
    leftStack.Orientation(wuxc::Orientation::Horizontal);
    leftStack.Spacing(8);
    leftStack.VerticalAlignment(VerticalAlignment::Center);

    auto titleBlock = MakeText(L"FlyoutTitle", L"Bluetooth", 15, true);
    leftStack.Children().Append(titleBlock);

    wuxc::ProgressRing btProgress;
    btProgress.Name(L"BluetoothProgressRing");
    btProgress.IsActive(true);
    btProgress.Width(14);
    btProgress.Height(14);
    btProgress.VerticalAlignment(VerticalAlignment::Center);
    btProgress.Foreground(MakeBrush(0xFF, GetSystemAccentColor().R, GetSystemAccentColor().G, GetSystemAccentColor().B));
    btProgress.Opacity(g_bluetoothScanning ? 1.0 : 0.3);
    leftStack.Children().Append(btProgress);

    wuxc::Grid::SetColumn(leftStack, 0);
    headerGrid.Children().Append(leftStack);

    wuxc::StackPanel rightStack;
    rightStack.Name(L"BluetoothHeaderRightStack");
    rightStack.Orientation(wuxc::Orientation::Horizontal);
    rightStack.Spacing(4);
    rightStack.VerticalAlignment(VerticalAlignment::Center);

    auto refreshButton = MakeGhostButton(L"BluetoothRefreshButton", EffectiveRowCorner());
    refreshButton.Padding(Thickness{6, 6, 6, 6});
    if (IsWinUI3StyleMode()) {
        refreshButton.Background(MakeBrush(0x0F, 0xFF, 0xFF, 0xFF));
        refreshButton.BorderBrush(MakeBrush(0x1C, 0xFF, 0xFF, 0xFF));
        refreshButton.BorderThickness(Thickness{1, 1, 1, 1});
    }
    refreshButton.Content(iconpacks::IsWinUI()
        ? iconpacks::Glyph(L"\uE72C", 16)
        : BuildVectorIcon(nullptr, L"M12 20c-2.21665 0 -4.10415 -0.77915 -5.6625 -2.3375C4.779165 16.10415 4 14.21665 4 12c0 -2.21665 0.779165 -4.10415 2.3375 -5.6625C7.89585 4.779165 9.78335 4 12 4c1.41665 0 2.65835 0.2875 3.725 0.8625 1.06665 0.575 1.99165 1.3625 2.775 2.3625V4h1.5v6.35H13.65v-1.5h4.2c-0.63335 -1 -1.44165 -1.80835 -2.425 -2.425C14.44165 5.80835 13.3 5.5 12 5.5c-1.81665 0 -3.35415 0.62915 -4.6125 1.8875C6.12915 8.64585 5.5 10.18335 5.5 12c0 1.81665 0.62915 3.35415 1.8875 4.6125C8.64585 17.87085 10.18335 18.5 12 18.5c1.38335 0 2.65 -0.39585 3.8 -1.1875s1.95 -1.8375 2.4 -3.1375h1.55c-0.48335 1.75 -1.44165 3.15835 -2.875 4.225C15.44165 19.46665 13.81665 20 12 20Z", L"", 24, 20, 1.7));
    refreshButton.Click([](auto&&, auto&&) {
        StartBluetoothScan(true);
    });
    rightStack.Children().Append(refreshButton);

    wuxc::ToggleSwitch toggle;
    toggle.Name(L"BluetoothHeaderToggle");
    g_namedElements.insert_or_assign(L"BluetoothHeaderToggle", toggle);
    StyleWinUI3ToggleSwitch(toggle);
    toggle.OnContent(winrt::box_value(L""));
    toggle.OffContent(winrt::box_value(L""));
    toggle.MinWidth(50);
    toggle.Width(50);
    toggle.HorizontalAlignment(HorizontalAlignment::Right);
    toggle.HorizontalContentAlignment(HorizontalAlignment::Right);
    toggle.VerticalAlignment(VerticalAlignment::Center);
    toggle.Margin(Thickness{0, 0, 4, 0});
    toggle.IsOn(radioOn);
    toggle.IsEnabled(true);
    toggle.Toggled([](auto&& sender, auto&&) {
        if (g_populatingPanel) return;
        bool on = sender.template as<wuxc::ToggleSwitch>().IsOn();
        RunInBackground([on] {
            if (WaitForSingleObject(g_stopEvent, 0) == WAIT_OBJECT_0) return;
            bluetooth::SetRadio(on);
            bool liveOn = bluetooth::QueryRadioOnLive();
            for (int i = 0; i < 22 && liveOn != on; ++i) {
                if (WaitForSingleObject(g_stopEvent, 80) == WAIT_OBJECT_0) return;
                liveOn = bluetooth::QueryRadioOnLive();
            }
            auto devices = liveOn ? bluetooth::Enumerate(false)
                                  : std::vector<bluetooth::Device>{};
            g_btDevicesVersion.fetch_add(1);
            RunOnUiThread([devices = std::move(devices), liveOn]() mutable {
                if (!liveOn) {
                    g_btRecentUnpaired.clear();
                }
                g_bluetoothDevices = std::move(devices);
                g_btLastEnumTick.store(GetTickCount64());
                RefreshBluetoothButtonIcon();
                PopulateBluetoothPanel();
            });
        });
    });
    rightStack.Children().Append(toggle);

    wuxc::Grid::SetColumn(rightStack, 1);
    headerGrid.Children().Append(rightStack);

    children.Append(headerGrid);

    if (!available) {
        children.Append(MakeStatusText(L"No Bluetooth radio was found on this PC."));
        return;
    }
    if (!radioOn) {
        children.Append(MakeStatusText(L"Bluetooth is off."));
        return;
    }

    if (g_bluetoothDevices.empty()) {
        children.Append(MakeStatusText(L"No paired devices."));
    }

    for (const auto& device : g_bluetoothDevices) {
        auto icon = iconpacks::BluetoothIcon(true);
        if (icon && !device.connected) {
            icon.Opacity(0.55);
        }

        const bool isPairing = (device.address.ullLong == g_pairingDeviceAddress.load());
        const bool isToggling = (device.address.ullLong == g_bluetoothConnectingAddress.load());
        const bool isRemoving = (device.address.ullLong == g_bluetoothRemovingAddress.load());
        std::wstring subtitle;
        if (isRemoving) {
            subtitle = L"Removing...";
        } else if (isPairing) {
            subtitle = L"Pairing...";
        } else if (isToggling && g_bluetoothConnectingState == 1) {
            subtitle = L"Connecting...";
        } else if (isToggling && g_bluetoothConnectingState == 2) {
            subtitle = L"Disconnecting...";
        } else if (device.connected) {
            if (device.hasMic && device.hasAudio) {
                subtitle = L"Connected mic, audio";
            } else if (device.hasMic) {
                subtitle = L"Connected mic";
            } else if (device.hasAudio) {
                subtitle = L"Connected audio";
            } else {
                subtitle = L"Connected";
            }
        } else if (device.paired) {
            subtitle = L"Paired";
        } else {
            subtitle = L"Available";
        }

        const bool isBusy = (isToggling || isPairing || isRemoving);
        FrameworkElement actionChip{nullptr};
        if (isBusy) {
            wuxc::ProgressRing rowRing;
            rowRing.IsActive(true);
            rowRing.Width(16);
            rowRing.Height(16);
            rowRing.VerticalAlignment(VerticalAlignment::Center);
            rowRing.Foreground(MakeBrush(0xFF, GetSystemAccentColor().R, GetSystemAccentColor().G,
                                         GetSystemAccentColor().B));
            actionChip = rowRing;
        } else {
            bluetooth::Device captured = device;

            // Same explicit Connect / Disconnect actions as the Wi-Fi cards, so
            // a device is always connected or dropped from a visible button.
            auto pairDevice = [captured] {
                g_pairingDeviceAddress = captured.address.ullLong;
                RepopulateLater(PopulateBluetoothPanel);

                RunInBackground([captured] {
                    if (WaitForSingleObject(g_stopEvent, 0) == WAIT_OBJECT_0) return;
                    Wh_Log(L"Clicking unpaired device: %s", captured.name.c_str());
                    bool paired = bluetooth::PairDevice(captured.address);
                    Wh_Log(L"PairDevice returned: %d", paired ? 1 : 0);
                    if (paired) {
                        WaitForSingleObject(g_stopEvent, 250);
                    }
                    auto devices = bluetooth::Enumerate(false);
                    g_btDevicesVersion.fetch_add(1);
                    RunOnUiThread([paired, captured, devices = std::move(devices)]() mutable {
                        g_pairingDeviceAddress = 0;
                        if (paired) {
                            uint64_t mac = captured.address.ullLong & 0xFFFFFFFFFFFFULL;
                            g_btRecentUnpaired.erase(
                                std::remove_if(g_btRecentUnpaired.begin(), g_btRecentUnpaired.end(),
                                               [mac](const bluetooth::Device& d) {
                                                   return (d.address.ullLong & 0xFFFFFFFFFFFFULL) == mac;
                                               }),
                                g_btRecentUnpaired.end());
                        }
                        MergeRecentUnpairedBluetooth(devices);
                        g_bluetoothDevices = std::move(devices);
                        g_btLastEnumTick.store(GetTickCount64());
                        RefreshBluetoothButtonIcon();
                        PopulateBluetoothPanel();
                    });
                });
            };

            auto toggleConnection = [captured] {
                bool connect = !captured.connected;
                g_bluetoothConnectingState = connect ? 1 : 2;
                g_bluetoothConnectingAddress = captured.address.ullLong;
                RepopulateLater(PopulateBluetoothPanel);

                RunInBackground([captured, connect] {
                    if (WaitForSingleObject(g_stopEvent, 0) == WAIT_OBJECT_0) return;
                    bool actionOk = bluetooth::SetConnected(captured.address, connect);
                    // Poll live connection state at short intervals instead of a
                    // blind 2.5 s sleep so disconnect/connect updates immediately
                    // once the ACL link settles (and exits right away if the
                    // device was externally unpaired).
                    if (actionOk || !connect) {
                        const ULONGLONG maxWaitMs = connect ? 2400 : 1000;
                        const ULONGLONG startTick = GetTickCount64();
                        while (GetTickCount64() - startTick < maxWaitMs) {
                            if (bluetooth::IsDeviceConnectedFast(captured.address) == connect) {
                                break;
                            }
                            if (WaitForSingleObject(g_stopEvent, 90) == WAIT_OBJECT_0) {
                                return;
                            }
                        }
                    }
                    auto devices = bluetooth::Enumerate(false);
                    g_btDevicesVersion.fetch_add(1);
                    RunOnUiThread([devices = std::move(devices)]() mutable {
                        MergeRecentUnpairedBluetooth(devices);
                        g_bluetoothDevices = std::move(devices);
                        g_btLastEnumTick.store(GetTickCount64());
                        g_bluetoothConnectingAddress = 0;
                        g_bluetoothConnectingState = 0;
                        RefreshBluetoothButtonIcon();
                        PopulateBluetoothPanel();
                    });
                });
            };

            auto removeDevice = [captured] {
                g_bluetoothRemovingAddress = captured.address.ullLong;
                RepopulateLater(PopulateBluetoothPanel);

                RunInBackground([captured] {
                    if (WaitForSingleObject(g_stopEvent, 0) == WAIT_OBJECT_0) return;
                    bluetooth::UnpairDevice(captured.address);
                    const uint64_t targetMac = captured.address.ullLong & 0xFFFFFFFFFFFFULL;
                    std::vector<bluetooth::Device> devices;
                    const ULONGLONG startTick = GetTickCount64();
                    while (true) {
                        devices = bluetooth::Enumerate(false);
                        bool stillPresent = false;
                        for (const auto& d : devices) {
                            if ((d.address.ullLong & 0xFFFFFFFFFFFFULL) == targetMac &&
                                (d.paired || d.connected)) {
                                stillPresent = true;
                                break;
                            }
                        }
                        if (!stillPresent || GetTickCount64() - startTick >= 1200) {
                            break;
                        }
                        if (WaitForSingleObject(g_stopEvent, 100) == WAIT_OBJECT_0) {
                            return;
                        }
                    }
                    g_btDevicesVersion.fetch_add(1);
                    RunOnUiThread([targetMac, devices = std::move(devices)]() mutable {
                        g_btRecentUnpaired.erase(
                            std::remove_if(g_btRecentUnpaired.begin(), g_btRecentUnpaired.end(),
                                           [targetMac](const bluetooth::Device& d) {
                                               return (d.address.ullLong & 0xFFFFFFFFFFFFULL) == targetMac;
                                           }),
                            g_btRecentUnpaired.end());
                        MergeRecentUnpairedBluetooth(devices);
                        g_bluetoothDevices = std::move(devices);
                        g_btLastEnumTick.store(GetTickCount64());
                        g_bluetoothRemovingAddress = 0;
                        RefreshBluetoothButtonIcon();
                        PopulateBluetoothPanel();
                    });
                });
            };

            if (device.connected || device.paired) {
                wuxc::StackPanel btnStack;
                btnStack.Orientation(wuxc::Orientation::Horizontal);
                btnStack.Spacing(6);
                btnStack.VerticalAlignment(VerticalAlignment::Center);

                auto primaryBtn = MakeActionChip(
                    nullptr,
                    device.connected ? L"Disconnect" : L"Connect",
                    [toggleConnection] { toggleConnection(); });
                auto removeBtn = MakeActionChip(
                    nullptr,
                    L"Remove",
                    [removeDevice] { removeDevice(); });
                btnStack.Children().Append(primaryBtn);
                btnStack.Children().Append(removeBtn);
                actionChip = btnStack;
            } else {
                actionChip = MakeActionChip(nullptr, L"Pair",
                                            [pairDevice] { pairDevice(); });
            }
        }

        FrameworkElement topTrailing{nullptr};
        FrameworkElement bottomActions{nullptr};
        const bool useTwoRowCard = device.connected && (device.batteryPercent >= 0);
        if (useTwoRowCard) {
            wuxc::Border battBadge;
            battBadge.UseLayoutRounding(true);
            battBadge.CornerRadius(CornerRadius{4, 4, 4, 4});
            battBadge.Padding(Thickness{6, 2, 6, 2});
            battBadge.Background(MakeBrush(0x14, 0xFF, 0xFF, 0xFF));
            battBadge.BorderBrush(MakeBrush(0x1F, 0xFF, 0xFF, 0xFF));
            battBadge.BorderThickness(Thickness{1, 1, 1, 1});
            battBadge.VerticalAlignment(VerticalAlignment::Center);

            wuxc::StackPanel battPill;
            battPill.Orientation(wuxc::Orientation::Horizontal);
            battPill.Spacing(5);
            battPill.VerticalAlignment(VerticalAlignment::Center);

            // BandBattery0..BandBattery6 (U+ECB9..U+ECBF), rendered natively at 16px
            // Segoe Fluent Icons grid size without Viewbox scaling to keep stems sharp.
            int pct = std::clamp(device.batteryPercent, 0, 100);
            int levelIdx = 0;
            if (pct >= 92) levelIdx = 6;
            else if (pct >= 76) levelIdx = 5;
            else if (pct >= 59) levelIdx = 4;
            else if (pct >= 42) levelIdx = 3;
            else if (pct >= 25) levelIdx = 2;
            else if (pct >= 8) levelIdx = 1;
            wchar_t battGlyph[2] = { static_cast<wchar_t>(0xECB9 + levelIdx), L'\0' };

            wuxc::FontIcon battIcon;
            battIcon.FontFamily(wuxm::FontFamily(L"Segoe Fluent Icons, Segoe MDL2 Assets"));
            battIcon.Glyph(battGlyph);
            battIcon.FontSize(16);
            battIcon.UseLayoutRounding(true);
            battIcon.Margin(Thickness{0, 1, 0, 0});
            battIcon.HorizontalAlignment(HorizontalAlignment::Center);
            battIcon.VerticalAlignment(VerticalAlignment::Center);
            if (pct <= 20) {
                battIcon.Foreground(MakeBrush(0xFF, 0xFF, 0x6B, 0x6B));
            } else {
                battIcon.Foreground(FontColorBrush(0xE8));
            }
            battPill.Children().Append(battIcon);

            auto battTxt = MakeText(nullptr, std::to_wstring(pct) + L"%", 12, true, 0.92);
            battTxt.VerticalAlignment(VerticalAlignment::Center);
            if (pct <= 20) {
                battTxt.Foreground(MakeBrush(0xFF, 0xFF, 0x6B, 0x6B));
            }
            battPill.Children().Append(battTxt);

            battBadge.Child(battPill);
            topTrailing = battBadge;
        }
        if (useTwoRowCard) {
            if (isBusy) {
                wuxc::StackPanel topStack;
                topStack.Orientation(wuxc::Orientation::Horizontal);
                topStack.Spacing(8);
                topStack.VerticalAlignment(VerticalAlignment::Center);
                topStack.Children().Append(topTrailing);
                if (actionChip) topStack.Children().Append(actionChip);
                topTrailing = topStack;
            } else {
                bottomActions = actionChip;
            }
        } else {
            topTrailing = actionChip;
        }

        // Use two-row card layout only for connected devices showing battery health;
        // otherwise keep action buttons on the same row as the device info.
        children.Append(MakeDeviceCardRow(icon, device.name, subtitle, topTrailing,
                                          bottomActions, L"BluetoothDeviceRow", device.connected));
    }

    children.Append(MakeDivider());
    children.Append(MakeSettingsLink(L"Bluetooth settings", L"ms-settings:bluetooth"));
}

wuxm::Imaging::BitmapImage Bgra32ToBitmapImage(const std::vector<uint8_t>& pixels, int width,
                                               int height) {
    if (pixels.empty() || width <= 0 || height <= 0) {
        return nullptr;
    }

    BITMAPV5HEADER infoHeader{};
    infoHeader.bV5Size = sizeof(BITMAPV5HEADER);
    infoHeader.bV5Width = width;
    infoHeader.bV5Height = -height;
    infoHeader.bV5Planes = 1;
    infoHeader.bV5BitCount = 32;
    infoHeader.bV5Compression = BI_BITFIELDS;
    infoHeader.bV5RedMask = 0x00FF0000;
    infoHeader.bV5GreenMask = 0x0000FF00;
    infoHeader.bV5BlueMask = 0x000000FF;
    infoHeader.bV5AlphaMask = 0xFF000000;
    infoHeader.bV5CSType = LCS_sRGB;
    infoHeader.bV5SizeImage = static_cast<DWORD>(pixels.size());

    BITMAPFILEHEADER fileHeader{};
    fileHeader.bfType = 0x4D42;
    fileHeader.bfSize = static_cast<DWORD>(sizeof(fileHeader) + sizeof(infoHeader) + pixels.size());
    fileHeader.bfOffBits = sizeof(fileHeader) + sizeof(infoHeader);

    try {
        winrt::Windows::Storage::Streams::InMemoryRandomAccessStream stream;
        winrt::Windows::Storage::Streams::DataWriter writer(stream);
        writer.WriteBytes(winrt::array_view<const uint8_t>(
            reinterpret_cast<const uint8_t*>(&fileHeader), sizeof(fileHeader)));
        writer.WriteBytes(winrt::array_view<const uint8_t>(
            reinterpret_cast<const uint8_t*>(&infoHeader), sizeof(infoHeader)));
        writer.WriteBytes(pixels);
        writer.StoreAsync().get();
        writer.DetachStream();
        stream.Seek(0);

        wuxm::Imaging::BitmapImage bitmap;
        bitmap.SetSourceAsync(stream);
        return bitmap;
    } catch (...) {
        return nullptr;
    }
}

wuxm::Imaging::BitmapImage CaptureScreenRect(const RECT& bounds) {
    int width = bounds.right - bounds.left;
    int height = bounds.bottom - bounds.top;
    if (width <= 0 || height <= 0 || width > 256 || height > 256) {
        return nullptr;
    }

    HDC screenDc = GetDC(nullptr);
    if (!screenDc) {
        return nullptr;
    }
    HDC memoryDc = CreateCompatibleDC(screenDc);
    if (!memoryDc) {
        ReleaseDC(nullptr, screenDc);
        return nullptr;
    }

    BITMAPINFO bmi{};
    bmi.bmiHeader.biSize = sizeof(BITMAPINFOHEADER);
    bmi.bmiHeader.biWidth = width;
    bmi.bmiHeader.biHeight = -height;
    bmi.bmiHeader.biPlanes = 1;
    bmi.bmiHeader.biBitCount = 32;
    bmi.bmiHeader.biCompression = BI_RGB;

    void* bits = nullptr;
    HBITMAP dib = CreateDIBSection(memoryDc, &bmi, DIB_RGB_COLORS, &bits, nullptr, 0);
    if (!dib) {
        DeleteDC(memoryDc);
        ReleaseDC(nullptr, screenDc);
        return nullptr;
    }

    HGDIOBJ old = SelectObject(memoryDc, dib);
    BOOL copied = BitBlt(memoryDc, 0, 0, width, height, screenDc, bounds.left, bounds.top,
                         SRCCOPY);

    std::vector<uint8_t> pixels;
    if (copied) {
        size_t dataSize = static_cast<size_t>(width) * height * 4;
        pixels.resize(dataSize);
        memcpy(pixels.data(), bits, dataSize);
    }

    SelectObject(memoryDc, old);
    DeleteObject(dib);
    DeleteDC(memoryDc);
    ReleaseDC(nullptr, screenDc);

    if (pixels.empty()) {
        return nullptr;
    }

    std::map<uint32_t, int> histogram;
    for (size_t i = 0; i + 3 < pixels.size(); i += 4) {
        uint32_t key = (static_cast<uint32_t>(pixels[i]) << 16) |
                       (static_cast<uint32_t>(pixels[i + 1]) << 8) |
                       static_cast<uint32_t>(pixels[i + 2]);
        histogram[key]++;
    }
    uint32_t background = 0;
    int backgroundCount = 0;
    for (const auto& entry : histogram) {
        if (entry.second > backgroundCount) {
            background = entry.first;
            backgroundCount = entry.second;
        }
    }

    int totalPixels = width * height;
    if (backgroundCount > totalPixels * 9 / 10) {
        return nullptr;
    }

    uint8_t backgroundB = static_cast<uint8_t>((background >> 16) & 0xFF);
    uint8_t backgroundG = static_cast<uint8_t>((background >> 8) & 0xFF);
    uint8_t backgroundR = static_cast<uint8_t>(background & 0xFF);
    for (size_t i = 0; i + 3 < pixels.size(); i += 4) {
        int deltaB = std::abs(static_cast<int>(pixels[i]) - backgroundB);
        int deltaG = std::abs(static_cast<int>(pixels[i + 1]) - backgroundG);
        int deltaR = std::abs(static_cast<int>(pixels[i + 2]) - backgroundR);
        bool isBackground = deltaB + deltaG + deltaR < 24;
        pixels[i + 3] = isBackground ? 0 : 255;
        if (isBackground) {
            pixels[i] = pixels[i + 1] = pixels[i + 2] = 0;
        }
    }

    return Bgra32ToBitmapImage(pixels, width, height);
}

struct PowerPlanEntry {
    GUID guid{};
    std::wstring name;
};

static constexpr DWORD kAccessScheme = 16;

static std::vector<PowerPlanEntry> EnumeratePowerPlans() {
    std::vector<PowerPlanEntry> out;
    HMODULE h = LoadLibraryExW(L"powrprof.dll", nullptr,
                               LOAD_LIBRARY_SEARCH_SYSTEM32);
    if (!h) return out;
    using PE_t = DWORD(WINAPI*)(HKEY, const GUID*, const GUID*, DWORD,
                                DWORD, UCHAR*, DWORD*);
    using PR_t = DWORD(WINAPI*)(HKEY, const GUID*, const GUID*,
                                const GUID*, UCHAR*, DWORD*);
    auto pEnum = (PE_t)GetProcAddress(h, "PowerEnumerate");
    auto pRead = (PR_t)GetProcAddress(h, "PowerReadFriendlyName");
    if (!pEnum || !pRead) { FreeLibrary(h); return out; }
    for (DWORD i = 0; i < 64; i++) {
        GUID g{};
        DWORD sz = sizeof(g);
        if (pEnum(nullptr, nullptr, nullptr, kAccessScheme, i,
                  (UCHAR*)&g, &sz) != ERROR_SUCCESS) {
            break;
        }
        wchar_t name[160]{};
        DWORD nsz = sizeof(name);
        if (pRead(nullptr, &g, nullptr, nullptr,
                  (UCHAR*)name, &nsz) != ERROR_SUCCESS) {
            continue;
        }
        PowerPlanEntry e;
        e.guid = g;
        e.name = name;
        if (!e.name.empty()) out.push_back(std::move(e));
    }
    FreeLibrary(h);
    return out;
}

static GUID GetActivePowerPlan() {
    GUID active{};
    HMODULE h = LoadLibraryExW(L"powrprof.dll", nullptr,
                               LOAD_LIBRARY_SEARCH_SYSTEM32);
    if (!h) return active;
    using PG_t = DWORD(WINAPI*)(HKEY, GUID**);
    auto pGet = (PG_t)GetProcAddress(h, "PowerGetActiveScheme");
    if (pGet) {
        GUID* g = nullptr;
        if (pGet(nullptr, &g) == ERROR_SUCCESS && g) {
            active = *g;
            LocalFree(g);
        }
    }
    FreeLibrary(h);
    return active;
}

static bool SetActivePowerPlan(const GUID& g) {
    HMODULE h = LoadLibraryExW(L"powrprof.dll", nullptr,
                               LOAD_LIBRARY_SEARCH_SYSTEM32);
    if (!h) return false;
    using PS_t = DWORD(WINAPI*)(HKEY, const GUID*);
    auto pSet = (PS_t)GetProcAddress(h, "PowerSetActiveScheme");
    bool ok = false;
    if (pSet) ok = pSet(nullptr, &g) == ERROR_SUCCESS;
    FreeLibrary(h);
    return ok;
}

static bool SameGuid(const GUID& a, const GUID& b) {
    return memcmp(&a, &b, sizeof(GUID)) == 0;
}

static std::wstring ActivePowerPlanName() {
    const GUID active = GetActivePowerPlan();
    for (const auto& p : EnumeratePowerPlans()) {
        if (SameGuid(p.guid, active)) return p.name;
    }
    return L"";
}

struct BatteryInfo {
    int percentage = 0;
    int health = 100;
    bool charging = false;
    bool powerSaving = false;
    bool present = true;
};

int QueryBatteryHealth() {
    static int cachedHealth = -1;
    if (cachedHealth >= 0) return cachedHealth;

    int health = 100;
    ULONGLONG designCap = 0;
    ULONGLONG fullCap = 0;

    static const CLSID kCLSID_WbemLocator = {
        0x4590f811, 0x1d3a, 0x11d0,
        {0x89, 0x1f, 0x00, 0xaa, 0x00, 0x4b, 0x2e, 0x24}};
    static const IID kIID_IWbemLocator = {
        0xdc12a687, 0x737f, 0x11cf,
        {0x88, 0x4d, 0x00, 0xaa, 0x00, 0x4b, 0x2e, 0x24}};

    auto extract = [](const VARIANT& v) -> ULONGLONG {
        switch (v.vt) {
            case VT_UI1: return v.bVal;
            case VT_UI2: return v.uiVal;
            case VT_UI4: return v.ulVal;
            case VT_UI8: return v.ullVal;
            case VT_I1:  return (ULONGLONG)v.cVal;
            case VT_I2:  return (ULONGLONG)v.iVal;
            case VT_I4:  return (ULONGLONG)v.lVal;
            case VT_I8:  return (ULONGLONG)v.llVal;
            default:     return 0;
        }
    };

    auto queryOne = [&](IWbemServices* services, PCWSTR cls, PCWSTR prop) -> ULONGLONG {
        std::wstring q = L"SELECT ";
        q += prop;
        q += L" FROM ";
        q += cls;
        BSTR lang = SysAllocString(L"WQL");
        BSTR query = SysAllocString(q.c_str());
        winrt::com_ptr<IEnumWbemClassObject> enumerator;
        HRESULT r = services->ExecQuery(
            lang, query,
            WBEM_FLAG_FORWARD_ONLY | WBEM_FLAG_RETURN_IMMEDIATELY,
            nullptr, enumerator.put());
        SysFreeString(query);
        SysFreeString(lang);
        if (FAILED(r) || !enumerator) return 0;

        IWbemClassObject* obj = nullptr;
        ULONG returned = 0;
        if (SUCCEEDED(enumerator->Next(2000, 1, &obj, &returned)) && returned && obj) {
            VARIANT v;
            VariantInit(&v);
            ULONGLONG result = 0;
            if (SUCCEEDED(obj->Get(prop, 0, &v, nullptr, nullptr))) {
                result = extract(v);
            }
            VariantClear(&v);
            obj->Release();
            return result;
        }
        return 0;
    };

    try {
        winrt::com_ptr<IWbemLocator> locator;
        if (SUCCEEDED(CoCreateInstance(kCLSID_WbemLocator, nullptr,
                                       CLSCTX_INPROC_SERVER, kIID_IWbemLocator,
                                       locator.put_void()))) {
            BSTR ns = SysAllocString(L"root\\WMI");
            winrt::com_ptr<IWbemServices> services;
            HRESULT hr = locator->ConnectServer(ns, nullptr, nullptr, nullptr, 0,
                                                nullptr, nullptr, services.put());
            SysFreeString(ns);
            if (SUCCEEDED(hr) && services) {
                CoSetProxyBlanket(services.get(), RPC_C_AUTHN_WINNT, RPC_C_AUTHZ_NONE,
                                  nullptr, RPC_C_AUTHN_LEVEL_CALL,
                                  RPC_C_IMP_LEVEL_IMPERSONATE, nullptr, EOAC_NONE);
                designCap = queryOne(services.get(), L"BatteryStaticData",
                                     L"DesignedCapacity");
                fullCap = queryOne(services.get(), L"BatteryFullChargedCapacity",
                                   L"FullChargedCapacity");
            }
        }
    } catch (...) {}

    if (designCap == 0 || fullCap == 0) {
        try {
            winrt::com_ptr<IWbemLocator> locator;
            if (SUCCEEDED(CoCreateInstance(kCLSID_WbemLocator, nullptr,
                                           CLSCTX_INPROC_SERVER, kIID_IWbemLocator,
                                           locator.put_void()))) {
                BSTR ns = SysAllocString(L"root\\cimv2");
                winrt::com_ptr<IWbemServices> services;
                HRESULT hr = locator->ConnectServer(ns, nullptr, nullptr, nullptr, 0,
                                                    nullptr, nullptr, services.put());
                SysFreeString(ns);
                if (SUCCEEDED(hr) && services) {
                    CoSetProxyBlanket(services.get(), RPC_C_AUTHN_WINNT,
                                      RPC_C_AUTHZ_NONE, nullptr, RPC_C_AUTHN_LEVEL_CALL,
                                      RPC_C_IMP_LEVEL_IMPERSONATE, nullptr, EOAC_NONE);
                    BSTR query = SysAllocString(
                        L"SELECT FullChargeCapacity, DesignCapacity FROM Win32_Battery");
                    BSTR lang = SysAllocString(L"WQL");
                    winrt::com_ptr<IEnumWbemClassObject> enumerator;
                    if (SUCCEEDED(services->ExecQuery(
                            lang, query,
                            WBEM_FLAG_FORWARD_ONLY | WBEM_FLAG_RETURN_IMMEDIATELY,
                            nullptr, enumerator.put()))) {
                        IWbemClassObject* obj = nullptr;
                        ULONG returned = 0;
                        if (SUCCEEDED(enumerator->Next(2000, 1, &obj, &returned)) &&
                            returned && obj) {
                            VARIANT full, design;
                            VariantInit(&full);
                            VariantInit(&design);
                            if (SUCCEEDED(obj->Get(L"FullChargeCapacity", 0, &full,
                                                   nullptr, nullptr)) &&
                                SUCCEEDED(obj->Get(L"DesignCapacity", 0, &design,
                                                   nullptr, nullptr))) {
                                fullCap   = extract(full);
                                designCap = extract(design);
                            }
                            VariantClear(&full);
                            VariantClear(&design);
                            obj->Release();
                        }
                    }
                    SysFreeString(query);
                    SysFreeString(lang);
                }
            }
        } catch (...) {}
    }

    if (designCap > 0 && fullCap > 0) {
        health = static_cast<int>((fullCap * 100ULL) / designCap);
        if (health > 100) health = 100;
        if (health < 0) health = 0;
    }
    cachedHealth = health;
    return health;
}

bool IsLaptop() {
    static int s_isLaptop = -1;
    if (s_isLaptop != -1) return s_isLaptop != 0;
    SYSTEM_POWER_STATUS sps;
    if (GetSystemPowerStatus(&sps)) {
        if ((sps.BatteryFlag & 128) == 0 && sps.BatteryLifePercent != 255) {
            s_isLaptop = 1;
            return true;
        }
    }
    static const CLSID kCLSID_WbemLocator = {0x4590f811, 0x1d3a, 0x11d0, {0x89, 0x1f, 0x00, 0xaa, 0x00, 0x4b, 0x2e, 0x24}};
    static const IID kIID_IWbemLocator = {0xdc12a687, 0x737f, 0x11cf, {0x88, 0x4d, 0x00, 0xaa, 0x00, 0x4b, 0x2e, 0x24}};
    winrt::com_ptr<IWbemLocator> locator;
    if (SUCCEEDED(CoCreateInstance(kCLSID_WbemLocator, nullptr, CLSCTX_INPROC_SERVER, kIID_IWbemLocator, locator.put_void()))) {
        BSTR ns = SysAllocString(L"root\\cimv2");
        winrt::com_ptr<IWbemServices> services;
        if (SUCCEEDED(locator->ConnectServer(ns, nullptr, nullptr, nullptr, 0, nullptr, nullptr, services.put()))) {
            CoSetProxyBlanket(services.get(), RPC_C_AUTHN_WINNT, RPC_C_AUTHZ_NONE, nullptr, RPC_C_AUTHN_LEVEL_CALL, RPC_C_IMP_LEVEL_IMPERSONATE, nullptr, EOAC_NONE);
            BSTR query = SysAllocString(L"SELECT ChassisTypes FROM Win32_SystemEnclosure");
            BSTR lang = SysAllocString(L"WQL");
            winrt::com_ptr<IEnumWbemClassObject> enumerator;
            if (SUCCEEDED(services->ExecQuery(lang, query, WBEM_FLAG_FORWARD_ONLY | WBEM_FLAG_RETURN_IMMEDIATELY, nullptr, enumerator.put()))) {
                IWbemClassObject* obj = nullptr;
                ULONG returned = 0;
                if (SUCCEEDED(enumerator->Next(2000, 1, &obj, &returned)) && returned) {
                    VARIANT v;
                    VariantInit(&v);
                    if (SUCCEEDED(obj->Get(L"ChassisTypes", 0, &v, nullptr, nullptr)) && (v.vt & VT_ARRAY) && v.parray) {
                        SAFEARRAY* sa = v.parray;
                        VARTYPE elem = static_cast<VARTYPE>(v.vt & VT_TYPEMASK);
                        LONG lb = 0, ub = -1;
                        SafeArrayGetLBound(sa, 1, &lb);
                        SafeArrayGetUBound(sa, 1, &ub);
                        for (LONG i = lb; i <= ub; ++i) {
                            short val = 0;
                            if (elem == VT_I2) SafeArrayGetElement(sa, &i, &val);
                            else if (elem == VT_UI2) { unsigned short uval; SafeArrayGetElement(sa, &i, &uval); val = uval; }
                            else if (elem == VT_I4) { long lval; SafeArrayGetElement(sa, &i, &lval); val = static_cast<short>(lval); }
                            if (val == 8 || val == 9 || val == 10 || val == 11 || val == 12 || val == 14 || val == 18 || val == 21 || val == 30 || val == 31 || val == 32) {
                                s_isLaptop = 1;
                                break;
                            }
                        }
                    }
                    VariantClear(&v);
                    obj->Release();
                }
            }
            SysFreeString(query);
            SysFreeString(lang);
        }
        SysFreeString(ns);
    }
    if (s_isLaptop == -1) s_isLaptop = 0;
    return s_isLaptop != 0;
}

BatteryInfo GetBatteryInfo() {
    BatteryInfo info;
    SYSTEM_POWER_STATUS powerStatus;
    if (GetSystemPowerStatus(&powerStatus)) {
        if (powerStatus.BatteryLifePercent == 255 || (powerStatus.BatteryFlag & 128)) {
            info.present = false;
            info.percentage = 100;
            info.charging = false;
        } else {
            info.percentage = powerStatus.BatteryLifePercent;
            info.charging = (powerStatus.ACLineStatus == 1);
        }
    } else {
        info.present = false;
    }

    info.powerSaving = false;
    {
        DWORD v = 0, size = sizeof(v);
        if (RegGetValueW(HKEY_LOCAL_MACHINE, L"SYSTEM\\CurrentControlSet\\Control\\Power",
                         L"EnergySaverState", RRF_RT_REG_DWORD, nullptr, &v, &size) == ERROR_SUCCESS) {
            info.powerSaving = (v == 1);
        } else if (GetSystemPowerStatus(&powerStatus)) {
            info.powerSaving = (((const BYTE*)&powerStatus)[3] != 0) || ((powerStatus.SystemStatusFlag & 1) != 0);
        }
        if (!info.powerSaving) {
            DWORD eco = 0, ecoSize = sizeof(eco);
            if (RegGetValueW(HKEY_LOCAL_MACHINE, L"SYSTEM\\CurrentControlSet\\Control\\Power",
                             L"EcoModeState", RRF_RT_REG_DWORD, nullptr, &eco, &ecoSize) == ERROR_SUCCESS && eco != 0) {
                info.powerSaving = true;
            }
        }
    }

    if (info.present) {
        info.health = QueryBatteryHealth();
    }
    return info;
}

std::mutex g_nightLightCoalesceMutex;
int g_nightLightPendingValue = -1;
bool g_nightLightWorkerRunning = false;
std::atomic<int> g_nightLightCachedState{-1};

void SetNightLightState(bool enable) {
    g_nightLightCachedState.store(enable ? 1 : 0);
    {
        std::lock_guard<std::mutex> lock(g_nightLightCoalesceMutex);
        g_nightLightPendingValue = enable ? 1 : 0;
        if (g_nightLightWorkerRunning) return;
        g_nightLightWorkerRunning = true;
    }
    RunInBackground([] {
        for (;;) {
            int v;
            {
                std::lock_guard<std::mutex> lock(g_nightLightCoalesceMutex);
                if (g_nightLightPendingValue < 0) {
                    g_nightLightWorkerRunning = false;
                    return;
                }
                v = g_nightLightPendingValue;
                g_nightLightPendingValue = -1;
            }
            try { nightlight::Set(v != 0); } catch (...) {}
        }
    });
}

bool GetNightLightState() {
    int v = g_nightLightCachedState.load();
    if (v < 0) {
        bool actual = false;
        try { actual = nightlight::Get(); } catch (...) {}
        v = actual ? 1 : 0;
        g_nightLightCachedState.store(v);
    }
    return v != 0;
}

bool SetSystemPowerSaving(bool enable) {
    // Publish WNF_PO_ENERGY_SAVER_OVERRIDE (0x41C6013DA3BC3075ULL): 1 = On, 2 = Off.
    // Same transient override used by Windows 11 Quick Settings; does not rewrite the active power plan's ESBATTTHRESHOLD.
    using RtlPublishWnfStateData_t = LONG(NTAPI*)(ULONGLONG, const void*, const void*, ULONG, const void*);
    static auto publishWnf = reinterpret_cast<RtlPublishWnfStateData_t>(
        reinterpret_cast<void*>(GetProcAddress(GetModuleHandleW(L"ntdll.dll"), "RtlPublishWnfStateData")));
    if (publishWnf) {
        DWORD v = enable ? 1 : 2;
        if (publishWnf(0x41C6013DA3BC3075ULL, nullptr, &v, sizeof(v), nullptr) >= 0) {
            return true;
        }
    }
    return false;
}

void UpdateBatteryButton() {
    if (!g_batteryButton) return;
    BatteryInfo info = GetBatteryInfo();
    static int s_lastPercentage = -1;
    static bool s_lastCharging = false;
    static bool s_lastPowerSaving = false;
    static bool s_initialized = false;
    if (s_initialized && info.percentage == s_lastPercentage &&
        info.charging == s_lastCharging && info.powerSaving == s_lastPowerSaving) {
        return;
    }
    s_lastPercentage = info.percentage;
    s_lastCharging = info.charging;
    s_lastPowerSaving = info.powerSaving;
    s_initialized = true;
    auto batteryIcon = iconpacks::BatteryIcon(info.percentage, info.charging, info.present, info.powerSaving);
    if (batteryIcon) {
        batteryIcon.VerticalAlignment(VerticalAlignment::Center);
        g_batteryButton.Content(batteryIcon);
    }
}

// ---------------------------------------------------------------------------
// Network monitor: download / upload throughput from the PDH "Network
// Interface" counter set (PDH is already linked; no iphlpapi dependency).
// ---------------------------------------------------------------------------
namespace netmon {

struct Sample {
    double downloadBytesPerSec = 0.0;
    double uploadBytesPerSec = 0.0;
    bool available = false;
};

static std::mutex s_mutex;
static PDH_HQUERY s_query = nullptr;
static PDH_HCOUNTER s_received = nullptr;
static PDH_HCOUNTER s_sent = nullptr;
    static bool s_initAttempted = false;
    static bool s_hasSample = false;
static double s_lastRx = 0.0;
static double s_lastTx = 0.0;
static double s_peakRx = 0.0;
static double s_peakTx = 0.0;
std::deque<float> g_netRxHistory;
std::deque<float> g_netTxHistory;
// Incremented every time a sample is appended to the history. Consumers use it
// to redraw only when there is actually new data.
std::atomic<unsigned long long> g_netSampleSeq{0};

static bool EnsureQuery() {
    if (s_initAttempted) return s_query != nullptr;
    s_initAttempted = true;
    if (PdhOpenQueryW(nullptr, 0, &s_query) != ERROR_SUCCESS) {
        s_query = nullptr;
        return false;
    }
    if (PdhAddEnglishCounterW(s_query,
                              L"\\Network Interface(*)\\Bytes Received/sec", 0,
                              &s_received) != ERROR_SUCCESS) {
        s_received = nullptr;
    }
    if (PdhAddEnglishCounterW(s_query, L"\\Network Interface(*)\\Bytes Sent/sec",
                              0, &s_sent) != ERROR_SUCCESS) {
        s_sent = nullptr;
    }
    if (!s_received || !s_sent) {
        PdhCloseQuery(s_query);
        s_query = nullptr;
        return false;
    }
    PdhCollectQueryData(s_query);  // prime: rate counters need two samples
    return true;
}

static bool IsIgnoredAdapter(const wchar_t* name) {
    if (!name || !*name) return true;
    static const wchar_t* kIgnored[] = {L"Loopback", L"loopback", L"isatap",
                                        L"Teredo", L"teredo", L"Pseudo"};
    for (auto* needle : kIgnored) {
        if (wcsstr(name, needle)) return true;
    }
    return false;
}

static double SumCounter(PDH_HCOUNTER counter) {
    if (!counter) return 0.0;
    DWORD size = 0;
    DWORD count = 0;
    if (PdhGetFormattedCounterArrayW(counter, PDH_FMT_DOUBLE, &size, &count,
                                     nullptr) != PDH_MORE_DATA ||
        size == 0 || count == 0) {
        return 0.0;
    }
    std::vector<BYTE> buffer(size);
    auto* items =
        reinterpret_cast<PDH_FMT_COUNTERVALUE_ITEM_W*>(buffer.data());
    if (PdhGetFormattedCounterArrayW(counter, PDH_FMT_DOUBLE, &size, &count,
                                     items) != ERROR_SUCCESS) {
        return 0.0;
    }
    double total = 0.0;
    for (DWORD i = 0; i < count; ++i) {
        if (IsIgnoredAdapter(items[i].szName)) continue;
        const DWORD status = items[i].FmtValue.CStatus;
        if (status != ERROR_SUCCESS && status != PDH_CSTATUS_VALID_DATA) {
            continue;
        }
        const double value = items[i].FmtValue.doubleValue;
        if (std::isfinite(value) && value > 0.0) total += value;
    }
    return total;
}

// Reads the PDH counters. The caller must hold s_mutex. Returns false when no
// reading could be produced.
static bool CollectLocked(Sample& result) {
    if (!EnsureQuery()) return false;
    if (PdhCollectQueryData(s_query) != ERROR_SUCCESS) return false;
    const double rx = SumCounter(s_received);
    const double tx = SumCounter(s_sent);
    // The counters are already per-second rates, so no delta maths here.
    result.downloadBytesPerSec = rx;
    result.uploadBytesPerSec = tx;
    result.available = s_hasSample;
    s_hasSample = true;
    s_lastRx = rx;
    s_lastTx = tx;
    if (rx > s_peakRx) s_peakRx = rx;
    if (tx > s_peakTx) s_peakTx = tx;
    return true;
}

// Reads the current values without touching the graph history. Used by the
// button so it cannot inject extra samples into the graph.
Sample SampleNow() {
    std::lock_guard<std::mutex> lock(s_mutex);
    Sample result;
    CollectLocked(result);
    return result;
}

// Appends the most recently read values as one graph sample without touching
// the performance counters again: collecting twice in quick succession makes
// the per-second rate counters noisy. Called by exactly one timer, so the
// graph advances at a constant, predictable rate.
void RecordLast() {
    std::lock_guard<std::mutex> lock(s_mutex);
    if (!s_hasSample) return;
    g_netRxHistory.push_back(static_cast<float>(s_lastRx));
    g_netTxHistory.push_back(static_cast<float>(s_lastTx));
    if (g_netRxHistory.size() > 60) g_netRxHistory.pop_front();
    if (g_netTxHistory.size() > 60) g_netTxHistory.pop_front();
    ++g_netSampleSeq;
}

std::wstring FormatSpeed(double bytesPerSec) {
    if (!std::isfinite(bytesPerSec) || bytesPerSec < 0.0) bytesPerSec = 0.0;
    double mb = bytesPerSec / (1024.0 * 1024.0);
    wchar_t buffer[32]{};
    swprintf_s(buffer, L"%.1f MB/s", mb);
    return buffer;
}

}  // namespace netmon

[[clang::no_destroy]] wuxc::Flyout g_networkFlyout{nullptr};
[[clang::no_destroy]] wuxc::StackPanel g_networkPanel{nullptr};

[[clang::no_destroy]] wuxc::Canvas g_netGraphCanvas{nullptr};
[[clang::no_destroy]] wuxc::Canvas g_netTxGraphCanvas{nullptr};
[[clang::no_destroy]] winrt::Windows::UI::Xaml::Shapes::Polyline g_netRxLine{nullptr};
[[clang::no_destroy]] winrt::Windows::UI::Xaml::Shapes::Polyline g_netTxLine{nullptr};
[[clang::no_destroy]] winrt::Windows::UI::Xaml::Shapes::Polygon g_netRxFill{nullptr};
[[clang::no_destroy]] winrt::Windows::UI::Xaml::Shapes::Polygon g_netTxFill{nullptr};
// Sequence number of the history this graph was last drawn from, so the cheap
// refresh ticks between samples do not re-render (and therefore cannot flicker).
static unsigned long long g_netGraphRenderedSeq = ~0ull;
// Quantised y-scale with hysteresis. A scale that followed the raw peak would
// rescale - and visibly jump - on nearly every sample.
static double g_netGraphScale = 1024.0 * 1024.0;
static int g_netGraphScaleHold = 0;
[[clang::no_destroy]] DispatcherTimer g_netFlyoutTimer{nullptr};
// Tile value blocks inside the flyout, refreshed in place so the panel is not
// rebuilt (and its scroll position reset) every second.
[[clang::no_destroy]] wuxc::TextBlock g_netDlNowText{nullptr};
[[clang::no_destroy]] wuxc::TextBlock g_netUlNowText{nullptr};
[[clang::no_destroy]] wuxc::TextBlock g_netDlPeakText{nullptr};
[[clang::no_destroy]] wuxc::TextBlock g_netUlPeakText{nullptr};

// Refresh the live values of an already-built network panel.
void UpdateNetworkFlyoutGraph();
static void RefreshNetworkPanelValues() {
    try {
        if (g_netDlNowText) g_netDlNowText.Text(winrt::hstring(netmon::FormatSpeed(netmon::s_lastRx)));
        if (g_netUlNowText) g_netUlNowText.Text(winrt::hstring(netmon::FormatSpeed(netmon::s_lastTx)));
        if (g_netDlPeakText) g_netDlPeakText.Text(winrt::hstring(netmon::FormatSpeed(netmon::s_peakRx)));
        if (g_netUlPeakText) g_netUlPeakText.Text(winrt::hstring(netmon::FormatSpeed(netmon::s_peakTx)));
        UpdateNetworkFlyoutGraph();
    } catch (...) {}
}

// Points for one throughput series. Always returns at least two points pinned
// to the bottom of the graph, so an idle link still shows a flat line at 0
// instead of the line disappearing.
static std::vector<wf::Point> BuildNetGraphPoints(std::deque<float> const& hist,
                                                  double width, double height,
                                                  double maxVal) {
    std::vector<wf::Point> pts;
    // Idle links must still show something: a curve pinned exactly to the
    // bottom edge gets half its stroke clipped and has no fill at all, so the
    // graph looks like it vanished at 0 B/s. Keep the trace a few pixels above
    // the floor instead, which reads as a thin flat baseline.
    constexpr double kMinLift = 3.0;
    const double floorY = (height > kMinLift * 2.0) ? height - kMinLift : height;
    const size_t count = hist.size();
    if (count == 0) {
        pts.push_back(wf::Point{0.0f, static_cast<float>(floorY)});
        pts.push_back(wf::Point{static_cast<float>(width),
                                static_cast<float>(floorY)});
        return pts;
    }
    if (count == 1) {
        double y = std::min(height - height * (hist[0] / maxVal), floorY);
        pts.push_back(wf::Point{0.0f, static_cast<float>(y)});
        pts.push_back(wf::Point{static_cast<float>(width),
                                static_cast<float>(y)});
        return pts;
    }
    for (size_t i = 0; i < count; ++i) {
        double x = width * i / (count - 1);
        double y = std::min(height - (height * (hist[i] / maxVal)), floorY);
        pts.push_back(wf::Point{static_cast<float>(x), static_cast<float>(y)});
    }
    return pts;
}

static double NetSeriesMax(std::deque<float> const& a, std::deque<float> const& b) {
    double maxVal = 1024.0 * 1024.0;
    for (float v : a) if (v > maxVal) maxVal = v;
    for (float v : b) if (v > maxVal) maxVal = v;
    return maxVal;
}

// Vertical area-fill gradient for a network graph series: strong at the curve,
// fully transparent at the baseline.
static wuxm::Brush MakeNetGraphFillBrush(wui::Color color) {
    wuxm::LinearGradientBrush brush;
    brush.StartPoint({0.5, 0.0});
    brush.EndPoint({0.5, 1.0});
    wuxm::GradientStop top;
    top.Offset(0.0);
    top.Color(wui::ColorHelper::FromArgb(145, color.R, color.G, color.B));
    wuxm::GradientStop bottom;
    bottom.Offset(1.0);
    bottom.Color(wui::ColorHelper::FromArgb(0, color.R, color.G, color.B));
    brush.GradientStops().Append(top);
    brush.GradientStops().Append(bottom);
    return brush;
}

// Smallest "nice" scale that still contains maxVal. A quantised scale means the
// y-axis moves in steps instead of chasing the peak on every sample, which is
// what made the old graph appear to blink.
static double NetGraphScaleFor(double maxVal) {
    static const double kSteps[] = {
        64.0 * 1024.0,           128.0 * 1024.0,
        256.0 * 1024.0,          512.0 * 1024.0,
        1024.0 * 1024.0,         2.0 * 1024.0 * 1024.0,
        5.0 * 1024.0 * 1024.0,   10.0 * 1024.0 * 1024.0,
        20.0 * 1024.0 * 1024.0,  50.0 * 1024.0 * 1024.0,
        100.0 * 1024.0 * 1024.0, 200.0 * 1024.0 * 1024.0,
        500.0 * 1024.0 * 1024.0, 1024.0 * 1024.0 * 1024.0};
    for (double step : kSteps) {
        if (maxVal <= step) return step;
    }
    return kSteps[ARRAYSIZE(kSteps) - 1];
}

void UpdateNetworkFlyoutGraph() {
    if (!g_netRxLine && !g_netTxLine) return;

    // Redraw only when a new sample actually arrived. The flyout refreshes its
    // labels far more often than the history grows, and re-rendering the curves
    // on those ticks is what made them flutter.
    const unsigned long long seq = netmon::g_netSampleSeq.load();
    if (seq == g_netGraphRenderedSeq) return;
    g_netGraphRenderedSeq = seq;

    double rxH = g_netGraphCanvas ? g_netGraphCanvas.ActualHeight() : 0.0;
    double txH = g_netTxGraphCanvas ? g_netTxGraphCanvas.ActualHeight() : 0.0;
    double rxW = g_netGraphCanvas ? g_netGraphCanvas.ActualWidth() : 0.0;
    double txW = g_netTxGraphCanvas ? g_netTxGraphCanvas.ActualWidth() : 0.0;
    if (rxW <= 0) rxW = 300;
    if (txW <= 0) txW = 300;
    if (rxH <= 0) rxH = 96;
    if (txH <= 0) txH = 96;

    // Grow instantly, shrink only after the peak has stayed low for a while, so
    // the curve breathes instead of jumping on every sample.
    const double peak =
        NetSeriesMax(netmon::g_netRxHistory, netmon::g_netTxHistory);
    const double wanted = NetGraphScaleFor(peak);
    if (wanted >= g_netGraphScale) {
        g_netGraphScale = wanted;
        g_netGraphScaleHold = 0;
    } else if (++g_netGraphScaleHold > 12) {
        g_netGraphScale = wanted;
        g_netGraphScaleHold = 0;
    }
    const double maxVal = g_netGraphScale;

    // Draws one series (area fill + stroke) and slides it in from the right by
    // exactly one sample, mirroring the Resource Monitor graph animation.
    auto renderSeries = [](std::deque<float> const& hist, double width,
                           double height, double scale, wui::Color color,
                           winrt::Windows::UI::Xaml::Shapes::Polyline line,
                           winrt::Windows::UI::Xaml::Shapes::Polygon fill) {
        if (!line || width <= 0 || height <= 0) return;
        const std::vector<wf::Point> linePts =
            BuildNetGraphPoints(hist, width, height, scale);
        if (linePts.size() < 2) return;
        try {
            // Re-apply the colours on every draw. ApplyIconColorToElement()
            // repaints the Fill/Stroke of every Shape in the tree with the
            // global icon colour (white by default), so a brush assigned once
            // at build time does not survive a style pass.
            line.Stroke(MakeBrush(255, color.R, color.G, color.B));
            if (fill) fill.Fill(MakeNetGraphFillBrush(color));

            auto lp = line.Points();
            lp.Clear();
            for (auto const& p : linePts) lp.Append(p);
            if (fill) {
                auto fp = fill.Points();
                fp.Clear();
                fp.Append(wf::Point{0.0f, static_cast<float>(height)});
                for (auto const& p : linePts) fp.Append(p);
                fp.Append(wf::Point{static_cast<float>(width),
                                    static_cast<float>(height)});
            }
        } catch (...) {
            return;
        }

        const float stepW = static_cast<float>(
            width / static_cast<double>(linePts.size() - 1));
        try {
            wuxh::ElementCompositionPreview::SetIsTranslationEnabled(line, true);
            auto lineVis = wuxh::ElementCompositionPreview::GetElementVisual(line);
            if (!lineVis) return;
            auto fillVis =
                fill ? wuxh::ElementCompositionPreview::GetElementVisual(fill)
                     : nullptr;
            auto compositor = lineVis.Compositor();
            if (!compositor) return;

            lineVis.StopAnimation(L"Offset");
            lineVis.Offset({stepW, 0.0f, 0.0f});
            if (fillVis) {
                fillVis.StopAnimation(L"Offset");
                fillVis.Offset({stepW, 0.0f, 0.0f});
            }

            auto ease = compositor.CreateCubicBezierEasingFunction(
                {0.0f, 0.0f}, {0.25f, 1.0f});
            auto anim = compositor.CreateVector3KeyFrameAnimation();
            anim.Duration(std::chrono::milliseconds(300));
            anim.InsertKeyFrame(0.0f, {stepW, 0.0f, 0.0f}, ease);
            anim.InsertKeyFrame(1.0f, {0.0f, 0.0f, 0.0f}, ease);
            lineVis.StartAnimation(L"Offset", anim);
            if (fillVis) fillVis.StartAnimation(L"Offset", anim);
        } catch (...) {}
    };

    renderSeries(netmon::g_netRxHistory, rxW, rxH, maxVal,
                 wui::ColorHelper::FromArgb(255, 0x5C, 0x9E, 0xFA),
                 g_netRxLine, g_netRxFill);
    renderSeries(netmon::g_netTxHistory, txW, txH, maxVal,
                 wui::ColorHelper::FromArgb(255, 0xE8, 0x6C, 0x2E),
                 g_netTxLine, g_netTxFill);
}

void PopulateNetworkPanel() {
    if (!g_networkPanel) return;
    g_populatingPanel = true;
    struct Guard { ~Guard() { g_populatingPanel = false; } } guard;
    auto children = g_networkPanel.Children();
    children.Clear();
    children.Append(MakePanelTitle(L"Network Monitor"));

    const bool winui = IsWinUI3StyleMode();
    auto rxColor = wui::ColorHelper::FromArgb(255, 0x5C, 0x9E, 0xFA);
    auto txColor = wui::ColorHelper::FromArgb(255, 0xE8, 0x6C, 0x2E);

    // One labelled graph per direction, stacked, exactly like the reference:
    // "Download" heading over a blue area graph, "Upload" over an orange one.
    auto makeGraph = [winui](std::wstring_view heading, wui::Color color,
                        wuxc::Canvas& outCanvas,
                        winrt::Windows::UI::Xaml::Shapes::Polyline& outLine,
                        winrt::Windows::UI::Xaml::Shapes::Polygon& outFill) {
        wuxc::StackPanel wrap;
        wrap.Spacing(4);
        auto lbl = MakeText(nullptr, heading, 13, true, 0.85);
        wrap.Children().Append(lbl);

        wuxc::Canvas canvas;
        canvas.Height(96);
        canvas.HorizontalAlignment(HorizontalAlignment::Stretch);
        {
            wuxm::RectangleGeometry clipGeom;
            clipGeom.Rect({0.0f, 0.0f, 4000.0f, 96.0f});
            canvas.Clip(clipGeom);
        }
        wuxc::Border border;
        border.Height(96);
        border.Background(MakeBrush(winui ? 0x0F : 0x12, 0xFF, 0xFF, 0xFF));
        border.BorderBrush(MakeBrush(winui ? 0x1A : 0x1E, 0xFF, 0xFF, 0xFF));
        border.BorderThickness(Thickness{1, 1, 1, 1});
        border.CornerRadius(MakeCorner(winui ? 6 : 8));
        try { border.BackgroundSizing(wuxc::BackgroundSizing::InnerBorderEdge); } catch (...) {}
        border.Margin(Thickness{0, 0, 0, 8});
        border.HorizontalAlignment(HorizontalAlignment::Stretch);
        border.Child(canvas);

        // Translucent area fill under the stroke, fading out towards the
        // bottom, exactly like the Resource Monitor graph. The brush is
        // re-applied on every redraw because the global icon-colour pass
        // repaints every Shape in the tree.
        winrt::Windows::UI::Xaml::Shapes::Polygon fill;
        fill.Fill(MakeNetGraphFillBrush(color));
        fill.Stretch(wuxm::Stretch::None);
        fill.IsHitTestVisible(false);
        canvas.Children().Append(fill);

        winrt::Windows::UI::Xaml::Shapes::Polyline line;
        line.Stroke(MakeBrush(255, color.R, color.G, color.B));
        line.StrokeThickness(2);
        line.Stretch(wuxm::Stretch::None);
        line.IsHitTestVisible(false);
        canvas.Children().Append(line);

        // Keep the sliding curve inside the graph box, and force a redraw once
        // the real width is known: the first draw happens before layout, when
        // the canvas is still 0 px wide.
        canvas.SizeChanged([canvas](auto&&, auto&&) {
            try {
                wuxm::RectangleGeometry clipGeom;
                clipGeom.Rect({0.0f, 0.0f,
                               static_cast<float>(canvas.ActualWidth()), 96.0f});
                canvas.Clip(clipGeom);
            } catch (...) {}
            g_netGraphRenderedSeq = ~0ull;
        });

        wrap.Children().Append(border);
        outCanvas = canvas;
        outLine = line;
        outFill = fill;
        return wrap;
    };

    wuxc::Canvas rxCanvas{nullptr};
    winrt::Windows::UI::Xaml::Shapes::Polyline rxLine{nullptr};
    winrt::Windows::UI::Xaml::Shapes::Polygon rxFill{nullptr};
    children.Append(makeGraph(L"Download", rxColor, rxCanvas, rxLine, rxFill));
    wuxc::Canvas txCanvas{nullptr};
    winrt::Windows::UI::Xaml::Shapes::Polyline txLine{nullptr};
    winrt::Windows::UI::Xaml::Shapes::Polygon txFill{nullptr};
    children.Append(makeGraph(L"Upload", txColor, txCanvas, txLine, txFill));
    // Names keep the series out of the global icon-colour pass, which repaints
    // the Fill/Stroke of every Shape it finds with the icon colour (white).
    if (rxFill) rxFill.Name(L"NetGraphRxFill");
    if (rxLine) rxLine.Name(L"NetGraphRxLine");
    if (txFill) txFill.Name(L"NetGraphTxFill");
    if (txLine) txLine.Name(L"NetGraphTxLine");

    // 2x2 tiles: current speed and the 1-minute peak for each direction.
    auto makeTile = [winui](std::wstring_view title, std::wstring value,
                       wuxc::TextBlock* outText) {
        wuxc::Border tile;
        tile.Background(MakeBrush(winui ? 0x0F : 0x14, 0xFF, 0xFF, 0xFF));
        if (winui) {
            tile.BorderBrush(MakeBrush(0x1A, 0xFF, 0xFF, 0xFF));
            tile.BorderThickness(Thickness{1, 1, 1, 1});
            try { tile.BackgroundSizing(wuxc::BackgroundSizing::InnerBorderEdge); } catch (...) {}
        }
        tile.CornerRadius(MakeCorner(winui ? 6 : 10));
        tile.Padding(Thickness{12, 8, 12, 8});
        tile.Margin(Thickness{0, 0, 0, 8});
        wuxc::StackPanel sp;
        sp.Spacing(2);
        sp.Children().Append(MakeText(nullptr, title, 12, false, 0.6));
        auto val = MakeText(nullptr, value, 20, true);
        if (outText) *outText = val;
        sp.Children().Append(val);
        tile.Child(sp);
        return tile;
    };

    wuxc::Grid tiles;
    tiles.ColumnSpacing(10);
    tiles.RowSpacing(0);
    for (int i = 0; i < 2; ++i) {
        wuxc::ColumnDefinition cd;
        cd.Width(GridLength{1, GridUnitType::Star});
        tiles.ColumnDefinitions().Append(cd);
    }
    for (int i = 0; i < 2; ++i) {
        wuxc::RowDefinition rd;
        rd.Height(GridLength{0, GridUnitType::Auto});
        tiles.RowDefinitions().Append(rd);
    }
    auto dlNow = makeTile(L"Download", netmon::FormatSpeed(netmon::s_lastRx),
                          &g_netDlNowText);
    wuxc::Grid::SetColumn(dlNow, 0);
    wuxc::Grid::SetRow(dlNow, 0);
    tiles.Children().Append(dlNow);
    auto ulNow = makeTile(L"Upload", netmon::FormatSpeed(netmon::s_lastTx),
                          &g_netUlNowText);
    wuxc::Grid::SetColumn(ulNow, 1);
    wuxc::Grid::SetRow(ulNow, 0);
    tiles.Children().Append(ulNow);
    auto dlPeak = makeTile(L"Download peak",
                           netmon::FormatSpeed(netmon::s_peakRx),
                           &g_netDlPeakText);
    wuxc::Grid::SetColumn(dlPeak, 0);
    wuxc::Grid::SetRow(dlPeak, 1);
    tiles.Children().Append(dlPeak);
    auto ulPeak = makeTile(L"Upload peak",
                           netmon::FormatSpeed(netmon::s_peakTx),
                           &g_netUlPeakText);
    wuxc::Grid::SetColumn(ulPeak, 1);
    wuxc::Grid::SetRow(ulPeak, 1);
    tiles.Children().Append(ulPeak);
    children.Append(tiles);

    children.Append(MakeDivider());
    children.Append(MakeSettingsLink(L"Network settings", L"ms-settings:network"));

    g_netGraphCanvas = rxCanvas;
    g_netTxGraphCanvas = txCanvas;
    g_netRxLine = rxLine;
    g_netTxLine = txLine;
    g_netRxFill = rxFill;
    g_netTxFill = txFill;
    // The shapes are brand new, so redraw even if the history has not moved.
    g_netGraphRenderedSeq = ~0ull;

    UpdateNetworkFlyoutGraph();

    if (!g_netFlyoutTimer) {
        g_netFlyoutTimer = DispatcherTimer();
        g_netFlyoutTimer.Interval(std::chrono::seconds(1));
        g_netFlyoutTimer.Tick([](wf::IInspectable const&, wf::IInspectable const&) {
            try {
                if (g_networkFlyout && g_networkFlyout.IsOpen()) {
                    // Refresh the existing widgets in place from the values the
                    // background timer already read. Rebuilding the panel every
                    // second reset its scroll position and made it flicker, and
                    // reading the counters here as well made the per-second rate
                    // values noisy.
                    RefreshNetworkPanelValues();
                } else {
                    g_netFlyoutTimer.Stop();
                }
            } catch (...) {}
        });
    }
    g_netFlyoutTimer.Start();
    if (g_networkPanel) ApplyControlStylesToPopupRoot(g_networkPanel.as<FrameworkElement>());
}

void AdaptTopBarHeightDensity() {
    try {
        int barH = std::max(30, g_settings.barHeightDip);

        FrameworkElement topBarRoot{nullptr};
        if (auto it = g_namedElements.find(L"TopBarRoot"); it != g_namedElements.end()) {
            topBarRoot = it->second;
        }
        if (!topBarRoot) return;

        // At ultra-compact heights (<= 34 DIP), clamp Top/Bottom to <= 1 DIP so inner
        // buttons fit across all 30 DIP, while always honoring explicit 0 bottom margin.
        auto rm = topBarRoot.Margin();
        if (barH <= 34) {
            if (rm.Top > 1.0 || rm.Bottom > 1.0) {
                topBarRoot.Margin(Thickness{
                    rm.Left, std::min(rm.Top, 1.0),
                    rm.Right, std::min(rm.Bottom, 1.0)});
            }
        }

        if (barH > 36) return;

        const double maxVertM = (barH <= 32) ? 1.0 : ((barH <= 34) ? 1.5 : 2.5);
        const double maxVertP = (barH <= 33) ? 0.0 : 1.0;

        auto adaptButton = [maxVertM, maxVertP](wuxc::Button const& btn) {
            if (!btn) return;
            try {
                btn.MinHeight(0);
                btn.VerticalAlignment(VerticalAlignment::Stretch);
                auto m = btn.Margin();
                if (m.Top > maxVertM || m.Bottom > maxVertM) {
                    btn.Margin(Thickness{
                        m.Left, std::min(m.Top, maxVertM),
                        m.Right, std::min(m.Bottom, maxVertM)});
                }
                auto p = btn.Padding();
                if (p.Top > maxVertP || p.Bottom > maxVertP) {
                    btn.Padding(Thickness{
                        p.Left, std::min(p.Top, maxVertP),
                        p.Right, std::min(p.Bottom, maxVertP)});
                }
            } catch (...) {}
        };

        std::function<void(wuxc::Panel const&)> adaptPanel = [&](wuxc::Panel const& panel) {
            if (!panel) return;
            try {
                for (auto&& child : panel.Children()) {
                    if (auto btn = child.try_as<wuxc::Button>()) {
                        adaptButton(btn);
                    } else if (auto sub = child.try_as<wuxc::Panel>()) {
                        adaptPanel(sub);
                    }
                }
            } catch (...) {}
        };

        if (auto grid = topBarRoot.try_as<wuxc::Panel>()) {
            adaptPanel(grid);
        }
        for (auto const& kv : g_taskButtonsByHwnd) {
            adaptButton(kv.second);
        }
    } catch (...) {}
}

void AdaptNetworkButtonDensity() {
    if (!g_networkButton) return;
    try {
        int barH = std::max(30, g_settings.barHeightDip);
        if (barH <= 36) {
            auto curMargin = g_networkButton.Margin();
            double maxVertM = (barH <= 33) ? 1.5 : 2.5;
            if (curMargin.Top > maxVertM || curMargin.Bottom > maxVertM) {
                g_networkButton.Margin(Thickness{
                    curMargin.Left, std::min(curMargin.Top, maxVertM),
                    curMargin.Right, std::min(curMargin.Bottom, maxVertM)});
            }
            auto curPad = g_networkButton.Padding();
            double maxVertP = (barH <= 33) ? 0.5 : 1.0;
            if (curPad.Top > maxVertP || curPad.Bottom > maxVertP) {
                g_networkButton.Padding(Thickness{
                    curPad.Left, std::min(curPad.Top, maxVertP),
                    curPad.Right, std::min(curPad.Bottom, maxVertP)});
            }
        }
        auto m = g_networkButton.Margin();
        auto b = g_networkButton.BorderThickness();
        auto p = g_networkButton.Padding();
        double availH = std::max(14.0, static_cast<double>(barH) - (m.Top + m.Bottom + b.Top + b.Bottom + p.Top + p.Bottom));

        const double rowH = (availH >= 26.0) ? 13.0 : (availH >= 20.0 ? 10.5 : std::max(8.0, (availH - 1.0) * 0.5));
        const double fontSize = (availH >= 26.0) ? 11.0 : (availH >= 20.0 ? 9.5 : 8.5);
        const double lineH = fontSize + 1.0;
        const double iconSize = (availH >= 26.0) ? 14.0 : (availH >= 20.0 ? 11.5 : 10.0);
        const double rowSpacing = (availH >= 21.0) ? 0.0 : -1.0;

        auto gridIt = g_namedElements.find(L"NetworkGrid");
        if (gridIt != g_namedElements.end()) {
            if (auto grid = gridIt->second.try_as<wuxc::Grid>()) {
                grid.RowSpacing(rowSpacing);
                auto rows = grid.RowDefinitions();
                for (uint32_t i = 0; i < rows.Size(); ++i) {
                    rows.GetAt(i).Height(GridLength{rowH, GridUnitType::Pixel});
                }
                for (uint32_t i = 0; i < grid.Children().Size(); ++i) {
                    auto row = grid.Children().GetAt(i).try_as<wuxc::Grid>();
                    if (!row) continue;
                    row.Height(rowH);
                    const bool isUp = (i == 0);
                    if (row.Children().Size() > 0) {
                        if (auto sp = row.Children().GetAt(0).try_as<wuxc::StackPanel>()) {
                            sp.Spacing(availH >= 24.0 ? 4.0 : 3.0);
                            for (uint32_t j = 0; j < sp.Children().Size(); ++j) {
                                auto child = sp.Children().GetAt(j);
                                if (auto icon = child.try_as<wuxc::FontIcon>()) {
                                    icon.FontSize(iconSize);
                                    icon.Margin(isUp
                                        ? (availH >= 26.0 ? Thickness{0, -3, 0, 2} : Thickness{0, -2, 0, 1})
                                        : (availH >= 26.0 ? Thickness{0, 2, 0, -3} : Thickness{0, 1, 0, -2}));
                                } else if (auto txt = child.try_as<wuxc::TextBlock>()) {
                                    txt.FontSize(fontSize);
                                    txt.LineHeight(lineH);
                                }
                            }
                        }
                    }
                }
            }
        }
    } catch (...) {}
}

void UpdateNetworkButton() {
    if (!g_networkButton) return;
    if (!g_settings.showNetworkButton) {
        try {
            g_networkButton.Visibility(Visibility::Collapsed);
        } catch (...) {}
        return;
    }
    try {
        g_networkButton.Visibility(Visibility::Visible);
    } catch (...) {}
    const auto sample = netmon::SampleNow();
    if (g_networkDownloadText) {
        try {
            g_networkDownloadText.Text(
                winrt::hstring(netmon::FormatSpeed(sample.downloadBytesPerSec)));
        } catch (...) {}
    }
    if (g_networkUploadText) {
        try {
            g_networkUploadText.Text(
                winrt::hstring(netmon::FormatSpeed(sample.uploadBytesPerSec)));
        } catch (...) {}
    }
}

