constexpr double kGaugeCx = 140.0;
constexpr double kGaugeCy = 102.0;
constexpr double kGaugeR = 86.0;
constexpr double kGaugeStartDeg = 135.0; // bottom-left -> +270 deg clockwise = 75% circle
constexpr double kGaugeSpanDeg = 270.0;

inline wf::Point PointOnDial(double angleDeg, double radius = kGaugeR) {
    constexpr double kPi = 3.14159265358979323846;
    double rad = angleDeg * kPi / 180.0;
    return wf::Point{
        static_cast<float>(kGaugeCx + radius * std::cos(rad)),
        static_cast<float>(kGaugeCy + radius * std::sin(rad))
    };
}

// Piecewise speedometer scale matching reference tick marks: 0, 5, 10, 50, 100, 250, 500, 750, 1000
inline double MbpsToDialNorm(double mbps) {
    if (mbps <= 0.0 || std::isnan(mbps) || std::isinf(mbps)) return 0.0;
    static constexpr double kTicks[9] = { 0.0, 5.0, 10.0, 50.0, 100.0, 250.0, 500.0, 750.0, 1000.0 };
    if (mbps >= 1000.0) return 1.0;
    for (int i = 0; i < 8; ++i) {
        if (mbps <= kTicks[i + 1]) {
            double t = (mbps - kTicks[i]) / (kTicks[i + 1] - kTicks[i]);
            return (static_cast<double>(i) + t) / 8.0;
        }
    }
    return 1.0;
}

inline std::wstring FormatRate(double mbps) {
    if (mbps < 0.0 || std::isnan(mbps)) return L"\u2014";
    wchar_t buf[32]{};
    if (mbps >= 1000.0) {
        swprintf_s(buf, L"%.0f", mbps);
    } else if (mbps >= 100.0) {
        swprintf_s(buf, L"%.2f", mbps);
    } else if (mbps >= 10.0) {
        swprintf_s(buf, L"%.1f", mbps);
    } else {
        swprintf_s(buf, L"%.2f", mbps);
    }
    return buf;
}

inline std::wstring FormatSummaryRate(double mbps) {
    if (mbps < 0.0 || std::isnan(mbps)) return L"\u2014";
    wchar_t buf[32]{};
    if (mbps >= 100.0) {
        swprintf_s(buf, L"%.0f", mbps);
    } else if (mbps >= 10.0) {
        swprintf_s(buf, L"%.1f", mbps);
    } else {
        swprintf_s(buf, L"%.2f", mbps);
    }
    return buf;
}

inline wuxm::LinearGradientBrush MakeArcGradient(wui::Color c0, wui::Color c1) {
    wuxm::LinearGradientBrush lgb;
    lgb.StartPoint(wf::Point{ 0.0f, 1.0f });
    lgb.EndPoint(wf::Point{ 0.85f, 0.05f });
    wuxm::GradientStop gs0;
    gs0.Color(c0);
    gs0.Offset(0.0);
    wuxm::GradientStop gs1;
    gs1.Color(c1);
    gs1.Offset(1.0);
    lgb.GradientStops().Append(gs0);
    lgb.GradientStops().Append(gs1);
    return lgb;
}


inline bool IsCancelled(uint64_t runId) {
    return g_runId.load() != runId ||
           InterlockedCompareExchange(&g_shuttingDown, 0, 0) != 0 ||
           (g_stopEvent && WaitForSingleObject(g_stopEvent, 0) == WAIT_OBJECT_0);
}

