    children.Append(tabPanel);

    g_tabButtons.clear();
    g_tabButtons.push_back(cpuTab);
    g_tabButtons.push_back(ramTab);
    g_tabButtons.push_back(gpuTab);
    g_tabButtons.push_back(diskTab);

    const bool winui = IsWinUI3StyleMode();
    wuxc::Border infoIsland;
    infoIsland.Name(L"InfoIsland");
    infoIsland.Background(MakeBrush(winui ? 0x0F : 0x15, 0xFF, 0xFF, 0xFF));
    infoIsland.CornerRadius(MakeCorner(6));
    infoIsland.BorderBrush(MakeBrush(winui ? 0x1A : 0x20, 0xFF, 0xFF, 0xFF));
    infoIsland.BorderThickness(Thickness{1, 1, 1, 1});
    try { infoIsland.BackgroundSizing(wuxc::BackgroundSizing::InnerBorderEdge); } catch (...) {}
    infoIsland.Margin(Thickness{0, 0, 0, 4});
    infoIsland.Padding(Thickness{12, 8, 12, 8});
    infoIsland.Height(74);
    infoIsland.MinHeight(74);
    infoIsland.HorizontalAlignment(HorizontalAlignment::Stretch);
    infoIsland.VerticalAlignment(VerticalAlignment::Top);

    // Use a Grid with 3 separate StackPanels so collapsed tabs contribute zero StackPanel.Spacing.
    wuxc::Grid infoStack;
    infoStack.HorizontalAlignment(HorizontalAlignment::Stretch);
