    g_infoCpuPanel.HorizontalAlignment(HorizontalAlignment::Stretch);
    g_infoCpuPanel.VerticalAlignment(VerticalAlignment::Center);
    g_infoCpuLabel = MakeText(L"InfoCpuLabel", L"CPU", 10, false, 0.65);
    g_infoCpuLabel.HorizontalAlignment(HorizontalAlignment::Left);
    g_infoCpuLabel.TextAlignment(TextAlignment::Left);
    g_infoCpuName = MakeText(L"InfoCpuName", L"Loading...", 13, true);
    g_infoCpuName.HorizontalAlignment(HorizontalAlignment::Left);
    g_infoCpuName.TextAlignment(TextAlignment::Left);
    g_infoCpuName.TextTrimming(TextTrimming::CharacterEllipsis);
