wuxm::Brush CreateWinUI3MenuBlurBrush(UIElement const& element) {
    try {
        float blurAmt = std::max(28.0f, static_cast<float>(g_settings.globalBlurAmount));
        wui::Color tint = wui::ColorHelper::FromArgb(0xFF, 0x2C, 0x2C, 0x2E);
        uint8_t tintAlpha = 0xC8;
        if (!g_settings.topBarBackgroundColor.empty()) {
            wui::Color userTint{};
            if (TryParseHexColor(g_settings.topBarBackgroundColor, &userTint) ||
                TryParseNamedColor(g_settings.topBarBackgroundColor, &userTint)) {
                // Blend subtle user tint into dark WinUI 3 charcoal Acrylic so menus stay legible & cohesive
                tint = wui::ColorHelper::FromArgb(
                    0xFF,
                    static_cast<uint8_t>((int(tint.R) * 3 + int(userTint.R)) / 4),
                    static_cast<uint8_t>((int(tint.G) * 3 + int(userTint.G)) / 4),
                    static_cast<uint8_t>((int(tint.B) * 3 + int(userTint.B)) / 4));
            }
        }
        return winrt::make<XamlBlurBrush>(
            element, blurAmt, tint, tintAlpha, false, 1.15f, 1.0f, true);
    } catch (...) {
        return MakeBrush(0xE8, 0x2C, 0x2C, 0x2E);
    }
}

wuxc::ControlTemplate GetWinUI3MenuItemTemplate(bool hasIcon) {
    static thread_local wuxc::ControlTemplate s_tplIconWin{nullptr};
    static thread_local wuxc::ControlTemplate s_tplPlainWin{nullptr};
    wuxc::ControlTemplate& slot = hasIcon ? s_tplIconWin : s_tplPlainWin;
    if (slot) return slot;

    std::wstring iconCol = L"";
    if (hasIcon) {
        iconCol =
            L"<TextBlock x:Name=\"MenuGlyph\" Text=\"{TemplateBinding Tag}\" "
            L"FontFamily=\"Segoe Fluent Icons, Segoe MDL2 Assets\" FontSize=\"14\" "
            L"Foreground=\"#EBFFFFFF\" TextLineBounds=\"Full\" OpticalMarginAlignment=\"None\" "
            L"Margin=\"0,0,10,0\" Padding=\"0\" "
            L"HorizontalAlignment=\"Center\" VerticalAlignment=\"Center\"/>";
    }
    std::wstring textColIdx = hasIcon ? L" Grid.Column=\"1\"" : L" Grid.Column=\"0\"";
    std::wstring cols = hasIcon
        ? L"<Grid.ColumnDefinitions><ColumnDefinition Width=\"Auto\"/><ColumnDefinition Width=\"*\"/></Grid.ColumnDefinitions>"
        : L"<Grid.ColumnDefinitions><ColumnDefinition Width=\"*\"/></Grid.ColumnDefinitions>";

    std::wstring xaml =
        L"<ControlTemplate xmlns=\"http://schemas.microsoft.com/winfx/2006/xaml/presentation\" "
        L"xmlns:x=\"http://schemas.microsoft.com/winfx/2006/xaml\" "
        L"TargetType=\"MenuFlyoutItem\">"
        L"<Grid x:Name=\"Root\" Background=\"Transparent\" Margin=\"4,2,4,2\">"
        L"<VisualStateManager.VisualStateGroups>"
        L"<VisualStateGroup x:Name=\"CommonStates\">"
        L"<VisualState x:Name=\"Normal\"/>"
        L"<VisualState x:Name=\"PointerOver\">"
        L"<Storyboard><DoubleAnimation Storyboard.TargetName=\"HoverPill\" Storyboard.TargetProperty=\"Opacity\" To=\"1\" Duration=\"0:0:0.06\"/></Storyboard>"
        L"</VisualState>"
        L"<VisualState x:Name=\"Pressed\">"
        L"<Storyboard>"
        L"<DoubleAnimation Storyboard.TargetName=\"PressedPill\" Storyboard.TargetProperty=\"Opacity\" To=\"1\" Duration=\"0\"/>"
        L"<DoubleAnimation Storyboard.TargetName=\"ContentGrid\" Storyboard.TargetProperty=\"Opacity\" To=\"0.76\" Duration=\"0\"/>"
        L"</Storyboard>"
        L"</VisualState>"
        L"<VisualState x:Name=\"Disabled\">"
        L"<Storyboard><DoubleAnimation Storyboard.TargetName=\"ContentGrid\" Storyboard.TargetProperty=\"Opacity\" To=\"0.4\" Duration=\"0\"/></Storyboard>"
        L"</VisualState>"
        L"</VisualStateGroup>"
        L"</VisualStateManager.VisualStateGroups>"
        L"<Border x:Name=\"BaseBg\" BackgroundSizing=\"InnerBorderEdge\" "
        L"Background=\"{TemplateBinding Background}\" BorderBrush=\"{TemplateBinding BorderBrush}\" "
        L"BorderThickness=\"{TemplateBinding BorderThickness}\" CornerRadius=\"4\"/>"
        L"<Border x:Name=\"HoverPill\" BackgroundSizing=\"InnerBorderEdge\" "
        L"Background=\"{ThemeResource MenuFlyoutItemBackgroundPointerOver}\" BorderThickness=\"0\" "
        L"CornerRadius=\"4\" Opacity=\"0\" IsHitTestVisible=\"False\"/>"
        L"<Border x:Name=\"PressedPill\" BackgroundSizing=\"InnerBorderEdge\" "
        L"Background=\"{ThemeResource MenuFlyoutItemBackgroundPressed}\" BorderThickness=\"0\" "
        L"CornerRadius=\"4\" Opacity=\"0\" IsHitTestVisible=\"False\"/>"
        L"<Grid x:Name=\"ContentGrid\" MinHeight=\"32\" Padding=\"{TemplateBinding Padding}\">"
        + cols + iconCol +
        L"<TextBlock x:Name=\"MenuTextLabel\"" + textColIdx +
        L" Text=\"{TemplateBinding Text}\" Foreground=\"{TemplateBinding Foreground}\" "
        L"FontFamily=\"{TemplateBinding FontFamily}\" FontSize=\"{TemplateBinding FontSize}\" "
        L"FontWeight=\"{TemplateBinding FontWeight}\" TextLineBounds=\"Full\" Padding=\"0\" "
        L"VerticalAlignment=\"Center\" TextTrimming=\"CharacterEllipsis\"/>"
        L"</Grid>"
        L"</Grid>"
        L"</ControlTemplate>";
    try {
        slot = Markup::XamlReader::Load(xaml).as<wuxc::ControlTemplate>();
    } catch (...) {}
    return slot;
}

