Style MakeMenuPresenterStyle() {
    Style style(winrt::xaml_typename<wuxc::MenuFlyoutPresenter>());
    auto setters = style.Setters();
    try {
        std::wstring ff = g_settings.fontFamily.empty()
            ? L"Segoe UI Variable Text, Segoe UI"
            : g_settings.fontFamily;
        setters.Append(Setter(wuxc::Control::FontFamilyProperty(),
                              winrt::box_value(wuxm::FontFamily(winrt::hstring(ff)))));
    } catch (...) {}
    setters.Append(Setter(wuxc::Control::FontWeightProperty(),
                          winrt::box_value(winrt::Windows::UI::Text::FontWeights::Normal())));
    setters.Append(Setter(wuxc::Control::BackgroundProperty(),
                          winrt::box_value(FlyoutBackgroundBrush())));
    setters.Append(Setter(wuxc::Control::BorderBrushProperty(),
                          winrt::box_value(MakeBrush(0x1E, 0xFF, 0xFF, 0xFF))));
    setters.Append(Setter(wuxc::Control::BorderThicknessProperty(),
                          winrt::box_value(Thickness{1, 1, 1, 1})));
    setters.Append(Setter(wuxc::Control::CornerRadiusProperty(),
                          winrt::box_value(MakeCorner(EffectiveMenuCorner()))));
    try {
        setters.Append(Setter(wuxc::Control::BackgroundSizingProperty(),
                              winrt::box_value(wuxc::BackgroundSizing::InnerBorderEdge)));
    } catch (...) {}
    setters.Append(Setter(wuxc::Control::PaddingProperty(),
                          winrt::box_value(Thickness{0, 4, 0, 4})));
    setters.Append(Setter(FrameworkElement::MinHeightProperty(), winrt::box_value(0.0)));
    setters.Append(Setter(FrameworkElement::MinWidthProperty(), winrt::box_value(160.0)));
    try {
        setters.Append(Setter(wuxc::Control::ElementSoundModeProperty(),
                              winrt::box_value(ElementSoundMode::Off)));
    } catch (...) {}
    if (auto tmpl = BuildFlyoutShellTemplate(true)) {
        setters.Append(Setter(wuxc::Control::TemplateProperty(), winrt::box_value(tmpl)));
    }
    return style;
}
void ApplyMenuItemLook(wuxc::MenuFlyoutItemBase const& item) {
    try {
        auto hover = MakeBrush(0x12, 0xFF, 0xFF, 0xFF);
        auto pressed = MakeBrush(0x0A, 0xFF, 0xFF, 0xFF);
        auto resources = item.Resources();
        auto set = [&](PCWSTR key, wf::IInspectable const& value) {
            auto boxedKey = winrt::box_value(winrt::hstring(key));
            if (resources.HasKey(boxedKey)) {
                resources.Remove(boxedKey);
            }
            resources.Insert(boxedKey, value);
        };
        set(L"MenuFlyoutItemBackgroundPointerOver", hover);
        set(L"MenuFlyoutItemBackgroundPressed", pressed);
        set(L"MenuFlyoutSubItemBackgroundPointerOver", hover);
        set(L"MenuFlyoutSubItemBackgroundPressed", pressed);
        set(L"MenuFlyoutSubItemBackgroundSubMenuOpened", hover);

        auto themeKillBrush = FlyoutBackgroundBrush();
        auto themeKillBorder = MakeBrush(0, 0, 0, 0);

        set(L"SystemControlTransientBackground", themeKillBrush);
        set(L"SystemControlTransientBackgroundAlt", themeKillBrush);
        set(L"SystemControlTransientBorderBrush", themeKillBorder);
        set(L"SystemControlTransientBorderBrushAlt", themeKillBorder);
        set(L"SystemControlBackgroundAltHighBrush", themeKillBrush);
        set(L"SystemControlBackgroundChromeMediumLowBrush", themeKillBrush);
        set(L"SystemControlBackgroundListLowBrush", themeKillBrush);
        set(L"SystemControlBackgroundListMediumBrush", themeKillBrush);
        set(L"FlyoutBackground", themeKillBrush);
        set(L"FlyoutBorderThemeBrush", themeKillBorder);
        set(L"MenuFlyoutBackground", themeKillBrush);
        set(L"ToolTipBackground", themeKillBrush);
        set(L"ContentDialogBackground", themeKillBrush);
        set(L"ContentDialogTopOverlay", themeKillBrush);
        set(L"ApplicationPageBackgroundThemeBrush", themeKillBrush);
        set(L"SolidBackgroundFillColorBase", themeKillBrush);
        set(L"SolidBackgroundFillColorBaseAlt", themeKillBrush);
        set(L"SolidBackgroundFillColorSecondary", themeKillBrush);
        set(L"SolidBackgroundFillColorTertiary", themeKillBrush);
        set(L"SolidBackgroundFillColorQuarternary", themeKillBrush);
        set(L"LayerFillColorDefaultBrush", themeKillBrush);
        set(L"CardBackgroundFillColorDefaultBrush", themeKillBrush);
        set(L"AcrylicBackgroundFillColorDefaultBrush", themeKillBrush);
        set(L"AcrylicBackgroundFillColorBaseBrush", themeKillBrush);
        set(L"AcrylicBackgroundFillColorDefault", themeKillBrush);
        set(L"AcrylicBackgroundFillColorBase", themeKillBrush);
        set(L"MicaBackgroundFillColorBase", themeKillBrush);
        set(L"MicaBackgroundFillColorBaseAlt", themeKillBrush);
        set(L"MicaBackgroundFillColorSecondary", themeKillBrush);
        set(L"LayerOnMicaBaseAltFillColorDefault", themeKillBrush);
        set(L"LayerOnMicaBaseAltFillColorSecondary", themeKillBrush);
        set(L"LayerOnMicaBaseAltFillColorTertiary", themeKillBrush);
        set(L"LayerOnMicaBaseAltFillColorTransparent", themeKillBrush);
        set(L"SmokeFillColorDefault", themeKillBrush);
        set(L"SmokeFillColorAlt", themeKillBrush);
        set(L"AcrylicInAppFillColorDefaultBrush", themeKillBrush);
        set(L"AcrylicInAppFillColorDefault", themeKillBrush);
        set(L"SystemControlAcrylicWindowBrush", themeKillBrush);
        set(L"SystemControlAcrylicElementBrush", themeKillBrush);
        set(L"SystemControlAcrylicElementMediumBrush", themeKillBrush);
        set(L"SystemControlAcrylicBackground", themeKillBrush);
        set(L"SystemControlAcrylicBackgroundBrush", themeKillBrush);
        set(L"MicaBackgroundFillColorBase", themeKillBrush);
        set(L"MicaBackgroundFillColorBaseAlt", themeKillBrush);
        set(L"MicaBackgroundFillColorSecondary", themeKillBrush);
        set(L"LayerOnMicaBaseAltFillColorDefault", themeKillBrush);
        set(L"LayerOnMicaBaseAltFillColorSecondary", themeKillBrush);
        set(L"LayerOnMicaBaseAltFillColorTertiary", themeKillBrush);
        set(L"LayerOnMicaBaseAltFillColorTransparent", themeKillBrush);
        set(L"SmokeFillColorDefault", themeKillBrush);
        set(L"SmokeFillColorAlt", themeKillBrush);
        set(L"OverlayCornerRadius", winrt::box_value(MakeCorner(EffectiveMenuCorner())));

        if (!g_settings.fontColor.empty()) {
            wui::Color fc{};
            if (TryParseHexColor(g_settings.fontColor, &fc) ||
                TryParseNamedColor(g_settings.fontColor, &fc)) {
                auto fgBrush = MakeBrush(fc.A, fc.R, fc.G, fc.B);
                set(L"MenuFlyoutItemForeground", fgBrush);
                set(L"MenuFlyoutItemForegroundPointerOver", fgBrush);
                set(L"MenuFlyoutItemForegroundPressed", fgBrush);
                set(L"MenuFlyoutItemForegroundDisabled", fgBrush);
                set(L"MenuFlyoutItemForegroundSelected", fgBrush);
                set(L"MenuFlyoutItemForegroundSelectedPointerOver", fgBrush);
                set(L"MenuFlyoutItemForegroundSelectedPressed", fgBrush);
                set(L"MenuFlyoutSubItemForeground", fgBrush);
                set(L"MenuFlyoutSubItemForegroundPointerOver", fgBrush);
                set(L"MenuFlyoutSubItemForegroundPressed", fgBrush);
                set(L"MenuFlyoutSubItemForegroundDisabled", fgBrush);
                set(L"MenuFlyoutSubItemForegroundSelected", fgBrush);
                set(L"MenuFlyoutSubItemForegroundSelectedPointerOver", fgBrush);
                set(L"MenuFlyoutSubItemForegroundSelectedPressed", fgBrush);
            }
        }

        if (auto control = item.try_as<wuxc::Control>()) {
            try { control.ElementSoundMode(ElementSoundMode::Off); } catch (...) {}
            control.CornerRadius(MakeCorner(4.0));
            control.Background(MakeBrush(0, 0, 0, 0));
            control.BorderBrush(MakeBrush(0, 0, 0, 0));
            control.BorderThickness(Thickness{0, 0, 0, 0});
            control.Margin(Thickness{0, 0, 0, 0});
            control.MinHeight(32.0);
            control.Height(34.0);
            control.FontSize(13.5);
            control.FontWeight(winrt::Windows::UI::Text::FontWeights::Normal());
            control.Padding(Thickness{10, 6, 12, 6});
        }

        item.Loaded([](wf::IInspectable const& sender, RoutedEventArgs const&) {
            if (g_settings.fontColor.empty()) return;
            wui::Color fc{};
            if (!TryParseHexColor(g_settings.fontColor, &fc) &&
                !TryParseNamedColor(g_settings.fontColor, &fc)) {
                return;
            }
            auto fgBrush = MakeBrush(fc.A, fc.R, fc.G, fc.B);
            auto fe = sender.as<FrameworkElement>();
            std::function<void(DependencyObject)> paint =
                [&](DependencyObject node) {
                    if (!node) return;
                    try {
                        if (auto tb = node.try_as<wuxc::TextBlock>()) {
                            tb.Foreground(fgBrush);
                        }
                        int n = wuxm::VisualTreeHelper::GetChildrenCount(node);
                        for (int i = 0; i < n; i++) {
                            paint(wuxm::VisualTreeHelper::GetChild(node, i));
                        }
                    } catch (...) {}
                };
            paint(fe);
        });
    } catch (...) {
    }
}

wuxc::MenuFlyoutItem MakeMenuItem(std::wstring_view text, std::function<void()> onClick,
                                  const wchar_t* glyph = nullptr) {
    const bool hasIcon = (glyph && *glyph);
    wuxc::MenuFlyoutItem item;
    item.Text(winrt::hstring(text));
    if (hasIcon) {
        item.Tag(winrt::box_value(winrt::hstring(glyph)));
    }
    try {
        std::wstring ff = g_settings.fontFamily.empty()
            ? L"Segoe UI Variable Text, Segoe UI"
            : g_settings.fontFamily;
        item.FontFamily(wuxm::FontFamily(winrt::hstring(ff)));
    } catch (...) {}
    item.FontWeight(winrt::Windows::UI::Text::FontWeights::Normal());
    if (!g_settings.fontColor.empty()) {
        wui::Color fc{};
        if (TryParseHexColor(g_settings.fontColor, &fc) ||
            TryParseNamedColor(g_settings.fontColor, &fc)) {
            item.Foreground(MakeBrush(fc.A, fc.R, fc.G, fc.B));
        }
    } else {
        item.Foreground(MakeBrush(0xF5, 0xFF, 0xFF, 0xFF));
    }
    ApplyMenuItemLook(item);
    if (auto tpl = GetWinUI3MenuItemTemplate(hasIcon)) {
        try { item.Template(tpl); } catch (...) {}
    }
    if (onClick) {
        item.Click([onClick = std::move(onClick)](auto&&, auto&&) {
            try {
                onClick();
            } catch (...) {
            }
        });
    }
    item.Loaded([](wf::IInspectable const& sender, RoutedEventArgs const&) {
        auto fe = sender.as<FrameworkElement>();
        DependencyObject current = fe;
        while (auto parent = wuxm::VisualTreeHelper::GetParent(current)) {
            if (auto presenter = parent.try_as<wuxc::MenuFlyoutPresenter>()) {
                if (g_menuShellTemplate && presenter.Template() != g_menuShellTemplate) {
                    presenter.Template(g_menuShellTemplate);
                    try { presenter.ApplyTemplate(); } catch (...) {}
                }
                try {
                    DependencyObject popupCur = presenter;
                    for (int i = 0; i < 10 && popupCur; i++) {
                        if (auto popup = popupCur.try_as<wuxc::Primitives::Popup>()) {
                            popup.Transitions(nullptr);
                            break;
                        }
                        popupCur = wuxm::VisualTreeHelper::GetParent(popupCur);
                    }
                } catch (...) {}
                auto isOurBlur = [](wf::IInspectable const& obj) {
                    return obj && obj.try_as<wuxm::XamlCompositionBrushBase>() != nullptr;
                };
                const double menuCorner = EffectiveMenuCorner();
                wuxc::Border shellBorder = FindVisualDescendantBorder(presenter, L"PART_BackgroundBorder");
                if (!shellBorder) {
                    try {
                        if (auto b = presenter.FindName(L"PART_BackgroundBorder").try_as<wuxc::Border>()) {
                            shellBorder = b;
                        }
                    } catch (...) {}
                }
                if (shellBorder) {
                    presenter.Background(MakeBrush(0, 0, 0, 0));
                    if (!isOurBlur(shellBorder.Background())) {
                        shellBorder.Background(CreateWinUI3MenuBlurBrush(presenter.as<UIElement>()));
                    }
                    shellBorder.BorderBrush(MakeBrush(0x1E, 0xFF, 0xFF, 0xFF));
                    shellBorder.BorderThickness(Thickness{1, 1, 1, 1});
                    try { shellBorder.BackgroundSizing(wuxc::BackgroundSizing::InnerBorderEdge); } catch (...) {}
                    shellBorder.CornerRadius(MakeCorner(menuCorner));
                    ApplyRoundedClip(shellBorder.as<FrameworkElement>(), menuCorner);
                } else if (!isOurBlur(presenter.Background())) {
                    presenter.Background(CreateWinUI3MenuBlurBrush(presenter.as<UIElement>()));
                }
                auto presenterRoot = presenter.as<FrameworkElement>();
                ApplyRoundedClip(presenterRoot, menuCorner);
                RegisterDetachedStyleRoot(presenterRoot);
                ApplyControlStylesToPopupRoot(presenterRoot);
                static std::map<void*, ULONGLONG> s_animatedMenuPresenterTicks;
                void* animKey = winrt::get_abi(presenter);
                ULONGLONG nowTick = GetTickCount64();
                auto itTick = s_animatedMenuPresenterTicks.find(animKey);
                if (itTick == s_animatedMenuPresenterTicks.end() || (nowTick - itTick->second) > 150) {
                    if (s_animatedMenuPresenterTicks.size() > 64) s_animatedMenuPresenterTicks.clear();
                    s_animatedMenuPresenterTicks[animKey] = nowTick;
                    try { ApplyFlyoutOpeningAnimation(presenterRoot); } catch (...) {}
                }
                break;
            }
            current = parent;
        }
    });
    return item;
}

