void StyleMenuFlyout(wuxc::MenuFlyout const& menu, Style const& presenterStyle) {
    menu.MenuFlyoutPresenterStyle(presenterStyle ? presenterStyle : MakeMenuPresenterStyle());
    try { menu.AreOpenCloseAnimationsEnabled(false); } catch (...) {}
    menu.Closing([](auto&& sender, auto&&) {
        if (g_settings.flyoutAnimation == L"none") return;
        try {
            wuxc::Primitives::FlyoutBase fb =
                sender.template as<wuxc::Primitives::FlyoutBase>();
            if (!fb) return;
            wuxc::MenuFlyout content = fb.try_as<wuxc::MenuFlyout>();
            if (!content) return;
        } catch (...) {}
    });
    menu.Opening([weakMenu=winrt::make_weak(menu)](auto&&,auto&&){
        if (g_openMenuFlyoutCount.load() <= 0) {
            g_menuPopupSeqFloor.store(g_popupShowSeqCounter.load());
        }
        auto menu=weakMenu.get();if(!menu)return;
        auto bind=[&](auto&& self,wuxc::MenuFlyoutItemBase const& item)->void{
            auto marker=winrt::box_value(L"TopBarImmediateMenuItemStyleHook");
            if(!item.Resources().HasKey(marker)){
                item.Resources().Insert(marker,winrt::box_value(true));
                item.Loaded([weakMenu](auto&& sender,auto&&){
                    DependencyObject node=sender.template as<DependencyObject>();
                    while(node){
                        if(auto presenter=node.try_as<wuxc::MenuFlyoutPresenter>()){
                            auto marker=winrt::box_value(L"TopBarImmediateMenuPresenterStyleHook");
                            if(!presenter.Resources().HasKey(marker)){
                                presenter.Resources().Insert(marker,winrt::box_value(true));
                                auto finishStyles=[weakMenu](wuxc::MenuFlyoutPresenter const& presenter){
                                    auto weakPresenter=winrt::make_weak(presenter);
                                    presenter.Dispatcher().RunAsync(winrt::Windows::UI::Core::CoreDispatcherPriority::High,
                                        [weakMenu,weakPresenter]{
                                            auto menu=weakMenu.get();auto presenter=weakPresenter.get();
                                            if(menu&&menu.IsOpen()&&presenter&&presenter.IsLoaded())StylePopupImmediately(menu,presenter);
                                        });
                                };
                                presenter.Loaded([finishStyles](auto&& sender,auto&&){finishStyles(sender.template as<wuxc::MenuFlyoutPresenter>());});
                                if(presenter.IsLoaded())finishStyles(presenter);
                            }
                            break;
                        }
                        node=wuxm::VisualTreeHelper::GetParent(node);
                    }
                });
            }
            if(auto submenu=item.try_as<wuxc::MenuFlyoutSubItem>())for(auto child:submenu.Items())self(self,child);
        };
        for(auto item:menu.Items())bind(bind,item);
    });
    menu.LightDismissOverlayMode(wuxc::LightDismissOverlayMode::Off);
    menu.ShouldConstrainToRootBounds(false);
    menu.Opened([](auto&& sender, auto&&) {
        g_pendingCloakForFlyout.store(false);
        g_lastMenuOpenedTick.store(GetTickCount64());
        g_openMenuFlyoutCount.fetch_add(1);
        try {
            std::vector<HWND> pending;
            {
                std::lock_guard<std::mutex> lock(g_cloakPendingMutex);
                for (HWND h : g_cloakPendingHwnds) pending.push_back(h);
                g_cloakPendingHwnds.clear();
            }
            for (HWND h : pending) {
                if (IsWindow(h)) {
                    BOOL cloakOff = FALSE;
                    DwmSetWindowAttribute(h, DWMWA_CLOAK, &cloakOff, sizeof(cloakOff));
                }
            }
        } catch (...) {}
        RegisterOpenPopup(sender.template as<wuxc::Primitives::FlyoutBase>());
        auto flyout=sender.template as<wuxc::Primitives::FlyoutBase>();
        StylePopupImmediately(flyout);
        ApplyBlurToAllOpenPopups();
        try {
            auto menu = sender.template as<wuxc::MenuFlyout>();
            if (menu) {
                auto items = menu.Items();
                if (items.Size() > 0) {
                    auto first = items.GetAt(0);
                    if (auto fe = first.template try_as<FrameworkElement>()) {
                        DependencyObject cur = fe;
                        while (auto parent = wuxm::VisualTreeHelper::GetParent(cur)) {
                            if (auto p = parent.try_as<wuxc::MenuFlyoutPresenter>()) {
                                ApplyPresenterBackgroundOverrides(p);
                                try { ApplyFlyoutOpeningAnimation(p.as<FrameworkElement>()); } catch (...) {}
                                break;
                            }
                            cur = parent;
                        }
                    }
                }
            }
        } catch (...) {}
        auto promote = [] {
            try { PromoteChildFlyoutPopups(); } catch (...) {}
        };
        promote();
        RunOnUiThread([promote] {
            promote();
            RunOnUiThread([promote] {
                promote();
                RunOnUiThread([promote] { promote(); });
            });
        });
    });
    menu.Closed([](auto&& sender, auto&&) {
        int prev = g_openMenuFlyoutCount.fetch_sub(1);
        if (prev <= 1) {
            g_openMenuFlyoutCount.store(0);
            g_menuPopupSeqFloor.store(0);
        }
        ForgetImmediateFlyoutStyleRoot(sender.template as<wuxc::Primitives::FlyoutBase>());
        UnregisterOpenPopup(sender.template as<wuxc::Primitives::FlyoutBase>());
        RunOnUiThread([] {
            try {
                if (g_searchFlyout && g_searchFlyout.IsOpen()) {
                    auto it = g_namedElements.find(L"SpotlightSearchBox");
                    if (it != g_namedElements.end()) {
                        if (auto box = it->second.try_as<wuxc::TextBox>()) {
                            try { box.Focus(FocusState::Programmatic); } catch (...) {}
                        }
                    }
                } else if (g_startMenuFlyout && g_startMenuFlyout.IsOpen()) {
                    auto it = g_namedElements.find(L"StartMenuSearchBox");
                    if (it != g_namedElements.end()) {
                        if (auto box = it->second.try_as<wuxc::TextBox>()) {
                            try { box.Focus(FocusState::Programmatic); } catch (...) {}
                        }
                    }
                }
            } catch (...) {}
        });
    });
}

void RunShellCommand(PCWSTR file, PCWSTR parameters, bool hidden) {
    ShellExecute(nullptr, L"open", file, parameters, nullptr,
                 hidden ? SW_HIDE : SW_SHOWNORMAL);
}

void SendWinKeyChord(WORD key) {
    INPUT input[4]{};
    input[0].type = INPUT_KEYBOARD;
    input[0].ki.wVk = VK_LWIN;
    input[1].type = INPUT_KEYBOARD;
    input[1].ki.wVk = key;
    input[2].type = INPUT_KEYBOARD;
    input[2].ki.wVk = key;
    input[2].ki.dwFlags = KEYEVENTF_KEYUP;
    input[3].type = INPUT_KEYBOARD;
    input[3].ki.wVk = VK_LWIN;
    input[3].ki.dwFlags = KEYEVENTF_KEYUP;
    SendInput(ARRAYSIZE(input), input, sizeof(INPUT));
}

void ShowDesktop() {
    if (HWND tray = FindWindow(L"Shell_TrayWnd", nullptr)) {
        PostMessage(tray, WM_COMMAND, 419, 0);
        return;
    }
    SendWinKeyChord('D');
}

void RevealShortcutInExplorer(const std::wstring& lnkPath) {
    if (lnkPath.empty()) return;
    if (lnkPath.rfind(L"shell:", 0) == 0) return;
    PIDLIST_ABSOLUTE pidl = nullptr;
    if (SUCCEEDED(SHParseDisplayName(lnkPath.c_str(), nullptr, &pidl, 0, nullptr)) && pidl) {
        SHOpenFolderAndSelectItems(pidl, 0, nullptr, 0);
        CoTaskMemFree(pidl);
    }
}

// Runs the action configured for the Start menu power button. "menu" is a
// no-op here because that mode keeps the normal power flyout.
void PerformPowerButtonAction(const std::wstring& action) {
    if (action == L"sleep") {
        SuspendSystem();
    } else if (action == L"shutdown") {
        RunShellCommand(L"shutdown.exe", L"/s /t 0", true);
    } else if (action == L"restart") {
        RunShellCommand(L"shutdown.exe", L"/r /t 0", true);
    } else if (action == L"signout") {
        RunShellCommand(L"shutdown.exe", L"/l", true);
    } else if (action == L"lock") {
        LockWorkStation();
    }
}

void LaunchTargetElevated(const std::wstring& target, const std::wstring& args) {
    if (target.empty()) return;
    std::wstring file = target;
    std::wstring parameters = args;
    if (target.find(L'!') != std::wstring::npos &&
        target.find(L'\\') == std::wstring::npos) {
        file = L"shell:AppsFolder\\" + target;
        parameters.clear();
    }
    SHELLEXECUTEINFOW sei{};
    sei.cbSize = sizeof(sei);
    sei.fMask = SEE_MASK_NOASYNC | SEE_MASK_FLAG_NO_UI;
    sei.lpVerb = L"runas";
    sei.lpFile = file.c_str();
    sei.lpParameters = parameters.empty() ? nullptr : parameters.c_str();
    sei.nShow = SW_SHOWNORMAL;
    ShellExecuteExW(&sei);
}

void TryUninstallShortcut(const std::wstring& lnkPath) {
    bool invoked = false;
    if (!lnkPath.empty() && lnkPath.rfind(L"shell:", 0) != 0) {
        SHELLEXECUTEINFOW sei{};
        sei.cbSize = sizeof(sei);
        sei.fMask = SEE_MASK_INVOKEIDLIST | SEE_MASK_FLAG_NO_UI;
        sei.lpVerb = L"Uninstall";
        sei.lpFile = lnkPath.c_str();
        sei.nShow = SW_SHOWNORMAL;
        invoked = ShellExecuteExW(&sei) != FALSE;
    }
    if (!invoked) {
        ShellExecute(nullptr, L"open", L"ms-settings:appsfeatures",
                     nullptr, nullptr, SW_SHOWNORMAL);
    }
}

void SuspendSystem() {
    using SetSuspendState_t = BOOLEAN(WINAPI*)(BOOLEAN, BOOLEAN, BOOLEAN);
    HMODULE module = LoadLibraryEx(L"powrprof.dll", nullptr, LOAD_LIBRARY_SEARCH_SYSTEM32);
    if (!module) {
        return;
    }
    auto setSuspendState =
        reinterpret_cast<SetSuspendState_t>(GetProcAddress(module, "SetSuspendState"));
    if (setSuspendState) {
        setSuspendState(FALSE /* hibernate */, FALSE /* force */, FALSE /* wake events */);
    }
    FreeLibrary(module);
}

void RestartExplorerShell() {
    HWND tray = FindWindow(L"Shell_TrayWnd", nullptr);
    DWORD shellPid = 0;
    if (tray) {
        GetWindowThreadProcessId(tray, &shellPid);
    }

    if (shellPid) {
        HANDLE proc = OpenProcess(PROCESS_TERMINATE, FALSE, shellPid);
        if (proc) {
            TerminateProcess(proc, 0);
            CloseHandle(proc);
        }
    }

    RunInBackground([] {
        for (int i = 0; i < 30; i++) {
            if (WaitForSingleObject(g_stopEvent, 100) == WAIT_OBJECT_0) return;
            if (!FindWindow(L"Shell_TrayWnd", nullptr)) break;
        }
        ShellExecute(nullptr, L"open", L"explorer.exe", nullptr, nullptr, SW_SHOWNORMAL);
    });
}

