std::vector<Result> QueryControlPanel(const std::wstring& q,size_t max) {
    std::vector<Result> out;
    auto tokens=TokenizeQuery(q);
    if(tokens.empty())return out;
    bool overview=IsPointerOverviewQuery(q);
    std::vector<ControlPanelEntry const*> matches;
    for(auto const& item:GetCachedControlPanelItems()){
        auto haystack=ToLowerCopy(item.display+L" "+item.keywords);
        if((overview&&item.display==kPointerOverviewTitle)||AllTokensMatch(tokens,haystack))matches.push_back(&item);
    }
    if(overview)std::stable_sort(matches.begin(),matches.end(),[](auto a,auto b){
        return (a->display==kPointerOverviewTitle)>(b->display==kPointerOverviewTitle);
    });
    for(auto const* item:matches){
        if(out.size()>=max)break;
        Result entry;
        entry.kind=Result::Kind::ControlPanel;
        entry.title=item->display;
        entry.subtitle=L"Control Panel";
        entry.target=item->path;
        entry.lnkPath=item->path;
        entry.args=item->arguments;
        out.push_back(std::move(entry));
    }
    return out;
}

std::vector<Result> QueryAll(const std::wstring& q, size_t max) {
    std::vector<Result> out;
    if (q.empty()) return out;
    auto apps = QueryApps(q, max);
    auto settings = QuerySettings(q, max);
    auto controlPanel = QueryControlPanel(q, max);
    auto files = QueryFiles(q, max);

    out.reserve(settings.size() + controlPanel.size() + apps.size() + files.size());
    for (auto& r : settings)     { if (!r.title.empty()) out.push_back(std::move(r)); }
    for (auto& r : controlPanel) { if (!r.title.empty()) out.push_back(std::move(r)); }
    for (auto& r : apps)         { if (!r.title.empty()) out.push_back(std::move(r)); }
    for (auto& r : files)        { if (!r.title.empty()) out.push_back(std::move(r)); }

    if (out.size() > max) out.resize(max);
    return out;
}

void Launch(const Result& r) {
    try {
        switch (r.kind) {
            case Result::Kind::App:
                ShellExecute(nullptr, L"open", r.target.c_str(),
                             r.args.empty() ? nullptr : r.args.c_str(),
                             nullptr, SW_SHOWNORMAL);
                break;
            case Result::Kind::File:
                ShellExecute(nullptr, L"open", r.target.c_str(),
                             nullptr, nullptr, SW_SHOWNORMAL);
                break;
            case Result::Kind::Setting:
                ShellExecute(nullptr, L"open", r.target.c_str(),
                             nullptr, nullptr, SW_SHOWNORMAL);
                break;
            case Result::Kind::ControlPanel:
                {
                    if (!r.args.empty()) ShellExecuteW(nullptr, L"open", r.target.c_str(), r.args.c_str(), nullptr, SW_SHOWNORMAL);
                    else if(r.target.size()>=4&&_wcsicmp(r.target.c_str()+r.target.size()-4,L".cpl")==0)
                        ShellExecuteW(nullptr,L"open",L"control.exe",r.target.c_str(),nullptr,SW_SHOWNORMAL);
                    else ShellExecuteW(nullptr,L"open",r.target.c_str(),nullptr,nullptr,SW_SHOWNORMAL);
                }
                break;
        }
    } catch (...) {}
}

