// Every top bar button that opens a flyout (or a window) on a plain left click.
// Their screen bounds are cached next to Start/Search so the low level mouse
// hook can recognise a press on them and act on it immediately, instead of
// relying on XAML Islands to route (and sometimes swallow) the click.
static const PCWSTR kTopBarFlyoutButtons[] = {
    L"DisplayButton", L"SoundButton", L"WifiButton", L"BluetoothButton",
    L"BatteryButton", L"ControlCenterButton", L"NetworkButton",
    L"SpeedTestButton", L"OptimizerButton", L"WallpaperButton", L"RecycleBinButton",
    L"TrayIconButton", L"MediaButton", L"NotificationsButton",
    L"WeatherButton", L"ClockButton", L"VirtualDesktopButton",
    L"ResourceCpuButton", L"ResourceRamButton", L"ResourceGpuButton", L"ResourceDiskButton",
    L"SettingsButton", L"TaskOverflowButton",
};
static constexpr int kTopBarFlyoutButtonCount =
    static_cast<int>(sizeof(kTopBarFlyoutButtons) / sizeof(kTopBarFlyoutButtons[0]));
static RECT g_topBarFlyoutButtonRects[kTopBarFlyoutButtonCount]{};
static RECT g_mediaSubButtonRects[3]{};
static std::atomic<bool> g_topBarMenuMouseConsumed{false};
static std::atomic<ULONGLONG> g_topBarMenuMouseTick{0};
