void ShowStartContextMenuAt(FrameworkElement const& anchor) {
    if (!anchor) return;
    static ULONGLONG s_lastShownTick = 0;
    ULONGLONG now = GetTickCount64();
    if (now - s_lastShownTick < 140) return;
    s_lastShownTick = now;

    CloseAnyOpenChildFlyout();
    try { EnsureTopBarHasKeyboardFocus(true); } catch (...) {}
    try { BuildStartContextMenu(); } catch (...) {}
    if (!g_startContextMenu) return;
    try {
        wuxc::Primitives::FlyoutShowOptions opts;
        opts.Placement(wuxc::Primitives::FlyoutPlacementMode::BottomEdgeAlignedLeft);
        g_startContextMenu.ShowAt(anchor, opts);
    } catch (...) {
        try { g_startContextMenu.ShowAt(anchor); } catch (...) {}
    }
}

void OpenFileLocationForApp(HWND hwnd) {
    if (!IsWindow(hwnd)) return;

    DWORD pid = GetRealAppPid(hwnd);
    if (!pid) return;

    HANDLE process = OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, FALSE, pid);
    if (!process) return;

    wchar_t path[MAX_PATH]{};
    DWORD size = ARRAYSIZE(path);
    bool ok = QueryFullProcessImageNameW(process, 0, path, &size) != FALSE;
    CloseHandle(process);
    if (!ok || !path[0]) return;

    PIDLIST_ABSOLUTE pidl = nullptr;
    if (SUCCEEDED(SHParseDisplayName(path, nullptr, &pidl, 0, nullptr)) && pidl) {
        SHOpenFolderAndSelectItems(pidl, 0, nullptr, 0);
        CoTaskMemFree(pidl);
        return;
    }

    std::wstring folder = path;
    size_t slash = folder.find_last_of(L"\\/");
    if (slash != std::wstring::npos) folder.resize(slash);
    ShellExecute(nullptr, L"open", folder.c_str(), nullptr, nullptr, SW_SHOWNORMAL);
}

void ShowFilePropertiesForApp(HWND hwnd) {
    if (!IsWindow(hwnd)) return;

    DWORD pid = GetRealAppPid(hwnd);
    if (!pid) return;

    HANDLE process = OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, FALSE, pid);
    if (!process) return;

    wchar_t path[MAX_PATH]{};
    DWORD size = ARRAYSIZE(path);
    bool ok = QueryFullProcessImageNameW(process, 0, path, &size) != FALSE;
    CloseHandle(process);
    if (!ok || !path[0]) return;

    SHELLEXECUTEINFOW sei{};
    sei.cbSize = sizeof(sei);
    sei.fMask = SEE_MASK_INVOKEIDLIST | SEE_MASK_FLAG_NO_UI;
    sei.lpVerb = L"properties";
    sei.lpFile = path;
    sei.nShow = SW_SHOW;
    ShellExecuteExW(&sei);
}

