void AttachWheelHandler(wuxc::Button const& button, bool isVolume) {
    button.PointerWheelChanged(
        [isVolume](wf::IInspectable const& sender, Input::PointerRoutedEventArgs const& args) {
            try {
                auto point = args.GetCurrentPoint(sender.as<UIElement>());
                int delta = point.Properties().MouseWheelDelta();
                if (delta == 0) return;

                int step = isVolume ? 6 : 4;
                int direction = delta > 0 ? 1 : -1;

                if (isVolume) {
                    int newVolume = std::clamp(audio::GetMasterVolume() + step * direction, 0, 100);
                    SetMasterVolumeCoalesced(newVolume);
                    ShowVolumePercent(newVolume);

                    if (!g_volumeRevertTimer) {
                        g_volumeRevertTimer = DispatcherTimer();
                        g_volumeRevertTimer.Interval(std::chrono::milliseconds(700));
                        g_volumeRevertTimer.Tick([](wf::IInspectable const&, wf::IInspectable const&) {
                            g_volumeRevertTimer.Stop();
                            RefreshSoundButtonIcon();
                        });
                    }
                    g_volumeRevertTimer.Stop();
                    g_volumeRevertTimer.Start();
                } else {
                    int newBrightness = std::clamp(brightness::GetFast() + step * direction, 0, 100);
                    SetBrightnessCoalesced(newBrightness);
                    ShowBrightnessPercent(newBrightness);

                    if (!g_brightnessRevertTimer) {
                        g_brightnessRevertTimer = DispatcherTimer();
                        g_brightnessRevertTimer.Interval(std::chrono::milliseconds(700));
                        g_brightnessRevertTimer.Tick([](wf::IInspectable const&, wf::IInspectable const&) {
                            g_brightnessRevertTimer.Stop();
                            RefreshDisplayButtonIcon();
                        });
                    }
                    g_brightnessRevertTimer.Stop();
                    g_brightnessRevertTimer.Start();
                }

                args.Handled(true);
            } catch (...) {}
        });
}

wuxc::Button MakeControlButton(PCWSTR name,
                               FrameworkElement icon,
                               wuxc::Flyout const& flyout,
                               const std::function<void()>& onOpening) {
    auto button = MakeGhostButton(name, EffectiveControlCorner());
    button.Content(icon);
    button.VerticalAlignment(VerticalAlignment::Stretch);
    button.Margin(Thickness{5, 4, 5, 4});
    button.Padding(Thickness{7, 0, 7, 0});
    button.HorizontalContentAlignment(HorizontalAlignment::Center);
    if (flyout) {
        button.Flyout(flyout);
        if (onOpening) {
            auto weakFlyout = winrt::make_weak(flyout);
            flyout.Opening([onOpening, weakFlyout](auto&&, auto&&) {
                try {
                    onOpening();
                    if (auto f = weakFlyout.get()) {
                        if (auto root = f.Content().try_as<FrameworkElement>()) {
                            ApplyControlStylesToPopupRoot(root);
                        }
                    }
                } catch (...) {
                }
            });
        }
    }
    AttachTopBarPressAnimation(button, 0.88f);
    RegisterNamed(name, button);
    return button;
}
std::wstring ReadTrayOrder() {
    std::vector<wchar_t> buffer(1024);
    size_t length = Wh_GetStringValue(L"trayOrder", buffer.data(), buffer.size());
    return std::wstring(buffer.data(), length);
}


std::vector<std::wstring> SplitItemList(const std::wstring& csv);
static void InsertCanonical(std::wstring& csv, const std::wstring& item);

static const std::vector<std::vector<std::wstring>> kAtomicGroups = {
    { L"StartButton", L"SearchButton" },
    { L"DisplayButton", L"WifiButton", L"SoundButton", L"BluetoothButton", L"RecycleBinButton" },
};

static int FindAtomicGroupOf(const std::wstring& item) {
    for (size_t gi = 0; gi < kAtomicGroups.size(); gi++) {
        for (const auto& m : kAtomicGroups[gi]) {
            if (m == item) return static_cast<int>(gi);
        }
    }
    return -1;
}

static const wchar_t* GetPanelOfItem(const std::wstring& item) {
    auto contains = [&](const std::wstring& csv) {
        auto v = SplitItemList(csv);
        return std::find(v.begin(), v.end(), item) != v.end();
    };
    if (contains(g_settings.leftItems))   return L"left";
    if (contains(g_settings.centerItems)) return L"center";
    if (contains(g_settings.rightItems))  return L"right";
    return nullptr;
}

void MoveItemWithinPanels(const std::wstring& item, int direction) {
    const wchar_t* panelName = GetPanelOfItem(item);
    if (!panelName) return;

    std::wstring* csv = nullptr;
    if (wcscmp(panelName, L"left") == 0)        csv = &g_settings.leftItems;
    else if (wcscmp(panelName, L"center") == 0) csv = &g_settings.centerItems;
    else if (wcscmp(panelName, L"right") == 0)  csv = &g_settings.rightItems;
    if (!csv) return;

    auto list = SplitItemList(*csv);
    auto it = std::find(list.begin(), list.end(), item);
    if (it == list.end()) return;
    int idx = static_cast<int>(it - list.begin());
    int n   = static_cast<int>(list.size());

    int myGroup = FindAtomicGroupOf(item);

    if (myGroup >= 0) {
        int target = idx + direction;
        if (target < 0 || target >= n) return;
        if (FindAtomicGroupOf(list[target]) != myGroup) return;
        std::swap(list[idx], list[target]);
    } else {
        if (direction < 0) {
            if (idx == 0) return;
            int target = idx - 1;
            while (target >= 0) {
                int g = FindAtomicGroupOf(list[target]);
                if (g < 0) break;
                while (target >= 0 && FindAtomicGroupOf(list[target]) == g) target--;
            }
            if (target < 0) target = 0;
            if (target >= idx) return;
            std::wstring moved = list[idx];
            for (int k = idx; k > target; k--) list[k] = list[k - 1];
            list[target] = moved;
        } else {
            if (idx == n - 1) return;
            int target = idx + 1;
            while (target < n) {
                int g = FindAtomicGroupOf(list[target]);
                if (g < 0) break;
                while (target < n && FindAtomicGroupOf(list[target]) == g) target++;
            }
            if (target >= n) target = n - 1;
            if (target <= idx) return;
            std::wstring moved = list[idx];
            for (int k = idx; k < target; k++) list[k] = list[k + 1];
            list[target] = moved;
        }
    }

    std::wstring out;
    for (int i = 0; i < n; i++) { if (i) out += L","; out += list[i]; }
    *csv = out;

    Wh_SetStringValue(L"leftItems",   g_settings.leftItems.c_str());
    Wh_SetStringValue(L"centerItems", g_settings.centerItems.c_str());
    Wh_SetStringValue(L"rightItems",  g_settings.rightItems.c_str());

    RunOnUiThread([] {
        if (!g_topBarHwnd) return;
        LoadSettings();
        g_dpiScale = g_settings.topBarScale / 100.0;
        g_barHeightPx = static_cast<int>(g_settings.barHeightDip * g_dpiScale + 0.5);
        SetTopBarContent(BuildTopBarContent());
        BuildStartContextMenu();
        BuildTaskContextMenu();
        ApplyAllControlStyles();
        try { if (g_rootElement) g_rootElement.UpdateLayout(); } catch (...) {}
        ApplyVisibilitySettings();
        UpdateResourceButton();
        StripInheritedIslandBackgrounds();
        PositionAppBar(g_topBarHwnd, g_barHeightPx);
        RefreshTaskList(true);
    });
}

void AttachTrayReorderMenu(wuxc::Button const& button, std::wstring name) {
    button.RightTapped([name](wf::IInspectable const& sender,
                              Input::RightTappedRoutedEventArgs const& args) {
        try {
            auto fe = sender.as<FrameworkElement>();
            // Guard against XAML routing a focus/light-dismiss right-click to
            // a left-side button when the user is actually right-clicking
            // elsewhere on the TopBar rapidly. Require the actual cursor and
            // event position to lie inside this button's own bounds.
            double aw = fe.ActualWidth();
            double ah = fe.ActualHeight();
            if (aw <= 1.0 || ah <= 1.0) return;
            auto localPt = args.GetPosition(fe);
            if (localPt.X < -2.0f || localPt.Y < -2.0f ||
                localPt.X > static_cast<float>(aw) + 2.0f ||
                localPt.Y > static_cast<float>(ah) + 2.0f) {
                return;
            }
            if (g_topBarPopupHwnd && IsWindow(g_topBarPopupHwnd)) {
                POINT cur{};
                RECT popup{};
                if (GetCursorPos(&cur) && GetWindowRect(g_topBarPopupHwnd, &popup)) {
                    double dpi = GetBarDpiScale();
                    if (!std::isfinite(dpi) || dpi <= 0.0) dpi = 1.0;
                    auto tf = fe.TransformToVisual(nullptr);
                    auto tl = tf.TransformPoint({0.0f, 0.0f});
                    auto br = tf.TransformPoint({static_cast<float>(aw), static_cast<float>(ah)});
                    RECT btnScreen{
                        popup.left + static_cast<LONG>(std::floor(tl.X * dpi)) - 2,
                        popup.top - 2,
                        popup.left + static_cast<LONG>(std::ceil(br.X * dpi)) + 2,
                        popup.bottom + 2
                    };
                    if (!PtInRect(&btnScreen, cur)) {
                        return;
                    }
                }
            }
            args.Handled(true);

            auto makeBtn = [](bool isLeft) {
                auto b = MakeGhostButton(nullptr, 4);
                b.MinWidth(104);
                b.Padding(Thickness{ 12, 7, 12, 7 });
                b.HorizontalAlignment(HorizontalAlignment::Stretch);
                b.HorizontalContentAlignment(HorizontalAlignment::Center);
                b.Background(MakeBrush(0x30, 0xFF, 0xFF, 0xFF));

                wuxc::StackPanel c;
                c.Orientation(wuxc::Orientation::Horizontal);
                c.Spacing(8);
                c.VerticalAlignment(VerticalAlignment::Center);
                c.HorizontalAlignment(HorizontalAlignment::Center);

                if (isLeft) {
                    wuxc::FontIcon fi; fi.Glyph(L"\uE76B"); fi.FontSize(14);
                    fi.Foreground(FontColorBrush());
                    c.Children().Append(fi);
                }
                auto t = MakeText(nullptr, isLeft ? L"Left" : L"Right", 13);
                t.Foreground(FontColorBrush());
                c.Children().Append(t);
                if (!isLeft) {
                    wuxc::FontIcon fi; fi.Glyph(L"\uE76C"); fi.FontSize(14);
                    fi.Foreground(FontColorBrush());
                    c.Children().Append(fi);
                }
                b.Content(c);
                return b;
            };

            auto leftBtn = makeBtn(true);
            auto rightBtn = makeBtn(false);

            auto rowGrid = wuxc::Grid();
            wuxc::ColumnDefinition c1; c1.Width(GridLength{ 1, GridUnitType::Star });
            wuxc::ColumnDefinition c2; c2.Width(GridLength{ 1, GridUnitType::Star });
            rowGrid.ColumnDefinitions().Append(c1);
            rowGrid.ColumnDefinitions().Append(c2);
            rowGrid.ColumnSpacing(6);
            wuxc::Grid::SetColumn(leftBtn, 0);
            wuxc::Grid::SetColumn(rightBtn, 1);
            rowGrid.Children().Append(leftBtn);
            rowGrid.Children().Append(rightBtn);

            // Second row: Left / Center / Right panel switcher with active panel indicator
            std::wstring currentPanel = FindSectionOf(name);
            auto panelGrid = wuxc::Grid();
            panelGrid.ColumnSpacing(6);
            for (int i = 0; i < 3; ++i) {
                wuxc::ColumnDefinition pc;
                pc.Width(GridLength{ 1, GridUnitType::Star });
                panelGrid.ColumnDefinitions().Append(pc);
            }
            const wchar_t* pLabels[3] = { L"Left", L"Center", L"Right" };
            const wchar_t* pIds[3]    = { L"left", L"center", L"right" };
            wuxc::Button panelBtns[3]{ nullptr, nullptr, nullptr };
            wui::Color accent = GetSystemAccentColor();
            for (int i = 0; i < 3; ++i) {
                bool isCurrent = (currentPanel == pIds[i]);
                auto pb = MakeGhostButton(nullptr, 4);
                pb.MinWidth(68);
                pb.Padding(Thickness{ 9, 6, 9, 6 });
                pb.HorizontalAlignment(HorizontalAlignment::Stretch);
                pb.HorizontalContentAlignment(HorizontalAlignment::Center);
                auto bgBrush = isCurrent
                    ? MakeBrush(0xFF, accent.R, accent.G, accent.B)
                    : MakeBrush(0x26, 0xFF, 0xFF, 0xFF);
                auto noBorder = MakeBrush(0, 0, 0, 0);
                pb.Background(bgBrush);
                pb.BorderBrush(noBorder);
                pb.BorderThickness(Thickness{ 0, 0, 0, 0 });
                try {
                    auto res = pb.Resources();
                    res.Insert(winrt::box_value(winrt::hstring(L"ButtonBackground")), bgBrush);
                    res.Insert(winrt::box_value(winrt::hstring(L"ButtonBorderBrush")), noBorder);
                    res.Insert(winrt::box_value(winrt::hstring(L"ButtonBorderBrushPointerOver")), noBorder);
                    res.Insert(winrt::box_value(winrt::hstring(L"ButtonBorderBrushPressed")), noBorder);
                } catch (...) {}
                auto pt = MakeText(nullptr, pLabels[i], 12, isCurrent);
                pt.Foreground(FontColorBrush());
                pb.Content(pt);
                wuxc::Grid::SetColumn(pb, i);
                panelGrid.Children().Append(pb);
                panelBtns[i] = pb;
            }

            wuxc::StackPanel menuStack;
            menuStack.Orientation(wuxc::Orientation::Vertical);
            menuStack.Spacing(5);
            menuStack.Children().Append(rowGrid);
            menuStack.Children().Append(panelGrid);

            const double reorderCorner = EffectiveFlyoutCorner();
            auto wrap = wuxc::Border();
            wrap.Name(L"FlyoutBlurHost");
            wrap.BorderBrush(MakeBrush(0x28, 0xFF, 0xFF, 0xFF));
            wrap.BorderThickness(Thickness{ 1, 1, 1, 1 });
            wrap.CornerRadius(MakeCorner(reorderCorner));
            wrap.Padding(Thickness{ 6, 6, 6, 6 });
            wrap.Background(CreateGlobalBlurBrush(wrap.as<UIElement>()));
            wrap.Child(menuStack);
            ApplyRoundedClip(wrap.as<FrameworkElement>(), reorderCorner);

            auto flyout = wuxc::Flyout();
            flyout.Content(wrap);
            flyout.ShouldConstrainToRootBounds(false);
            flyout.Opened([](auto&& sender, auto&&) {
                RegisterOpenPopup(sender.template as<wuxc::Primitives::FlyoutBase>());
            });
            flyout.Closed([](auto&& sender, auto&&) {
                UnregisterOpenPopup(sender.template as<wuxc::Primitives::FlyoutBase>());
            });
            {
                Style fpStyle(winrt::xaml_typename<wuxc::FlyoutPresenter>());
                fpStyle.Setters().Append(Setter(wuxc::Control::BackgroundProperty(),
                    winrt::box_value(MakeBrush(0x00, 0, 0, 0))));
                fpStyle.Setters().Append(Setter(wuxc::Control::BorderThicknessProperty(),
                    winrt::box_value(Thickness{ 0, 0, 0, 0 })));
                fpStyle.Setters().Append(Setter(wuxc::Control::PaddingProperty(),
                    winrt::box_value(Thickness{ 0, 0, 0, 0 })));
                if (auto tmpl = BuildFlyoutShellTemplate(false)) {
                    fpStyle.Setters().Append(Setter(wuxc::Control::TemplateProperty(),
                        winrt::box_value(tmpl)));
                }
                flyout.FlyoutPresenterStyle(fpStyle);
            }
            {
                auto wrapRef = wrap;
                flyout.Opened([wrapRef](auto&&, auto&&) {
                    try {
                        ApplyFlyoutBlurBrush(wrapRef);
                        ApplyControlStylesToPopupRoot(wrapRef.as<FrameworkElement>());
                    } catch (...) {}
                    ApplyBlurToAllOpenPopups();
                });
            }

            auto flyoutRef = std::make_shared<wuxc::Flyout>(flyout);
            leftBtn.Click([name, flyoutRef](auto&&, auto&&) {
                MoveItemWithinPanels(name, -1);
                try { flyoutRef->Hide(); } catch (...) {}
            });
            rightBtn.Click([name, flyoutRef](auto&&, auto&&) {
                MoveItemWithinPanels(name, +1);
                try { flyoutRef->Hide(); } catch (...) {}
            });
            for (int i = 0; i < 3; ++i) {
                std::wstring targetSection = pIds[i];
                panelBtns[i].Click([name, targetSection, flyoutRef](auto&&, auto&&) {
                    int grp = FindAtomicGroupOf(name);
                    if (grp >= 0 && grp < static_cast<int>(kAtomicGroups.size())) {
                        for (const auto& m : kAtomicGroups[grp]) {
                            MoveItemToSection(m, targetSection);
                        }
                    } else {
                        MoveItemToSection(name, targetSection);
                    }
                    try { flyoutRef->Hide(); } catch (...) {}
                    RunOnUiThread([] {
                        if (!g_topBarHwnd) return;
                        LoadSettings();
                        g_dpiScale = g_settings.topBarScale / 100.0;
                        g_barHeightPx = static_cast<int>(g_settings.barHeightDip * g_dpiScale + 0.5);
                        SetTopBarContent(BuildTopBarContent());
                        BuildStartContextMenu();
                        BuildTaskContextMenu();
                        ApplyAllControlStyles();
                        try { if (g_rootElement) g_rootElement.UpdateLayout(); } catch (...) {}
                        ApplyVisibilitySettings();
                        UpdateResourceButton();
                        StripInheritedIslandBackgrounds();
                        PositionAppBar(g_topBarHwnd, g_barHeightPx);
                        RefreshTaskList(true);
                    });
                });
            }

            CloseAnyOpenChildFlyout();
            flyout.Placement(wuxc::Primitives::FlyoutPlacementMode::Bottom);
            try { flyout.ElementSoundMode(ElementSoundMode::Off); } catch (...) {}
            flyout.ShowAt(fe);

            for (int delayMs : { 30, 90, 200 }) {
                RunInBackground([delayMs] {
                    if (WaitForSingleObject(g_stopEvent, delayMs) == WAIT_OBJECT_0) return;
                    RunOnUiThread([] {
                        try { PromoteChildFlyoutPopups(); } catch (...) {}
                    });
                });
            }
        } catch (...) {
        }
    });
}

void EnsureAutoRefreshTimers() {
    if (!g_wifiAutoRefreshTimer) {
        g_wifiAutoRefreshTimer = DispatcherTimer();
        g_wifiAutoRefreshTimer.Interval(std::chrono::seconds(4));
        g_wifiAutoRefreshTimer.Tick([](wf::IInspectable const&, wf::IInspectable const&) {
            const bool wifiInCC = (g_controlCenterFlyout && g_controlCenterFlyout.IsOpen() &&
                                   g_ccNav.activeSubView == L"wifi");
            if (!(g_wifiFlyout && g_wifiFlyout.IsOpen()) && !wifiInCC) {
                g_wifiAutoRefreshTimer.Stop();
                return;
            }
            if (g_wifiPasswordPrompt || !g_wifiConnectingSSID.empty() ||
                !g_wifiDisconnectingSSID.empty()) {
                return;
            }
            const ULONGLONG now = GetTickCount64();
            if (!g_wifiScanning.load() &&
                (g_wifiLastScanTick.load() == 0 || now - g_wifiLastScanTick.load() >= 16000)) {
                StartWifiScan();
            } else {
                SyncWifiStateFast();
            }
        });
    }
    if (!g_bluetoothAutoRefreshTimer) {
        g_bluetoothAutoRefreshTimer = DispatcherTimer();
        g_bluetoothAutoRefreshTimer.Interval(std::chrono::seconds(3));
        g_bluetoothAutoRefreshTimer.Tick([](wf::IInspectable const&, wf::IInspectable const&) {
            const bool btInCC = (g_controlCenterFlyout && g_controlCenterFlyout.IsOpen() &&
                                 g_ccNav.activeSubView == L"bluetooth");
            if (!(g_bluetoothFlyout && g_bluetoothFlyout.IsOpen()) && !btInCC) {
                g_bluetoothAutoRefreshTimer.Stop();
                return;
            }
            SyncBluetoothStateFast();
        });
    }
}

std::vector<std::wstring> SplitItemList(const std::wstring& csv) {
    std::vector<std::wstring> out;
    size_t pos = 0;
    while (pos <= csv.size()) {
        size_t comma = csv.find(L',', pos);
        std::wstring token = TrimWs(csv.substr(
            pos, comma == std::wstring::npos ? std::wstring::npos : comma - pos));
        if (!token.empty()) out.push_back(token);
        if (comma == std::wstring::npos) break;
        pos = comma + 1;
    }
    return out;
}

void RemoveItemFromAll(std::wstring& csv, const std::wstring& item) {
    auto items = SplitItemList(csv);
    std::wstring result;
    for (auto& s : items) {
        if (s == item) continue;
        if (!result.empty()) result += L",";
        result += s;
    }
    csv = result;
}

std::wstring FindSectionOf(const std::wstring& item) {
    auto has = [](const std::wstring& csv, const std::wstring& it) {
        auto v = SplitItemList(csv);
        return std::find(v.begin(), v.end(), it) != v.end();
    };
    if (has(g_settings.leftItems, item))   return L"left";
    if (has(g_settings.centerItems, item)) return L"center";
    if (has(g_settings.rightItems, item))  return L"right";
    return L"";
}


static int CanonicalItemRank(const std::wstring& item) {
    static const wchar_t* kOrder[] = {
        L"StartButton", L"SearchButton", L"VirtualDesktopButton", L"AppTitleButton", L"TaskListPanel",
        L"ResourceButton", L"WeatherButton", L"MediaButton", L"NetworkButton", L"SpeedTestButton", L"OptimizerButton", L"SettingsButton",
        L"TrayIconButton", L"WallpaperButton",
        L"DisplayButton", L"WifiButton", L"SoundButton", L"BluetoothButton", L"RecycleBinButton",
        L"BatteryButton", L"NotificationsButton",
        L"ControlCenterButton", L"ClockButton",
    };
    for (size_t i = 0; i < ARRAYSIZE(kOrder); i++) {
        if (item == kOrder[i]) return static_cast<int>(i);
    }
    return 1000;
}

static void InsertCanonical(std::wstring& csv, const std::wstring& item) {
    auto list = SplitItemList(csv);
    int rank = CanonicalItemRank(item);
    size_t pos = list.size();
    for (size_t i = 0; i < list.size(); i++) {
        if (CanonicalItemRank(list[i]) > rank) { pos = i; break; }
    }
    list.insert(list.begin() + pos, item);
    std::wstring out;
    for (size_t i = 0; i < list.size(); i++) {
        if (i) out += L",";
        out += list[i];
    }
    csv = out;
}

void MoveItemToSection(const std::wstring& item, const std::wstring& section) {
    std::vector<std::wstring> toMove;
    int grp = FindAtomicGroupOf(item);
    if (grp >= 0 && grp < static_cast<int>(kAtomicGroups.size())) {
        // Move the entire locked group together (e.g. Control Buttons)
        toMove = kAtomicGroups[grp];
    } else {
        toMove.push_back(item);
        if (item == L"AppTitleButton") toMove.push_back(L"TaskListPanel");
        else if (item == L"TaskListPanel") toMove.push_back(L"AppTitleButton");
    }

    for (const auto& m : toMove) {
        RemoveItemFromAll(g_settings.leftItems, m);
        RemoveItemFromAll(g_settings.centerItems, m);
        RemoveItemFromAll(g_settings.rightItems, m);
    }
    for (const auto& m : toMove) {
        if (section == L"left") {
            InsertCanonical(g_settings.leftItems, m);
        } else if (section == L"center") {
            InsertCanonical(g_settings.centerItems, m);
        } else if (section == L"right") {
            InsertCanonical(g_settings.rightItems, m);
        }
    }
    Wh_SetStringValue(L"leftItems", g_settings.leftItems.c_str());
    Wh_SetStringValue(L"centerItems", g_settings.centerItems.c_str());
    Wh_SetStringValue(L"rightItems", g_settings.rightItems.c_str());
}

void InvalidateStartAndSearchFlyouts() {
    ++g_searchPopupEpoch;
    g_searchPopupPrimed = false;
    g_searchPopupPriming = false;
    g_searchPopupPrimeAttempted = false;
    g_searchOpenPendingAfterPrime = false;
    g_searchPopupPositionSettleUntil = 0;
    try { if (g_searchPopupPrimeTimer) g_searchPopupPrimeTimer.Stop(); } catch (...) {}
    g_searchPopupPrimePollTicks = 0;
    g_searchPopupPrimeStableTicks = 0;
    ++g_searchRenderGeneration;
    g_searchToken.fetch_add(1);
    if (g_searchQueryTimer) g_searchQueryTimer.Stop();
    if (g_searchDebounceTimer) g_searchDebounceTimer.Stop();
    StopSearchHeightAnimation();
    if (g_startMenuFlyout) {
        try { if (g_startMenuFlyout.IsOpen()) g_startMenuFlyout.Hide(); } catch (...) {}
        try { UnregisterOpenPopup(g_startMenuFlyout); } catch (...) {}
        g_startMenuFlyout = nullptr;
    }
    if (g_searchFlyout) {
        try { if (g_searchFlyout.IsOpen()) g_searchFlyout.Hide(); } catch (...) {}
        try { UnregisterOpenPopup(g_searchFlyout); } catch (...) {}
        g_searchFlyout = nullptr;
    }
    if (g_startPowerMenu)   { try { g_startPowerMenu.Hide();   } catch (...) {} g_startPowerMenu = nullptr; }
    if (g_startAccountFlyout){try { g_startAccountFlyout.Hide();}catch (...) {} g_startAccountFlyout = nullptr; }
    if (g_startTileMenu)    { try { g_startTileMenu.Hide();    } catch (...) {} g_startTileMenu = nullptr; }
    if (g_searchResultMenu) { try { g_searchResultMenu.Hide(); } catch (...) {} g_searchResultMenu = nullptr; }

    for (const auto& name : { L"StartMenuSearchBox", L"SpotlightSearchBox",
                              L"StartMenuPowerButton", L"StartMenuAccountButton",
                              L"SearchBlurHost", L"SearchResultsPanel" }) {
        g_namedElements.erase(name);
    }
    g_searchResultsPanel = nullptr;
    g_searchQuery.clear();
    g_searchResults.clear();
    g_searchKeyboardActive = false;
    g_startMenuKeyboardActive = false;
}

std::wstring ShortcutVkToName(DWORD vk) {
    if (vk >= 'A' && vk <= 'Z') return std::wstring(1, (wchar_t)vk);
    if (vk >= '0' && vk <= '9') return std::wstring(1, (wchar_t)vk);
    if (vk >= VK_F1 && vk <= VK_F12) {
        wchar_t buf[8];
        swprintf_s(buf, L"F%d", (int)(vk - VK_F1 + 1));
        return buf;
    }
    switch (vk) {
        case VK_SPACE: return L"Space";
        case VK_RETURN: return L"Enter";
        case VK_TAB: return L"Tab";
        case VK_ESCAPE: return L"Escape";
        case VK_BACK: return L"Backspace";
        case VK_DELETE: return L"Delete";
        case VK_INSERT: return L"Insert";
        case VK_HOME: return L"Home";
        case VK_END: return L"End";
        case VK_PRIOR: return L"PageUp";
        case VK_NEXT: return L"PageDown";
        case VK_LEFT: return L"Left";
        case VK_RIGHT: return L"Right";
        case VK_UP: return L"Up";
        case VK_DOWN: return L"Down";
        case VK_OEM_1: return L";";
        case VK_OEM_2: return L"/";
        case VK_OEM_3: return L"`";
        case VK_OEM_4: return L"[";
        case VK_OEM_5: return L"\\";
        case VK_OEM_6: return L"]";
        case VK_OEM_7: return L"'";
        case VK_OEM_COMMA: return L",";
        case VK_OEM_PERIOD: return L".";
        case VK_OEM_MINUS: return L"-";
        case VK_OEM_PLUS: return L"=";
    }
    return L"";
}

DWORD ShortcutNameToVk(const std::wstring& name) {
    if (name.size() == 1) {
        wchar_t c = name[0];
        if ((c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9')) return (DWORD)c;
        if (c == L';') return VK_OEM_1;
        if (c == L'/') return VK_OEM_2;
        if (c == L'`') return VK_OEM_3;
        if (c == L'[') return VK_OEM_4;
        if (c == L'\\') return VK_OEM_5;
        if (c == L']') return VK_OEM_6;
        if (c == L'\'') return VK_OEM_7;
        if (c == L',') return VK_OEM_COMMA;
        if (c == L'.') return VK_OEM_PERIOD;
        if (c == L'-') return VK_OEM_MINUS;
        if (c == L'=') return VK_OEM_PLUS;
    }
    if (name.size() >= 2 && name.size() <= 3 && name[0] == L'F') {
        int n = _wtoi(name.c_str() + 1);
        if (n >= 1 && n <= 12) return VK_F1 + (n - 1);
    }
    if (name == L"Space") return VK_SPACE;
    if (name == L"Enter") return VK_RETURN;
    if (name == L"Tab") return VK_TAB;
    if (name == L"Escape") return VK_ESCAPE;
    if (name == L"Backspace") return VK_BACK;
    if (name == L"Delete") return VK_DELETE;
    if (name == L"Insert") return VK_INSERT;
    if (name == L"Home") return VK_HOME;
    if (name == L"End") return VK_END;
    if (name == L"PageUp") return VK_PRIOR;
    if (name == L"PageDown") return VK_NEXT;
    if (name == L"Left") return VK_LEFT;
    if (name == L"Right") return VK_RIGHT;
    if (name == L"Up") return VK_UP;
    if (name == L"Down") return VK_DOWN;
    return 0;
}

UINT ShortcutWin32Modifiers(const std::wstring& keys) {
    UINT mods = MOD_NOREPEAT;
    if (keys.find(L"Win+") != std::wstring::npos) mods |= MOD_WIN;
    if (keys.find(L"Ctrl+") != std::wstring::npos) mods |= MOD_CONTROL;
    if (keys.find(L"Alt+") != std::wstring::npos) mods |= MOD_ALT;
    if (keys.find(L"Shift+") != std::wstring::npos) mods |= MOD_SHIFT;
    return mods;
}

DWORD ShortcutKeyVk(const std::wstring& keys) {
    size_t pos = keys.rfind(L'+');
    std::wstring name = (pos != std::wstring::npos) ? keys.substr(pos + 1) : keys;
    return ShortcutNameToVk(name);
}

bool IsWindowsReservedShortcut(const std::wstring& keys) {
    bool hasWin = keys.find(L"Win") != std::wstring::npos;
    bool hasCtrl = keys.find(L"Ctrl") != std::wstring::npos;
    bool hasAlt = keys.find(L"Alt") != std::wstring::npos;
    DWORD key = ShortcutKeyVk(keys);
    if (!key) return false;

    if (hasCtrl && !hasWin && !hasAlt) {
        static const std::set<DWORD> ctrlReserved = {
            'A', 'C', 'V', 'X', 'Z', 'Y', 'S', 'O', 'P', 'N', 'F', 'H', 'J', 'K', 'L', 'M', 'R', 'T', 'U', 'W', 'D', 'E', 'G', 'I', 'Q', 'B'
        };
        if (ctrlReserved.count(key)) return true;
    }

    if (hasAlt && !hasWin && !hasCtrl) {
        if (key == VK_TAB || key == VK_F4 || key == VK_SPACE || key == VK_ESCAPE || key == VK_RETURN) return true;
        if (key >= 'A' && key <= 'Z') return true;
    }

    if (hasWin) return true;
    if (hasCtrl && keys.find(L"Shift+")!=std::wstring::npos && key==VK_ESCAPE) return true;

    return false;
}

std::wstring SerializeCustomShortcuts() {
    using namespace winrt::Windows::Data::Json;
    JsonArray arr;
    for (auto& sc : g_customShortcuts) {
        JsonObject obj;
        obj.SetNamedValue(L"keys", JsonValue::CreateStringValue(winrt::hstring(sc.keys)));
        obj.SetNamedValue(L"action", JsonValue::CreateStringValue(winrt::hstring(sc.action)));
        obj.SetNamedValue(L"enabled", JsonValue::CreateBooleanValue(sc.enabled));
        obj.SetNamedValue(L"overrideWindows", JsonValue::CreateBooleanValue(sc.overrideWindows));
        arr.Append(obj);
    }
    return std::wstring(arr.Stringify());
}

void DeserializeCustomShortcuts(const std::wstring& json) {
    using namespace winrt::Windows::Data::Json;
    g_customShortcuts.clear();
    if (json.empty()) return;
    try {
        auto arr = JsonArray::Parse(winrt::hstring(json));
        for (uint32_t i = 0; i < arr.Size(); i++) {
            auto obj = arr.GetObjectAt(i);
            CustomShortcut sc;
            sc.keys = std::wstring(obj.GetNamedString(L"keys", L""));
            sc.action = std::wstring(obj.GetNamedString(L"action", L""));
            sc.enabled = obj.GetNamedBoolean(L"enabled", true);
            sc.overrideWindows = obj.GetNamedBoolean(L"overrideWindows", false);
            if (!sc.keys.empty() && !sc.action.empty()) {
                g_customShortcuts.push_back(std::move(sc));
            }
        }
    } catch (...) {}
}

