static void TagSearchableCard(wuxc::Border const& card,
                              const std::wstring& label,
                              PCWSTR key,
                              const std::wstring& desc,
                              const std::wstring& extraOptions = L"") {
    if (!card) return;
    // Use unit separator \x1F between fields so RenderSettingsSearchResults
    // can distinguish title, key, description, and dropdown options cleanly.
    std::wstring meta = s_currentPageTitle + L"\x1F" + s_currentHeadingTitle + L"\x1F" +
                        label + L"\x1F" + (key ? key : L"") + L"\x1F" +
                        desc + L"\x1F" + extraOptions;
    card.Tag(winrt::box_value(winrt::hstring(meta)));
}

