[[clang::no_destroy]] DispatcherTimer g_cloakTimer{nullptr};

static int ReadTopBarAutoHideDurationMs() {
    int ms = g_settings.topBarAutoHideSpeed;
    if (ms < 0) ms = 0;
    wchar_t msBuf[64] = {0};
    size_t msLen = Wh_GetStringValue(L"topBarAutoHideMs", msBuf, ARRAYSIZE(msBuf));
    if (msLen > 0) {
        try { ms = std::stoi(msBuf); } catch (...) { ms = 500; }
    }
    return std::clamp(ms, 0, 2000);
}

void SlideTopBarXaml(bool show, bool animate) {
    if (!g_topBarAutoHideHost) return;
    try {
        static std::atomic<uint64_t> s_animationGeneration{0};
        uint64_t generation = s_animationGeneration.fetch_add(1) + 1;
        auto host = g_topBarAutoHideHost;
        host.IsHitTestVisible(true);
        {
            int ms = ReadTopBarAutoHideDurationMs();
            g_slideDurationMs = ms;
            g_topBarAutoHideSpeed.store(ms);
            g_settings.topBarAutoHideSpeed = ms;
        }
        Wh_Log(L"TopBar auto-hide animation: direction=%ls duration=%dms animated=%d",
               show ? L"open" : L"close",
               g_slideDurationMs, animate ? 1 : 0);
        auto xf = host.RenderTransform().try_as<wuxm::CompositeTransform>();
        if (!xf) {
            xf = wuxm::CompositeTransform();
            host.RenderTransformOrigin(wf::Point{0.0, 0.0});
            host.RenderTransform(xf);
        }
        double targetY = show ? 0.0 : -static_cast<double>(g_settings.barHeightDip);
        try { wuxh::ElementCompositionPreview::SetIsTranslationEnabled(host, true); } catch (...) {}
        if (!animate || g_slideDurationMs <= 0) {
            if (g_manualSlideTimer) g_manualSlideTimer.Stop();
            if (xf) xf.TranslateY(targetY);
            return;
        }
        static DispatcherTimer& s_manualSlideTimer = g_manualSlideTimer;
        static ULONGLONG s_manualSlideTick = 0;
        static double s_manualSlideFromY = 0;
        static double s_manualSlideToY = 0;
        static double s_manualSlideDurMs = 500;
        static uint64_t s_manualSlideGen = 0;
        s_manualSlideTick = GetTickCount64();
        s_manualSlideFromY = xf ? xf.TranslateY() : (show ? -static_cast<double>(g_settings.barHeightDip) : 0.0);
        s_manualSlideToY = targetY;
        s_manualSlideDurMs = static_cast<double>(g_slideDurationMs);
        s_manualSlideGen = generation;
        if (!s_manualSlideTimer) {
            s_manualSlideTimer = DispatcherTimer();
            s_manualSlideTimer.Interval(std::chrono::milliseconds(16));
            s_manualSlideTimer.Tick([](wf::IInspectable const&, wf::IInspectable const&) {
                if (s_manualSlideGen != s_animationGeneration.load()) {
                    s_manualSlideTimer.Stop();
                    return;
                }
                if (!g_topBarAutoHideHost) { s_manualSlideTimer.Stop(); return; }
                auto xf2 = g_topBarAutoHideHost.RenderTransform().try_as<wuxm::CompositeTransform>();
                if (!xf2) { s_manualSlideTimer.Stop(); return; }
                double elapsed = (double)(GetTickCount64() - s_manualSlideTick);
                double t = elapsed / s_manualSlideDurMs;
                if (t > 1.0) t = 1.0;
                double eased = 1.0 - std::pow(1.0 - t, 3.0);
                double y = s_manualSlideFromY + (s_manualSlideToY - s_manualSlideFromY) * eased;
                try { xf2.TranslateY(y); } catch (...) {}
                if (t >= 1.0) {
                    s_manualSlideTimer.Stop();
                    try {
                        if (g_topBarAutoHideHost) {
                            auto finalXf = g_topBarAutoHideHost.RenderTransform().try_as<wuxm::CompositeTransform>();
                            if (finalXf) finalXf.TranslateY(s_manualSlideToY);
                        }
                        if (s_manualSlideToY == 0.0 && g_topBarPopupHwnd && IsWindow(g_topBarPopupHwnd)) {
                            ForceDisableWindowsTransparency(g_topBarPopupHwnd, true);
                        }
                    } catch (...) {}
                }
            });
        }
        s_manualSlideTimer.Stop();
        s_manualSlideTimer.Start();
        return;
    } catch (...) {}
}

void ClipIslandHwndToEmpty();
void ClipHostHwndToEmpty();

void ParkHiddenTopBarPopup() {
    ClipIslandHwndToEmpty();
    ClipHostHwndToEmpty();
    if (g_topBarPopupRetryTimer) {
        try { g_topBarPopupRetryTimer.Stop(); } catch (...) {}
    }
    if (g_topBarPopupHwnd && IsWindow(g_topBarPopupHwnd)) {
        HRGN empty = CreateRectRgn(0, 0, 0, 0);
        if (empty) SetWindowRgn(g_topBarPopupHwnd, empty, TRUE);
        BOOL cloakOn = TRUE;
        DwmSetWindowAttribute(g_topBarPopupHwnd, DWMWA_CLOAK, &cloakOn, sizeof(cloakOn));
        LONG_PTR ex = GetWindowLongPtrW(g_topBarPopupHwnd, GWL_EXSTYLE);
        if (!(ex & WS_EX_TRANSPARENT)) {
            SetWindowLongPtrW(g_topBarPopupHwnd, GWL_EXSTYLE,
                              ex | static_cast<LONG_PTR>(WS_EX_TRANSPARENT));
        }
        g_suppressPopupPositionLock = true;
        SetWindowPos(g_topBarPopupHwnd, HWND_BOTTOM, -32000, -32000, 0, 0,
                     SWP_NOSIZE | SWP_NOACTIVATE | SWP_HIDEWINDOW | SWP_NOREDRAW | SWP_FRAMECHANGED);
        ShowWindow(g_topBarPopupHwnd, SW_HIDE);
        g_suppressPopupPositionLock = false;
    }
    // Also sweep any stale/duplicate Xaml_WindowedPopupClass in our own process
    // left behind over the top-bar strip (never touching Settings or live child/toast popups).
    if (!g_anyChildFlyoutOpen.load() && !g_liveNotifPopupOpen.load()) {
        struct SweepCtx { DWORD pid; RECT barStrip; };
        RECT mr = GetBarMonitorRect();
        RECT strip{ mr.left, mr.top, mr.right, mr.top + std::max(g_barHeightPx, 40) + 12 };
        SweepCtx ctx{ GetCurrentProcessId(), strip };
        EnumWindows([](HWND hwnd, LPARAM lp) -> BOOL {
            auto* c = reinterpret_cast<SweepCtx*>(lp);
            if (!IsWindow(hwnd) || !IsWindowVisible(hwnd)) return TRUE;
            if (hwnd == g_topBarHwnd || hwnd == g_islandHwnd || hwnd == g_topBarPopupHwnd ||
                hwnd == g_settingsWindowHwnd || IsXamlPopupOwnedBySettingsWindow(hwnd)) {
                return TRUE;
            }
            DWORD pid = 0;
            GetWindowThreadProcessId(hwnd, &pid);
            if (pid != c->pid) return TRUE;
            wchar_t cls[64]{};
            if (!GetClassNameW(hwnd, cls, ARRAYSIZE(cls))) return TRUE;
            if (!(wcsstr(cls, L"Xaml") && wcsstr(cls, L"Popup"))) return TRUE;
            RECT r{}, inter{};
            if (GetWindowRect(hwnd, &r) && IntersectRect(&inter, &r, &c->barStrip)) {
                HRGN empty = CreateRectRgn(0, 0, 0, 0);
                if (empty) SetWindowRgn(hwnd, empty, TRUE);
                BOOL cloakOn = TRUE;
                DwmSetWindowAttribute(hwnd, DWMWA_CLOAK, &cloakOn, sizeof(cloakOn));
                ShowWindow(hwnd, SW_HIDE);
            }
            return TRUE;
        }, reinterpret_cast<LPARAM>(&ctx));
    }
    {
        RECT mr = GetBarMonitorRect();
        POINT probePt{ mr.left + 100, mr.top + 20 };
        HWND under = WindowFromPoint(probePt);
        wchar_t cls[64]{};
        DWORD pid = 0;
        if (under) {
            GetClassNameW(under, cls, ARRAYSIZE(cls));
            GetWindowThreadProcessId(under, &pid);
        }
        Wh_Log(L"AutoHide: parked popup=%p; under(%ld,%ld)=%p class=%s pid=%u (ours=%u)",
               g_topBarPopupHwnd, probePt.x, probePt.y, under, cls, pid, GetCurrentProcessId());
    }
}

void ScheduleCloakAfterSlide() {
    if (!g_cloakTimer) {
        g_cloakTimer = DispatcherTimer();
        g_cloakTimer.Tick([](wf::IInspectable const&, wf::IInspectable const&) {
            g_cloakTimer.Stop();
            g_topBarHideAnimating.store(false);
            if (g_topBarAutoHidden.load() &&
                g_topBarPopupHwnd && IsWindow(g_topBarPopupHwnd)) {
                ForceDisableWindowsTransparency(g_topBarPopupHwnd, true);
                ParkHiddenTopBarPopup();
            }
        });
    }
    g_cloakTimer.Interval(std::chrono::milliseconds(g_slideDurationMs + 35));
    g_cloakTimer.Stop();
    g_cloakTimer.Start();
}

void ForceXamlPopupInputRefresh() {
    HWND popup = g_topBarPopupHwnd;
    if (!popup || !IsWindow(popup)) return;
    RECT r{};
    if (!GetWindowRect(popup, &r)) return;
    int w = r.right - r.left;
    int h = r.bottom - r.top;
    if (w <= 0 || h <= 1) return;
    g_suppressPopupPositionLock = true;
    SetWindowPos(popup, nullptr, r.left, r.top, w, h - 1,
                 SWP_NOZORDER | SWP_NOACTIVATE | SWP_NOSENDCHANGING);
    SetWindowPos(popup, nullptr, r.left, r.top, w, h,
                 SWP_NOZORDER | SWP_NOACTIVATE | SWP_NOSENDCHANGING);
    g_suppressPopupPositionLock = false;
}

void EnforceTopBarPopupState() {
    struct Ctx { DWORD pid; };
    Ctx ctx{ GetCurrentProcessId() };
    EnumWindows([](HWND hwnd, LPARAM lp) -> BOOL {
        auto* c = reinterpret_cast<Ctx*>(lp);
        if (!IsWindow(hwnd)) return TRUE;
        if (hwnd == g_islandHwnd || hwnd == g_topBarHwnd) return TRUE;
        if (hwnd == g_topBarPopupHwnd && (ShouldKeepTopBarPopupHidden() || g_fullScreenAppActive)) return TRUE;
        DWORD pid = 0;
        GetWindowThreadProcessId(hwnd, &pid);
        if (pid != c->pid) return TRUE;
        wchar_t cls[256]{};
        if (!GetClassNameW(hwnd, cls, 256)) return TRUE;
        if (!(wcsstr(cls, L"Xaml") && wcsstr(cls, L"Popup"))) return TRUE;
        LONG_PTR ex = GetWindowLongPtrW(hwnd, GWL_EXSTYLE);
        if (ex & WS_EX_TRANSPARENT) {
            SetWindowLongPtrW(hwnd, GWL_EXSTYLE,
                              ex & ~static_cast<LONG_PTR>(WS_EX_TRANSPARENT));
            SetWindowPos(hwnd, nullptr, 0, 0, 0, 0,
                         SWP_NOMOVE | SWP_NOSIZE | SWP_NOZORDER |
                         SWP_NOACTIVATE | SWP_FRAMECHANGED);
        }
        return TRUE;
    }, reinterpret_cast<LPARAM>(&ctx));
}

void FinishShowBarForAutoHide() {
    g_autoHideRevealPending = false;
    g_topBarHideAnimating.store(false);
    if (g_rgnTimer) g_rgnTimer.Stop();
    if (!g_topBarAutoHidden.exchange(false)) return;

    Wh_Log(L"AutoHide: revealing existing popup input site=%p",
           g_topBarPopupHwnd);

    if (g_topBarPopupHwnd && IsWindow(g_topBarPopupHwnd)) {
        ForceDisableWindowsTransparency(g_topBarPopupHwnd, true);
        DwmFlush();
    }
    if (g_islandHwnd && IsWindow(g_islandHwnd)) {
        ForceDisableWindowsTransparency(g_islandHwnd, true);
        DwmFlush();
    }

    if (g_topBarPopupHwnd && IsWindow(g_topBarPopupHwnd)) {
        LONG_PTR ex = GetWindowLongPtrW(g_topBarPopupHwnd, GWL_EXSTYLE);
        if (ex & WS_EX_TRANSPARENT) {
            SetWindowLongPtrW(g_topBarPopupHwnd, GWL_EXSTYLE,
                              ex & ~static_cast<LONG_PTR>(WS_EX_TRANSPARENT));
        }
        SetWindowRgn(g_topBarPopupHwnd, nullptr, TRUE);
        RECT mr0 = GetBarMonitorRect();
        g_forcePopupPosition = true;
        g_suppressPopupPositionLock = true;
        SetWindowPos(g_topBarPopupHwnd, HWND_TOPMOST,
                     mr0.left, mr0.top,
                     mr0.right - mr0.left, g_barHeightPx,
                     SWP_NOACTIVATE | SWP_NOOWNERZORDER | SWP_SHOWWINDOW);
        g_suppressPopupPositionLock = false;
        DwmFlush();
        ForceDisableWindowsTransparency(g_topBarPopupHwnd, true);
        DwmFlush();
        BOOL cloakOff0 = FALSE;
        DwmSetWindowAttribute(g_topBarPopupHwnd, DWMWA_CLOAK,
                              &cloakOff0, sizeof(cloakOff0));
        DwmFlush();
        ForceDisableWindowsTransparency(g_topBarPopupHwnd, true);
        DwmFlush();
    }

    if (g_islandHwnd && IsWindow(g_islandHwnd)) {
        ForceDisableWindowsTransparency(g_islandHwnd, true);
    }
    if (g_islandHwnd && IsWindow(g_islandHwnd)) {
        ForceDisableWindowsTransparency(g_islandHwnd, true);
    }
    if (g_topBarHwnd && IsWindow(g_topBarHwnd)) {
        ForceDisableWindowsTransparency(g_topBarHwnd, true);
    }
    if (g_topBarPopupHwnd && IsWindow(g_topBarPopupHwnd)) {
        ForceDisableWindowsTransparency(g_topBarPopupHwnd, true);
        DwmFlush();
        g_suppressPopupPositionLock = true;
        SetWindowPos(g_topBarPopupHwnd, HWND_TOPMOST, 0, 0, 0, 0,
                     SWP_NOMOVE | SWP_NOSIZE | SWP_NOACTIVATE |
                     SWP_NOOWNERZORDER | SWP_SHOWWINDOW);
        g_suppressPopupPositionLock = false;
        ForceDisableWindowsTransparency(g_topBarPopupHwnd, true);
        DwmFlush();
        BOOL off = FALSE;
        DwmSetWindowAttribute(g_topBarPopupHwnd, DWMWA_CLOAK,
                              &off, sizeof(off));
        ForceDisableWindowsTransparency(g_topBarPopupHwnd, true);
        RestoreTopBarZOrder();
        ForceDisableWindowsTransparency(g_topBarHwnd, true);
        ForceDisableWindowsTransparency(g_topBarPopupHwnd, true);
        DwmFlush();
        RedrawWindow(g_topBarPopupHwnd, nullptr, nullptr,
                     RDW_INVALIDATE | RDW_UPDATENOW | RDW_ALLCHILDREN);
    }

    if (g_islandHwnd && IsWindow(g_islandHwnd)) {
        ForceDisableWindowsTransparency(g_islandHwnd, true);
    }
    if (g_topBarPopupHwnd && IsWindow(g_topBarPopupHwnd)) {
        ForceDisableWindowsTransparency(g_topBarPopupHwnd, true);
    }
    DwmFlush();
    if (g_topBarPopupHwnd && IsWindow(g_topBarPopupHwnd)) {
        SetWindowPos(g_topBarPopupHwnd, HWND_TOPMOST, 0, 0, 0, 0,
                     SWP_NOMOVE | SWP_NOSIZE | SWP_NOACTIVATE | SWP_NOOWNERZORDER);
        DwmFlush();
    }
    if (g_settings.topBarShowTrigger == L"activationbar") {
        AnimateActivationPillWindow(false);
        static DispatcherTimer& s_pillHideDelayTimer = g_pillHideDelayTimer;
        if (!s_pillHideDelayTimer) {
            s_pillHideDelayTimer = DispatcherTimer();
            s_pillHideDelayTimer.Interval(std::chrono::milliseconds(120));
            s_pillHideDelayTimer.Tick([](wf::IInspectable const&, wf::IInspectable const&) {
                s_pillHideDelayTimer.Stop();
                try { SlideTopBarXaml(true, true); } catch (...) {}
            });
        }
        s_pillHideDelayTimer.Stop();
        s_pillHideDelayTimer.Start();
    } else {
        SlideTopBarXaml(true, true);
    }
    for (int delayMs : { 16, 40, 90, 180, 320, 600, 1000 }) {
        RunInBackground([delayMs] {
            if (WaitForSingleObject(g_stopEvent, delayMs) == WAIT_OBJECT_0) return;
            RunOnUiThread([] {
                try {
                    if (g_topBarPopupHwnd && IsWindow(g_topBarPopupHwnd) &&
                        !ShouldKeepTopBarPopupHidden()) {
                        ForceDisableWindowsTransparency(g_topBarPopupHwnd, true);
                        DwmFlush();
                    }
                } catch (...) {}
            });
        });
    }
    g_barLeaveTick = 0;
}

void ShowBarForAutoHide() {
    if (!g_topBarAutoHidden.load() || g_autoHideRevealPending.exchange(true)) {
        return;
    }
    POINT cursor{};
    GetCursorPos(&cursor);
    Wh_Log(L"AutoHide: revealing bar at cursor (%ld,%ld), popup=%p",
           cursor.x, cursor.y, g_topBarPopupHwnd);
    if (g_cloakTimer) g_cloakTimer.Stop();
    FinishShowBarForAutoHide();
}

void HideBarForAutoHide() {
    if (g_topBarAutoHidden.exchange(true)) return;
    const int slideMs = ReadTopBarAutoHideDurationMs();
    g_slideDurationMs = slideMs;
    g_topBarAutoHideSpeed.store(slideMs);
    g_settings.topBarAutoHideSpeed = slideMs;

    POINT cursor{};
    GetCursorPos(&cursor);
    Wh_Log(L"AutoHide: hiding bar (%dms) at cursor (%ld,%ld), popup=%p",
           slideMs, cursor.x, cursor.y, g_topBarPopupHwnd);
    if (g_islandHwnd && IsWindow(g_islandHwnd)) {
        ForceDisableWindowsTransparency(g_islandHwnd, true);
    }
    if (g_topBarPopupHwnd && IsWindow(g_topBarPopupHwnd)) {
        ForceDisableWindowsTransparency(g_topBarPopupHwnd, true);
    }

    if (slideMs <= 0) {
        g_topBarHideAnimating.store(false);
        if (g_rgnTimer) g_rgnTimer.Stop();
        if (g_cloakTimer) g_cloakTimer.Stop();
        if (g_pillDelayTimer) g_pillDelayTimer.Stop();
        SlideTopBarXaml(false, false);
        if (g_topBarPopupHwnd && IsWindow(g_topBarPopupHwnd)) {
            ForceDisableWindowsTransparency(g_topBarPopupHwnd, true);
            ParkHiddenTopBarPopup();
        }
        if (g_settings.topBarShowTrigger == L"activationbar" && !IsTrueFullscreen()) {
            try { AnimateActivationPillWindow(true); } catch (...) {}
        }
        return;
    }

    // Keep DWMWA_CLOAK off for the duration of the slide-out so AutoHideTick's
    // SyncTopBarCloakState doesn't hide the bar after ~50ms before the slide finishes.
    g_topBarHideAnimating.store(true);
    SlideTopBarXaml(false, true);
    if (g_topBarPopupHwnd && IsWindow(g_topBarPopupHwnd)) {
        static DispatcherTimer& s_rgnTimer = g_rgnTimer;
        static ULONGLONG s_rgnTick = 0;
        static int s_rgnDurMs = 0;
        static int s_rgnH = 0;
        static int s_rgnWidth = 0;
        s_rgnTick = GetTickCount64();
        s_rgnDurMs = slideMs;
        s_rgnH = g_barHeightPx > 0 ? g_barHeightPx : 40;
        RECT rgnMr = GetBarMonitorRect();
        s_rgnWidth = rgnMr.right - rgnMr.left;
        if (!s_rgnTimer) {
            s_rgnTimer = DispatcherTimer();
            s_rgnTimer.Interval(std::chrono::milliseconds(16));
            s_rgnTimer.Tick([](wf::IInspectable const&, wf::IInspectable const&) {
                if (!g_topBarAutoHidden.load()) {
                    g_topBarHideAnimating.store(false);
                    if (g_topBarPopupHwnd && IsWindow(g_topBarPopupHwnd)) {
                        SetWindowRgn(g_topBarPopupHwnd, nullptr, TRUE);
                    }
                    s_rgnTimer.Stop();
                    return;
                }
                if (!g_topBarPopupHwnd || !IsWindow(g_topBarPopupHwnd)) {
                    g_topBarHideAnimating.store(false);
                    s_rgnTimer.Stop();
                    return;
                }
                ULONGLONG now = GetTickCount64();
                double t = s_rgnDurMs > 0 ? (now - s_rgnTick) / (double)s_rgnDurMs : 1.0;
                if (t > 1.0) t = 1.0;
                double eased = 1.0 - std::pow(1.0 - t, 3.0);
                int newH = s_rgnH - (int)(s_rgnH * eased);
                if (newH < 1) newH = 1;
                HRGN rgn = CreateRectRgn(0, 0, s_rgnWidth, newH);
                if (rgn) {
                    SetWindowRgn(g_topBarPopupHwnd, rgn, TRUE);
                }
                if (t >= 1.0) {
                    s_rgnTimer.Stop();
                    g_topBarHideAnimating.store(false);
                    ForceDisableWindowsTransparency(g_topBarPopupHwnd, true);
                    ParkHiddenTopBarPopup();
                }
            });
        }
        s_rgnTimer.Stop();
        s_rgnTimer.Start();
    }
    ScheduleCloakAfterSlide();
    if (g_settings.topBarShowTrigger == L"activationbar" && !IsTrueFullscreen()) {
        static DispatcherTimer& s_pillDelayTimer = g_pillDelayTimer;
        int pillDelayMs = slideMs;
        if (!s_pillDelayTimer) {
            s_pillDelayTimer = DispatcherTimer();
            s_pillDelayTimer.Tick([](wf::IInspectable const&, wf::IInspectable const&) {
                s_pillDelayTimer.Stop();
                if (!g_topBarAutoHidden.load()) return;
                try { AnimateActivationPillWindow(true); } catch (...) {}
            });
        }
        s_pillDelayTimer.Interval(std::chrono::milliseconds(pillDelayMs));
        s_pillDelayTimer.Stop();
        s_pillDelayTimer.Start();
    }
}

void SyncTopBarCloakState() {
    if (!g_topBarPopupHwnd || !IsWindow(g_topBarPopupHwnd)) return;
    bool wantCloaked = ShouldKeepTopBarPopupHidden();
    BOOL isCloaked = FALSE;
    if (SUCCEEDED(DwmGetWindowAttribute(g_topBarPopupHwnd, DWMWA_CLOAKED,
                                        &isCloaked, sizeof(isCloaked)))) {
        if (wantCloaked != (isCloaked != FALSE)) {
            BOOL val = wantCloaked ? TRUE : FALSE;
            DwmSetWindowAttribute(g_topBarPopupHwnd, DWMWA_CLOAK, &val, sizeof(val));
        }
    }
    if (wantCloaked) {
        RECT r{};
        bool onScreen = GetWindowRect(g_topBarPopupHwnd, &r) && r.left > -16000;
        if (IsWindowVisible(g_topBarPopupHwnd) || onScreen) {
            ParkHiddenTopBarPopup();
        }
    }
}

// --- Smart Auto Hide: transparent detector region ---------------------------
// The detector region is the bar's grid: the full width of the bar monitor and
// the bar's height, anchored to the top of that monitor. On a 1080p display
// with a 40 px bar that is exactly the 1080x40 area the bar occupies.
//
// It is deliberately a pure geometry region and not a real window: nothing is
// ever painted for it and it never takes part in hit-testing, so by
// construction it is invisible to the user and every click passes straight
// through it. A real layered window would shadow WindowFromPoint over the top
// strip and break the bar's own hover detection.
static RECT SmartDetectorRegion() {
    RECT r = GetBarMonitorRect();
    r.bottom = r.top + (g_barHeightPx > 0 ? g_barHeightPx : 40);
    return r;
}

// True when at least one normal application window occupies the detector
// region. Runs once per tick (20 Hz) and ignores everything that can never be
// a real window over the bar: our own UI, tool/owned/child windows, cloaked
// windows from other virtual desktops, minimised windows, the shell's own
// windows and anything living on another monitor.
//
// A maximised window always counts even though the appbar reservation keeps
// its raw rectangle below the bar, which is why a plain rectangle test alone
// never detected it.
static bool AnyWindowInSmartDetector() {
    const RECT region = SmartDetectorRegion();
    const HMONITOR barMonitor = GetBarMonitor();
    const DWORD selfPid = GetCurrentProcessId();

    struct Ctx {
        RECT region;
        HMONITOR monitor;
        DWORD selfPid;
        bool found;
    } ctx{region, barMonitor, selfPid, false};

    EnumWindows(
        [](HWND h, LPARAM lp) -> BOOL {
            auto* c = reinterpret_cast<Ctx*>(lp);
            if (!h || !IsWindowVisible(h) || IsIconic(h)) return TRUE;
            DWORD pid = 0;
            GetWindowThreadProcessId(h, &pid);
            if (!pid || pid == c->selfPid) return TRUE;
            if (GetWindow(h, GW_OWNER) != nullptr) return TRUE;
            LONG_PTR exStyle = GetWindowLongPtrW(h, GWL_EXSTYLE);
            if (exStyle & (WS_EX_TOOLWINDOW | WS_EX_NOACTIVATE)) return TRUE;
            if (GetAncestor(h, GA_ROOT) != h) return TRUE;
            BOOL cloaked = FALSE;
            if (SUCCEEDED(DwmGetWindowAttribute(h, DWMWA_CLOAKED, &cloaked,
                                                sizeof(cloaked))) &&
                cloaked) {
                return TRUE;
            }
            wchar_t cls[64]{};
            if (GetClassNameW(h, cls, 64)) {
                if (wcscmp(cls, L"Progman") == 0 ||
                    wcscmp(cls, L"WorkerW") == 0 ||
                    wcscmp(cls, L"Shell_TrayWnd") == 0 ||
                    wcscmp(cls, L"Shell_SecondaryTrayWnd") == 0) {
                    return TRUE;
                }
            }
            if (MonitorFromWindow(h, MONITOR_DEFAULTTONEAREST) != c->monitor) {
                return TRUE;
            }
            if (IsZoomed(h)) {
                c->found = true;
                return FALSE;
            }
            RECT frame{};
            if (FAILED(DwmGetWindowAttribute(h, DWMWA_EXTENDED_FRAME_BOUNDS,
                                             &frame, sizeof(frame)))) {
                if (!GetWindowRect(h, &frame)) return TRUE;
            }
            RECT hit{};
            if (!IntersectRect(&hit, &frame, &c->region)) return TRUE;
            if ((hit.right - hit.left) < 4 || (hit.bottom - hit.top) < 2) {
                return TRUE;
            }
            c->found = true;
            return FALSE;
        },
        reinterpret_cast<LPARAM>(&ctx));
    return ctx.found;
}

// Cached wrapper around the scan. The enumeration touches every top-level
// window and asks DWM for its frame bounds, so it runs at most ~8 times a
// second instead of on every 50 ms tick. The lag is imperceptible.
static bool AnyWindowInSmartDetectorCached() {
    static ULONGLONG s_lastScan = 0;
    static bool s_lastResult = false;
    const ULONGLONG now = GetTickCount64();
    if (s_lastScan != 0 && now - s_lastScan < 120) return s_lastResult;
    s_lastScan = now;
    s_lastResult = AnyWindowInSmartDetector();
    return s_lastResult;
}

// Smart Auto Hide tick.
//
// The reveal side is a literal copy of the Auto Hide body below: the same
// trigger (a 1 px band at the very top of the monitor for "top edge", the
// activation pill for "activation bar"), the same reveal delay, the same
// no-reveal-while-dragging rule, the same leave delay and the same
// fullscreen/flyout suppression. Nothing about hovering the 40 px detector
// region reveals the bar - that region only decides when the bar must go away.
//
// The only added rule is the hide side: a window in the detector region makes
// the bar hide, and the bar comes back as soon as the region is clear.
static ULONGLONG g_smartRevealHoverStart = 0;

// Drops every latch Smart Auto Hide holds. Called whenever the bar behaviour
// changes so a stale hover timestamp can never leak into another mode (or back
// into Smart Auto Hide).
void ResetSmartAutoHideState() {
    g_smartRevealHoverStart = 0;
    g_barLeaveTick = 0;
}

static void SmartAutoHideTick() {
    // An open flyout, context menu or thumbnail preview always wins: the bar
    // has to stay put until the interaction is over.
    const bool thumbnailOpen =
        (g_thumbPreviewHwnd && IsWindow(g_thumbPreviewHwnd) &&
         IsWindowVisible(g_thumbPreviewHwnd)) ||
        (g_thumbButtonsHwnd && IsWindow(g_thumbButtonsHwnd) &&
         IsWindowVisible(g_thumbButtonsHwnd));
    if (g_anyChildFlyoutOpen.load() || thumbnailOpen ||
        g_contextMenuTargetHwnd != nullptr) {
        g_barLeaveTick = 0;
        return;
    }

    // Keep the activation pill out of the way when it is not the trigger.
    if (g_settings.topBarShowTrigger != L"activationbar" &&
        g_activationPillHwnd && IsWindow(g_activationPillHwnd) &&
        IsWindowVisible(g_activationPillHwnd)) {
        ShowWindow(g_activationPillHwnd, SW_HIDE);
    }

    // Same fullscreen suppression as plain Auto Hide.
    if (g_fullScreenAppActive) {
        if (IsAnyFullscreenActive()) {
            if (g_activationPillHwnd && IsWindow(g_activationPillHwnd) &&
                IsWindowVisible(g_activationPillHwnd)) {
                ShowWindow(g_activationPillHwnd, SW_HIDE);
            }
            return;
        }
        g_fullScreenAppActive = false;
        RestoreTopBarZOrder();
        if (g_settings.topBarShowTrigger == L"activationbar" &&
            !(g_activationPillHwnd && IsWindow(g_activationPillHwnd) &&
              IsWindowVisible(g_activationPillHwnd))) {
            AnimateActivationPillWindow(true);
        }
    }

    POINT pt{};
    if (!GetCursorPos(&pt)) return;
    const RECT mr = GetBarMonitorRect();

    const bool inMonX = pt.x >= mr.left && pt.x <= mr.right;
    // Exactly the Auto Hide reveal target: the single pixel row at the very top
    // of the monitor. The detector region must never act as a trigger.
    const bool onTopEdge = inMonX && (pt.y >= mr.top && pt.y <= mr.top + 1);

    bool onPill = false;
    if (g_settings.topBarShowTrigger == L"activationbar" &&
        g_activationPillHwnd && IsWindow(g_activationPillHwnd) &&
        IsWindowVisible(g_activationPillHwnd)) {
        RECT pr{};
        if (GetWindowRect(g_activationPillHwnd, &pr)) {
            InflateRect(&pr, 6, 6);
            onPill = PtInRect(&pr, pt) != FALSE;
        }
    }

    const bool shouldShow =
        (g_settings.topBarShowTrigger == L"topedge") ? onTopEdge : onPill;
    const bool draggingWindow = (GetAsyncKeyState(VK_LBUTTON) & 0x8000) != 0;

    // The one thing Smart Auto Hide adds: is a window occupying the detector
    // region, i.e. does anything actually need the bar out of the way?
    const bool occupied = AnyWindowInSmartDetectorCached();

    if (g_topBarAutoHidden.load()) {
        g_barLeaveTick = 0;

        // Nothing needs the space any more (no window left in the region, or it
        // was never occupied): the bar belongs on screen.
        if (!occupied) {
            g_smartRevealHoverStart = 0;
            ShowBarForAutoHide();
            return;
        }

        // Still occupied: only an explicit reveal request from the configured
        // trigger brings the bar back, exactly like Auto Hide.
        if (shouldShow && !draggingWindow) {
            const ULONGLONG now = GetTickCount64();
            if (g_smartRevealHoverStart == 0) g_smartRevealHoverStart = now;
            if (now - g_smartRevealHoverStart <
                static_cast<ULONGLONG>(g_settings.topBarRevealDelayMs)) {
                return;
            }
            g_smartRevealHoverStart = 0;
            ShowBarForAutoHide();
            return;
        }
        g_smartRevealHoverStart = 0;
        return;
    }

    // Visible.
    g_smartRevealHoverStart = 0;

    // Nothing occupies the region: the bar stays where it is.
    if (!occupied) {
        g_barLeaveTick = 0;
        return;
    }

    // A window does occupy the region. Keep the bar up while the pointer is on
    // it (or on something it opened), and hide it otherwise.
    const bool insideBar =
        inMonX && (pt.y >= mr.top && pt.y <= mr.top + g_barHeightPx);

    bool insideFlyout = false;
    HWND hit = WindowFromPoint(pt);
    if (hit) {
        DWORD pid = 0;
        GetWindowThreadProcessId(hit, &pid);
        if (pid == GetCurrentProcessId() && hit != g_topBarHwnd &&
            hit != g_islandHwnd && hit != g_topBarPopupHwnd) {
            wchar_t cls[256]{};
            if (GetClassName(hit, cls, 256) && wcsstr(cls, L"Xaml") &&
                wcsstr(cls, L"Popup")) {
                insideFlyout = true;
            }
        }
    }

    bool insideThumbPreview = false;
    if (g_thumbPreviewHwnd && IsWindow(g_thumbPreviewHwnd)) {
        RECT tr{};
        if (GetWindowRect(g_thumbPreviewHwnd, &tr) && PtInRect(&tr, pt)) {
            insideThumbPreview = true;
        }
    }
    if (!insideThumbPreview && g_thumbButtonsHwnd &&
        IsWindow(g_thumbButtonsHwnd)) {
        RECT tr{};
        if (GetWindowRect(g_thumbButtonsHwnd, &tr) && PtInRect(&tr, pt)) {
            insideThumbPreview = true;
        }
    }

    // While a window is being dragged the pointer always sits on that window's
    // title bar, which is inside the bar band - that must not count as "in use",
    // otherwise dragging a window onto the region would never hide the bar.
    const bool userOnBar = insideFlyout || insideThumbPreview ||
                           (!draggingWindow && insideBar);
    if (userOnBar) {
        g_barLeaveTick = 0;
        return;
    }

    // Hide after the Auto Hide leave delay so a window merely crossing the bar
    // does not make it flicker.
    const ULONGLONG now = GetTickCount64();
    const ULONGLONG leaveTick = g_barLeaveTick.load();
    if (leaveTick == 0) {
        g_barLeaveTick = now;
    } else if (now - leaveTick >
               static_cast<ULONGLONG>(g_settings.topBarHideDelayMs)) {
        HideBarForAutoHide();
    }
}

void AutoHideTick() {
    if (g_settings.topBarBehaviour != L"default" || g_anyChildFlyoutOpen.load()) {
        EnforceTopBarPopupState();
    }
    SyncTopBarCloakState();
    if (g_settings.topBarBehaviour == L"default") {
        g_topBarHideAnimating.store(false);
        if (g_autoHideBootDelay.exchange(false)) {
            g_autoHideBootDelayScheduled = false;
            if (g_autoHideBootDelayTimer) g_autoHideBootDelayTimer.Stop();
        }
        if (g_fullScreenAppActive && !IsAnyFullscreenActive()) {
            g_fullScreenAppActive = false;
            RestoreTopBarZOrder();
        }
        if (g_topBarAutoHidden.exchange(false)) {
            SetTopBarPopupClickThrough(false);
            SlideTopBarXaml(true, false);
            SlideTopBar(true, false);
            if (g_topBarAutoHideHost) {
                try {
                    g_topBarAutoHideHost.Opacity(1.0);
                    if (auto transform = g_topBarAutoHideHost.RenderTransform()
                            .try_as<wuxm::CompositeTransform>()) {
                        transform.TranslateY(0.0);
                    }
                } catch (...) {}
            }
            if (g_topBarPopupHwnd && IsWindow(g_topBarPopupHwnd)) {
                SetWindowRgn(g_topBarPopupHwnd, nullptr, TRUE);
                ForceDisableWindowsTransparency(g_topBarPopupHwnd, true);
                BOOL cloakOff = FALSE;
                DwmSetWindowAttribute(g_topBarPopupHwnd, DWMWA_CLOAK,
                                      &cloakOff, sizeof(cloakOff));
                RECT mr = GetBarMonitorRect();
                g_suppressPopupPositionLock = true;
                SetWindowPos(g_topBarPopupHwnd, HWND_TOPMOST, mr.left, mr.top,
                             mr.right - mr.left, g_barHeightPx,
                             SWP_NOACTIVATE | SWP_NOOWNERZORDER | SWP_SHOWWINDOW);
                g_suppressPopupPositionLock = false;
            }
            if (g_topBarHwnd && IsWindow(g_topBarHwnd)) {
                PositionAppBar(g_topBarHwnd, g_barHeightPx);
            }
        }
        if (g_activationPillHwnd && IsWindow(g_activationPillHwnd) &&
            IsWindowVisible(g_activationPillHwnd)) {
            ShowWindow(g_activationPillHwnd, SW_HIDE);
        }
        try {
            if (g_topBarAutoHideHost) {
                g_topBarAutoHideHost.Opacity(1.0);
                if (auto transform = g_topBarAutoHideHost.RenderTransform()
                        .try_as<wuxm::CompositeTransform>()) {
                    transform.TranslateY(0.0);
                }
            }
        } catch (...) {}
        if (!g_fullScreenAppActive) {
            if (g_topBarPopupHwnd && IsWindow(g_topBarPopupHwnd)) {
                SetTopBarPopupClickThrough(false);
                BOOL cloakOff = FALSE;
                DwmSetWindowAttribute(g_topBarPopupHwnd, DWMWA_CLOAK,
                                      &cloakOff, sizeof(cloakOff));
                if (!IsWindowVisible(g_topBarPopupHwnd)) {
                    ShowWindow(g_topBarPopupHwnd, SW_SHOWNOACTIVATE);
                }
            } else {
                EnsureTopBarPopupShown();
            }
        }
        return;
    }

    if (g_autoHideBootDelay.load()) {
        g_barLeaveTick = 0;
        return;
    }

    if (!g_topBarAutoHideHost) return;

    // --- Smart Auto Hide -----------------------------------------------------
    // Hides while a window occupies the bar's detector region and comes back
    // as soon as the last one leaves. All the reveal mechanics are the plain
    // Auto Hide ones, so triggers, delays, animations, the activation pill and
    // flyout suppression behave identically in both modes.
    if (g_settings.topBarBehaviour == L"smart") {
        SmartAutoHideTick();
        return;
    }
    // ------------------------------------------------------------------------

    if (g_settings.topBarShowTrigger != L"activationbar" &&
        g_activationPillHwnd && IsWindow(g_activationPillHwnd) &&
        IsWindowVisible(g_activationPillHwnd)) {
        ShowWindow(g_activationPillHwnd, SW_HIDE);
    }

    if (g_fullScreenAppActive) {
        if (IsAnyFullscreenActive()) {
            if (g_activationPillHwnd && IsWindow(g_activationPillHwnd) &&
                IsWindowVisible(g_activationPillHwnd)) {
                ShowWindow(g_activationPillHwnd, SW_HIDE);
            }
            return;
        }
        g_fullScreenAppActive = false;
        RestoreTopBarZOrder();
        if (g_settings.topBarShowTrigger == L"activationbar" &&
            !(g_activationPillHwnd && IsWindow(g_activationPillHwnd) &&
              IsWindowVisible(g_activationPillHwnd))) {
            AnimateActivationPillWindow(true);
        }
    }

    if (g_anyChildFlyoutOpen.load()) {
        g_barLeaveTick = 0;
        return;
    }

    POINT pt{};
    if (!GetCursorPos(&pt)) return;
    RECT mr = GetBarMonitorRect();

    bool inMonX = (pt.x >= mr.left && pt.x <= mr.right);
    bool onTopEdge = inMonX && (pt.y >= mr.top && pt.y <= mr.top + 1);

    bool onPill = false;
    if (g_settings.topBarShowTrigger == L"activationbar" &&
        g_activationPillHwnd && IsWindow(g_activationPillHwnd) &&
        IsWindowVisible(g_activationPillHwnd)) {
        RECT pr{};
        if (GetWindowRect(g_activationPillHwnd, &pr)) {
            InflateRect(&pr, 6, 6);
            onPill = PtInRect(&pr, pt) != FALSE;
        }
    }

    bool shouldShow = (g_settings.topBarShowTrigger == L"topedge") ? onTopEdge : onPill;
    bool currentlyHidden = g_topBarAutoHidden.load();
    bool draggingWindow = (GetAsyncKeyState(VK_LBUTTON) & 0x8000) != 0;
    static ULONGLONG s_activationHoverStart = 0;

    if (currentlyHidden && shouldShow && draggingWindow) {
        s_activationHoverStart = 0;
        return;
    }

    if (currentlyHidden && shouldShow) {
        ULONGLONG now = GetTickCount64();
        if (s_activationHoverStart == 0) s_activationHoverStart = now;
        if (now - s_activationHoverStart <
            static_cast<ULONGLONG>(g_settings.topBarRevealDelayMs)) {
            return;
        }
        s_activationHoverStart = 0;
        ShowBarForAutoHide();
        return;
    }
    if (!shouldShow || !currentlyHidden) {
        s_activationHoverStart = 0;
    }

    if (!currentlyHidden) {
        bool insideBar = inMonX && (pt.y >= mr.top && pt.y <= mr.top + g_barHeightPx);

        bool insideFlyout = false;
        HWND hit = WindowFromPoint(pt);
        if (hit) {
            DWORD pid = 0;
            GetWindowThreadProcessId(hit, &pid);
            if (pid == GetCurrentProcessId() &&
                hit != g_topBarHwnd && hit != g_islandHwnd &&
                hit != g_topBarPopupHwnd) {
                wchar_t cls[256]{};
                if (GetClassName(hit, cls, 256) &&
                    wcsstr(cls, L"Xaml") && wcsstr(cls, L"Popup")) {
                    insideFlyout = true;
                }
            }
        }

        bool insideThumbPreview = false;
        if (g_thumbPreviewHwnd && IsWindow(g_thumbPreviewHwnd)) {
            RECT tr{};
            if (GetWindowRect(g_thumbPreviewHwnd, &tr) && PtInRect(&tr, pt)) {
                insideThumbPreview = true;
            }
        }
        if (!insideThumbPreview && g_thumbButtonsHwnd && IsWindow(g_thumbButtonsHwnd)) {
            RECT tr{};
            if (GetWindowRect(g_thumbButtonsHwnd, &tr) && PtInRect(&tr, pt)) {
                insideThumbPreview = true;
            }
        }

        if (!insideBar && !insideFlyout && !insideThumbPreview) {
            ULONGLONG now = GetTickCount64();
            ULONGLONG leaveTick = g_barLeaveTick.load();
            if (leaveTick == 0) {
                g_barLeaveTick = now;
            } else if (now - leaveTick >
                       static_cast<ULONGLONG>(g_settings.topBarHideDelayMs)) {
                HideBarForAutoHide();
            }
        } else {
            g_barLeaveTick = 0;
        }
    }
}

