            if (batteryIcon) {
                batteryIcon.VerticalAlignment(VerticalAlignment::Center);
            }
            g_batteryButton = MakeControlButton(L"BatteryButton", batteryIcon, g_batteryFlyout,
                                                [] { PopulateBatteryPanel(); });
            rightPanel.Children().Append(g_batteryButton);
