            dot.Background(MakeBrush(0xFF, acc.R, acc.G, acc.B));
            dot.BorderBrush(MakeBrush(0xCC, 0x10, 0x10, 0x12));
            dot.BorderThickness(Thickness{1, 1, 1, 1});
