        wuxc::StackPanel notificationsPanel;
        auto notificationsFlyout = MakeControlFlyout(
            L"NotificationsFlyoutRoot", notificationsPanel, kPanelWidth, true);
        notificationsFlyout.Opening([notificationsPanel, notificationsFlyout](auto&&, auto&&) {
            try {
                windows_notifications::g_expandedApps.clear();
                windows_notifications::g_expandedNotificationIds.clear();
                PopulateWindowsNotificationPanel(notificationsPanel, notificationsFlyout);
                windows_notifications::RefreshAsync([notificationsPanel, notificationsFlyout] {
                    try {
                        if (!notificationsFlyout || !notificationsFlyout.IsOpen()) return;
                        bool replyInProgress = false;
                        std::function<void(DependencyObject)> checkActiveInput = [&](DependencyObject node) {
                            if (!node || replyInProgress) return;
                            if (auto tb = node.try_as<wuxc::TextBox>()) {
                                if (!tb.Text().empty() || tb.FocusState() != FocusState::Unfocused) {
                                    replyInProgress = true;
                                    return;
                                }
                            }
                            int n = wuxm::VisualTreeHelper::GetChildrenCount(node);
                            for (int i = 0; i < n && !replyInProgress; ++i) {
                                checkActiveInput(wuxm::VisualTreeHelper::GetChild(node, i));
                            }
                        };
                        checkActiveInput(notificationsPanel);
                        if (!replyInProgress) {
                            PopulateWindowsNotificationPanel(notificationsPanel, notificationsFlyout);
                        }
                    } catch (...) {}
                });
            } catch (...) {}
        });
        notificationsFlyout.Closed([notificationsPanel](auto&&, auto&&) {
            windows_notifications::g_expandedApps.clear();
            windows_notifications::g_expandedNotificationIds.clear();
            try { if (notificationsPanel) notificationsPanel.Children().Clear(); } catch (...) {}
        });
        notificationsButton.Flyout(notificationsFlyout);
        AttachTopBarPressAnimation(notificationsButton, 0.88f);
